QT_ISI(26,{"4511":["(Ha Mim) hanya Allah sajalah yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Meem"]]],"4512":["(Diturunkan Alkitab ini) yaitu Alquran; lafal ayat ini menjadi Mubtada (dari Allah) menjadi Khabar dari Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["تَنزِيلُ","(The) revelation"],["ٱلْكِتَـٰبِ","(of) the Book"],["مِنَ","(is) from"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْحَكِيمِ","the All-Wise"]]],"4513":["(Kami tiada menciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan) dengan tujuan (yang benar) guna menunjukkan kekuasaan dan keesaan Kami (dan dalam waktu yang ditentukan) bagi kemusnahannya, yaitu hingga hari kiamat. (Dan orang-orang yang kafir; terhadap apa yang diperingatkan kepada mereka) berupa dipertakuti dengan siksa (mereka berpaling)",[["مَا","Not"],["خَلَقْنَا","We created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["وَمَا","and what"],["بَيْنَهُمَآ","(is) between both of them"],["إِلَّا","except"],["بِٱلْحَقِّ","in truth"],["وَأَجَلٍۢ","and (for) a term"],["مُّسَمًّۭى ۚ","appointed"],["وَٱلَّذِينَ","But those who"],["كَفَرُوا۟","disbelieve"],["عَمَّآ","from what"],["أُنذِرُوا۟","they are warned"],["مُعْرِضُونَ","(are) turning away"]]],"4514":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah oleh kalian kepadaku (tentang apa yang kalian seru) kalian sembah (selain Allah) yakni berhala-berhala; menjadi Maf'ul Awwal (perlihatkanlah kepadaku) ceritakanlah oleh kalian kepadaku (apakah yang telah mereka ciptakan) menjadi Maf'ul kedua (dari bumi ini) lafal ayat ini berkedudukan menjadi Maf'ul Tsani (atau adakah mereka berserikat) artinya, mempunyai andil (dalam) penciptaan (langit) bersama dengan Allah; lafal Am di sini bermakna Hamzah atau kata tanya yang menunjukkan makna ingkar. (Bawalah kepada-Ku Kitab yang sebelum ini) sebelum Alquran ini (atau peninggalan) yakni sisa-sisa (dari pengetahuan) yang ditemukan dari orang-orang terdahulu, yang hal tersebut membenarkan pengakuan kalian bahwa menyembah berhala itu dapat mendekatkan diri kalian kepada Allah? (jika kalian adalah orang-orang yang benar\") di dalam pengakuan kalian.",[["قُلْ","Say"],["أَرَءَيْتُم","Do you see"],["مَّا","what"],["تَدْعُونَ","you call"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["أَرُونِى","Show me"],["مَاذَا","what"],["خَلَقُوا۟","they have created"],["مِنَ","of"],["ٱلْأَرْضِ","the earth"],["أَمْ","or"],["لَهُمْ","for them"],["شِرْكٌۭ","(is) any share"],["فِى","in"],["ٱلسَّمَـٰوَٰتِ ۖ","the heavens"],["ٱئْتُونِى","Bring me"],["بِكِتَـٰبٍۢ","a book"],["مِّن","from"],["قَبْلِ","before"],["هَـٰذَآ","this"],["أَوْ","or"],["أَثَـٰرَةٍۢ","a trace"],["مِّنْ","of"],["عِلْمٍ","knowledge"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"4515":["(Dan siapakah) Istifham atau kata tanya ini menunjukkan makna negatif, yakni tidak ada seorang pun (yang lebih sesat daripada orang yang menyeru) yang menyembah (selain Allah) (yang tidak dapat memperkenankan doanya sampai hari kiamat) yang dimaksud adalah berhala-berhala yang menjadi sesembahan mereka, sedikit pun dan untuk selamanya tidak akan dapat memperkenankan apa yang diminta oleh para penyembahnya (dan mereka terhadap seruan para penyembahnya) yakni penyembahan yang dilakukan oleh para penyembahnya (lalai) karena berhala-berhala itu adalah benda mati dan tidak berakal.",[["وَمَنْ","And who"],["أَضَلُّ","(is) more astray"],["مِمَّن","than (he) who"],["يَدْعُوا۟","calls"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["مَن","who"],["لَّا","will not respond"],["يَسْتَجِيبُ","will not respond"],["لَهُۥٓ","to him"],["إِلَىٰ","until"],["يَوْمِ","(the) Day"],["ٱلْقِيَـٰمَةِ","(of) Resurrection"],["وَهُمْ","and they"],["عَن","of"],["دُعَآئِهِمْ","their calls"],["غَـٰفِلُونَ","(are) unaware"]]],"4516":["(Dan apabila manusia dikumpulkan pada hari kiamat niscaya sesembahan-sesembahan itu) berhala-berhala itu (terhadap mereka) yang menyembahnya (menjadi musuh mereka dan sesembahan-sesembahan itu terhadap penyembahan) para penyembahnya (ingkar) menyangkalnya.",[["وَإِذَا","And when"],["حُشِرَ","are gathered"],["ٱلنَّاسُ","the people"],["كَانُوا۟","they will be"],["لَهُمْ","for them"],["أَعْدَآءًۭ","enemies"],["وَكَانُوا۟","and they will be"],["بِعِبَادَتِهِمْ","of their worship"],["كَـٰفِرِينَ","deniers"]]],"4517":["(Dan apabila dibacakan kepada mereka) kepada penduduk Mekah (ayat-ayat Kami) yakni Alquran (yang menjelaskan) atau yang jelas keadaannya (berkatalah orang-orang yang ingkar) di antara mereka (kepada kebenaran) kepada Alquran (ketika kebenaran itu datang kepada mereka, \"Ini adalah sihir yang nyata\") jelas sihirnya.",[["وَإِذَا","And when"],["تُتْلَىٰ","are recited"],["عَلَيْهِمْ","to them"],["ءَايَـٰتُنَا","Our Verses"],["بَيِّنَـٰتٍۢ","clear"],["قَالَ","say"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لِلْحَقِّ","of the truth"],["لَمَّا","when"],["جَآءَهُمْ","it comes to them"],["هَـٰذَا","This"],["سِحْرٌۭ","(is) a magic"],["مُّبِينٌ","clear"]]],"4518":["(Bahkan) lafal Am di sini mempunyai makna sama dengan lafal Bal dan Hamzah yang menunjukkan makna ingkar (mereka mengatakan, \"Dia telah mengada-adakannya\") maksudnya, Alquran itu. (Katakanlah, \"Jika aku mengada-adakannya) umpamanya (maka kalian tiada mempunyai kuasa mempertahankan aku dari Allah) dari azab-Nya (barang sedikit pun) artinya, kalian tidak akan mampu menolak azab-Nya daripada diriku, jika Dia mengazab aku (Dia lebih mengetahui apa-apa yang kalian percakapkan tentangnya) tentang Alquran itu. (Cukuplah Dia) Yang Maha Tinggi (menjadi saksi antaraku dan antara kalian dan Dialah Yang Maha Pengampun) kepada orang yang bertobat (lagi Maha Penyayang\") kepada orang yang bertobat kepada-Nya; karena itu Dia tidak menyegerakan azab-Nya kepada mereka.",[["أَمْ","Or"],["يَقُولُونَ","they say"],["ٱفْتَرَىٰهُ ۖ","He has invented it"],["قُلْ","Say"],["إِنِ","If"],["ٱفْتَرَيْتُهُۥ","I have invented it"],["فَلَا","then not"],["تَمْلِكُونَ","you have power"],["لِى","for me"],["مِنَ","against"],["ٱللَّهِ","Allah"],["شَيْـًٔا ۖ","anything"],["هُوَ","He"],["أَعْلَمُ","knows best"],["بِمَا","of what"],["تُفِيضُونَ","you utter"],["فِيهِ ۖ","concerning it"],["كَفَىٰ","Sufficient is He"],["بِهِۦ","Sufficient is He"],["شَهِيدًۢا","(as) a Witness"],["بَيْنِى","between me"],["وَبَيْنَكُمْ ۖ","and between you"],["وَهُوَ","and He"],["ٱلْغَفُورُ","(is) the Oft-Forgiving"],["ٱلرَّحِيمُ","the Most Merciful"]]],"4519":["(Katakanlah, \"Aku bukanlah rasul yang pertama) atau untuk, pertama kalinya (di antara rasul-rasul) maksudnya aku bukanlah rasul yang pertama, karena telah, banyak rasul yang diutus sebelumku, maka mengapa kalian mendustakan aku (dan aku tidak mengetahui apa yang akan diperbuat terhadapku dan tidak pula terhadap kalian) di dunia ini; apakah aku akan diusir dari negeriku, atau apakah aku akan dibunuh sebagaimana nasib yang telah dialami oleh nabi-nabi sebelumku, atau adakalanya kalian melempariku dengan batu, atau barangkali kalian akan tertimpa azab sebagaimana apa yang dialami oleh kaum yang mendustakan sebelum kalian. (Tiada lain) tidak lain (aku hanyalah mengikuti apa yang diwahyukan kepadaku) yaitu Alquran, dan aku sama sekali belum pernah membuat-buat dari diriku sendiri (dan aku tidak lain hanyalah seorang pemberi peringatan yang menjelaskan\") yang jelas peringatannya.",[["قُلْ","Say"],["مَا","Not"],["كُنتُ","I am"],["بِدْعًۭا","a new (one)"],["مِّنَ","among"],["ٱلرُّسُلِ","the Messengers"],["وَمَآ","and not"],["أَدْرِى","I know"],["مَا","what"],["يُفْعَلُ","will be done"],["بِى","with me"],["وَلَا","and not"],["بِكُمْ ۖ","with you"],["إِنْ","Not"],["أَتَّبِعُ","I follow"],["إِلَّا","but"],["مَا","what"],["يُوحَىٰٓ","is revealed"],["إِلَىَّ","to me"],["وَمَآ","and not"],["أَنَا۠","I am"],["إِلَّا","but"],["نَذِيرٌۭ","a warner"],["مُّبِينٌۭ","clear"]]],"4520":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah kepadaku, bagaimana pendapat kalian (jika ia) yakni jika Alquran itu (datang dari sisi Allah padahal kalian mengingkarinya) lafal Wakafartum Bihi merupakan jumlah Haliyah (dan seorang saksi dari Bani Israel mengakui kebenaran) yaitu Abdullah bin Salam (yang serupa dengan yang tersebut dalam Alquran) bahwasanya Alquran itu datang dari sisi Allah (lalu dia beriman) yakni saksi tersebut beriman kepada Alquran (sedangkan kalian menyombongkan diri) tidak mau beriman kepada Alquran. Sedangkan Jawab Syaratnya ialah 'Bukankah kalau demikian kalian adalah orang-orang yang lalim', hal ini disimpulkan dari pengertian ayat selanjutnya, ('Sesungguhnya Allah tiada memberi petunjuk kepada orang-orang yang lalim.\")",[["قُلْ","Say"],["أَرَءَيْتُمْ","Do you see"],["إِن","if"],["كَانَ","it is"],["مِنْ","from Allah"],["عِندِ","from Allah"],["ٱللَّهِ","from Allah"],["وَكَفَرْتُم","and you disbelieve"],["بِهِۦ","in it"],["وَشَهِدَ","and testifies"],["شَاهِدٌۭ","a witness"],["مِّنۢ","from"],["بَنِىٓ","(the) Children of Israel"],["إِسْرَٰٓءِيلَ","(the) Children of Israel"],["عَلَىٰ","to"],["مِثْلِهِۦ","(the) like thereof"],["فَـَٔامَنَ","then he believed"],["وَٱسْتَكْبَرْتُمْ ۖ","while you are arrogant"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the people"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"4521":["(Dan orang-orang kafir berkata kepada orang-orang yang beriman) sehubungan dengan perihal orang-orang yang beriman, (\"Kalau sekiranya beriman) kepada Alquran itu (adalah suatu yang baik, tentulah mereka tiada mendahului kami beriman kepadanya. Dan karena mereka tidak mendapat petunjuk) yaitu orang-orang yang mengatakan demikian (dengannya) tidak mendapat petunjuk dari Alquran (maka mereka akan berkata, 'Ini) Alquran ini (adalah dusta) maksudnya, kebohongan (yang lama.'\")",[["وَقَالَ","And say"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لِلَّذِينَ","of those who"],["ءَامَنُوا۟","believe"],["لَوْ","If"],["كَانَ","it had been"],["خَيْرًۭا","good"],["مَّا","not"],["سَبَقُونَآ","they (would) have preceded us"],["إِلَيْهِ ۚ","to it"],["وَإِذْ","And when"],["لَمْ","not"],["يَهْتَدُوا۟","they (are) guided"],["بِهِۦ","by it"],["فَسَيَقُولُونَ","they say"],["هَـٰذَآ","This"],["إِفْكٌۭ","(is) a lie"],["قَدِيمٌۭ","ancient"]]],"4522":["(Dan sebelumnya) sebelum Alquran (telah ada kitab Musa) kitab Taurat (sebagai petunjuk dan rahmat) bagi orang-orang yang beriman kepadanya; lafal Imaaman dan Rahmatan keduanya merupakan Hal. (Dan ini) yaitu Alquran (adalah Kitab yang membenarkan) kitab-kitab sebelumnya (dalam bahasa Arab) menjadi Hal dari Dhamir yang terkandung di dalam lafal Mushaddiquun (untuk memberi peringatan kepada orang-orang yang lalim) yakni orang-orang musyrik Mekah (dan) dia adalah (memberi kabar gembira kepada orang-orang yang berbuat baik) yakni orang-orang yang beriman.",[["وَمِن","And before it"],["قَبْلِهِۦ","And before it"],["كِتَـٰبُ","(was the) Scripture"],["مُوسَىٰٓ","(of) Musa"],["إِمَامًۭا","(as) a guide"],["وَرَحْمَةًۭ ۚ","and a mercy"],["وَهَـٰذَا","And this"],["كِتَـٰبٌۭ","(is) a Book"],["مُّصَدِّقٌۭ","confirming"],["لِّسَانًا","(in) language"],["عَرَبِيًّۭا","Arabic"],["لِّيُنذِرَ","to warn"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","do wrong"],["وَبُشْرَىٰ","and (as) glad tidings"],["لِلْمُحْسِنِينَ","for the good-doers"]]],"4523":["(Sesungguhnya orang-orang yang mengatakan, \"Rabb kami ialah Allah,\" kemudian mereka beristiqamah) atau menetapi ketaatan (maka tidak ada kekhawatiran terhadap mereka dan mereka tiada pula berduka cita.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["قَالُوا۟","say"],["رَبُّنَا","Our Lord"],["ٱللَّهُ","(is) Allah"],["ثُمَّ","then"],["ٱسْتَقَـٰمُوا۟","remain firm"],["فَلَا","then no"],["خَوْفٌ","fear"],["عَلَيْهِمْ","on them"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"4524":["(Mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya) lafal Khaalidiina Fiihaa menjadi Hal atau kata keterangan keadaan (sebagai balasan) menjadi Mashdar yang dinashabkan oleh Fi'ilnya yang diperkirakan keberadaannya, yaitu lafal Yujzauna; artinya: mereka diberi pahala sebagai balasan (atas apa yang telah mereka kerjakan.)",[["أُو۟لَـٰٓئِكَ","Those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَنَّةِ","(of) Paradise"],["خَـٰلِدِينَ","abiding forever"],["فِيهَا","therein"],["جَزَآءًۢ","a reward"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"4525":["(Kami perintahkan kepada manusia supaya berbuat baik kepada dua orang ibu bapaknya) menurut suatu qiraat lafal Ihsaan dibaca Husnan; maksudnya: Kami perintahkan manusia supaya berbuat baik kepada kedua orang tuanya. Lafal Ihsaanan adalah Mashdar yang dinashabkan oleh Fi'ilnya yang diperkirakan keberadaannya; demikian pula penjabarannya bila dibaca Husnan (ibunya mengandungnya dengan susah payah dan melahirkannya dengan susah pula) artinya penuh dengan susah payah. (Mengandungnya sampai menyapihnya) dari penyusuannya (adalah tiga puluh bulan) yakni dalam masa enam bulan sebagai batas yang paling minim bagi mengandung, sedangkan sisanya dua puluh empat bulan, yaitu lama masa penyusuan yang maksimal. Menurut suatu pendapat disebutkan bahwa jika sang ibu mengandungnya selama enam bulan atau sembilan bulan, maka sisanya adalah masa penyusuan (sehingga) menunjukkan makna Ghayah bagi jumlah yang diperkirakan keberadaannya, yakni dia hidup sehingga (apabila dia telah dewasa) yang dimaksud dengan pengertian dewasa ialah kekuatan fisik dan akal serta inteligensinya telah sempurna yaitu sekitar usia tiga puluh tiga tahun atau tiga puluh tahun (dan umurnya sampai empat puluh tahun) yakni genap mencapai empat puluh tahun, dalam usia ini seseorang telah mencapai batas maksimal kedewasaannya (ia berdoa, \"Ya Rabbku!) dan seterusnya. Ayat ini diturunkan berkenaan dengan Abu Bakar Ash-Shiddiq, yaitu sewaktu usianya mencapai empat puluh tahun sesudah dua tahun Nabi saw. diangkat menjadi rasul. Lalu ia beriman kepada Nabi saw. lalu beriman pula kedua orang tuanya, lalu menyusul anaknya yang bernama Abdurrahman, lalu cucunya yang bernama Atiq (Tunjukilah aku) maksudnya berilah ilham (untuk mensyukuri nikmat Engkau yang telah Engkau berikan) nikmat tersebut (kepadaku dan kepada ibu bapakku) yaitu nikmat tauhid (dan supaya aku dapat berbuat amal saleh yang Engkau ridai) maka Abu Bakar segera memerdekakan sembilan orang hamba sahaya yang beriman; mereka disiksa karena memeluk agama Allah (berilah kebaikan kepadaku dengan memberi kebaikan kepada cucuku) maka semua anak cucunya adalah orang-orang yang beriman. (Sesungguhnya aku bertobat kepada Engkau dan sesungguhnya aku termasuk orang-orang yang berserah diri.\")",[["وَوَصَّيْنَا","And We have enjoined"],["ٱلْإِنسَـٰنَ","(on) man"],["بِوَٰلِدَيْهِ","to his parents"],["إِحْسَـٰنًا ۖ","kindness"],["حَمَلَتْهُ","Carried him"],["أُمُّهُۥ","his mother"],["كُرْهًۭا","(with) hardship"],["وَوَضَعَتْهُ","and gave birth to him"],["كُرْهًۭا ۖ","(with) hardship"],["وَحَمْلُهُۥ","And (the) bearing of him"],["وَفِصَـٰلُهُۥ","and (the) weaning of him"],["ثَلَـٰثُونَ","(is) thirty"],["شَهْرًا ۚ","month(s)"],["حَتَّىٰٓ","until"],["إِذَا","when"],["بَلَغَ","he reaches"],["أَشُدَّهُۥ","his maturity"],["وَبَلَغَ","and reaches"],["أَرْبَعِينَ","forty"],["سَنَةًۭ","year(s)"],["قَالَ","he says"],["رَبِّ","My Lord"],["أَوْزِعْنِىٓ","grant me (the) power"],["أَنْ","that"],["أَشْكُرَ","I may be grateful"],["نِعْمَتَكَ","(for) Your favor"],["ٱلَّتِىٓ","which"],["أَنْعَمْتَ","You have bestowed"],["عَلَىَّ","upon me"],["وَعَلَىٰ","and upon"],["وَٰلِدَىَّ","my parents"],["وَأَنْ","and that"],["أَعْمَلَ","I do"],["صَـٰلِحًۭا","righteous (deeds)"],["تَرْضَىٰهُ","which please You"],["وَأَصْلِحْ","and make righteous"],["لِى","for me"],["فِى","among"],["ذُرِّيَّتِىٓ ۖ","my offspring"],["إِنِّى","indeed"],["تُبْتُ","I turn"],["إِلَيْكَ","to You"],["وَإِنِّى","and indeed, I am"],["مِنَ","of"],["ٱلْمُسْلِمِينَ","those who submit"]]],"4526":["(Mereka itulah) maksudnya yang mengatakan ucapan ini, yaitu Abu Bakar dan lain-lainnya (orang-orang yang Kami terima dari mereka amal baik) lafal Ahsana di sini bermakna Hasana (yang telah mereka kerjakan dan Kami ampuni kesalahan-kesalahan mereka, bersama penghuni-penghuni surga) lafal Fii Ash-haabil Jannah berkedudukan menjadi Hal atau kata keterangan keadaan maksudnya, mereka digolongkan ke dalam para penghuni surga (sebagai janji yang benar yang telah dijanjikan kepada mereka) yaitu sebagaimana yang telah diungkapkan dalam ayat yang lain, yakni firman-Nya, \"Allah menjanjikan kepada orang-orang yang mukmin lelaki dan perempuan, (akan mendapat) surga.\" (Q.S. At-Taubah, 72).",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones"],["نَتَقَبَّلُ","We will accept"],["عَنْهُمْ","from them"],["أَحْسَنَ","(the) best"],["مَا","(of) what"],["عَمِلُوا۟","they did"],["وَنَتَجَاوَزُ","and We will overlook"],["عَن","[from]"],["سَيِّـَٔاتِهِمْ","their evil deeds"],["فِىٓ","among"],["أَصْحَـٰبِ","(the) companions"],["ٱلْجَنَّةِ ۖ","(of) Paradise"],["وَعْدَ","A promise"],["ٱلصِّدْقِ","true"],["ٱلَّذِى","which"],["كَانُوا۟","they were"],["يُوعَدُونَ","promised"]]],"4527":["(Dan orang yang berkata kepada dua orang ibu bapaknya) menurut suatu qiraat dibaca Idgham dimaksud adalah jenisnya (\"Cis) dapat dibaca Uffin atau Uffan, merupakan Mashdar yang artinya, busuk dan buruk (bagi kamu keduanya) yakni aku marah kepada kamu berdua (apakah kamu keduanya memperingatkan kepadaku) menurut qiraat lain dibaca Ata'idannii, dengan diidgamkan (bahwa aku akan dibangkitkan) dari kubur (padahal sungguh telah berlalu beberapa umat) yakni generasi-generasi (sebelumku\") dan ternyata mereka tidak dikeluarkan dari kuburnya (lalu kedua ibu bapaknya itu memohon pertolongan kepada Allah) meminta pertolongan supaya anaknya sadar dan bertobat, seraya mengatakan, bahwa apabila kamu tidak mau bertobat, (\"Celakalah kamu) binasalah kamu (berimanlah) kepada adanya hari berbangkit. (Sesungguhnya janji Allah adalah benar.\" Lalu dia berkata: \"Ini tidak lain) maksudnya ucapan yang menyatakan adanya hari berbangkit ini (hanyalah dongengan orang-orang dahulu belaka\") artinya, kedustaan-kedustaan mereka.",[["وَٱلَّذِى","But the one who"],["قَالَ","says"],["لِوَٰلِدَيْهِ","to his parents"],["أُفٍّۢ","Uff"],["لَّكُمَآ","to both of you"],["أَتَعِدَانِنِىٓ","Do you promise me"],["أَنْ","that"],["أُخْرَجَ","I will be brought forth"],["وَقَدْ","and have already passed away"],["خَلَتِ","and have already passed away"],["ٱلْقُرُونُ","the generations"],["مِن","before me"],["قَبْلِى","before me"],["وَهُمَا","And they both"],["يَسْتَغِيثَانِ","seek help"],["ٱللَّهَ","(of) Allah"],["وَيْلَكَ","Woe to you"],["ءَامِنْ","Believe"],["إِنَّ","Indeed"],["وَعْدَ","(the) Promise"],["ٱللَّهِ","(of) Allah"],["حَقٌّۭ","(is) true"],["فَيَقُولُ","But he says"],["مَا","Not"],["هَـٰذَآ","(is) this"],["إِلَّآ","but"],["أَسَـٰطِيرُ","(the) stories"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"4528":["(Mereka itulah orang-orang yang telah pasti) telah ditentukan (ketetapan atas mereka) yakni ketetapan azab (bersama umat-umat yang telah berlalu sebelum mereka dari jin dan manusia. Sesungguhnya mereka adalah orang-orang yang merugi.)",[["أُو۟لَـٰٓئِكَ","Those "],["ٱلَّذِينَ","(are) the ones"],["حَقَّ","(has) proved true"],["عَلَيْهِمُ","against them"],["ٱلْقَوْلُ","the word"],["فِىٓ","among"],["أُمَمٍۢ","nations"],["قَدْ","(that) already passed away"],["خَلَتْ","(that) already passed away"],["مِن","before them"],["قَبْلِهِم","before them"],["مِّنَ","of"],["ٱلْجِنِّ","(the) jinn"],["وَٱلْإِنسِ ۖ","and the men"],["إِنَّهُمْ","Indeed, they"],["كَانُوا۟","are"],["خَـٰسِرِينَ","(the) losers"]]],"4529":["(Dan bagi masing-masing mereka) bagi masing-masing dari orang mukmin dan orang kafir (derajat), derajat orang-orang yang beriman memperoleh kedudukan yang tinggi di dalam surga, sedangkan derajat orang-orang kafir memperoleh kedudukan di dasar neraka (menurut apa yang telah mereka kerjakan) berdasar pada amal ketaatan bagi orang-orang mukmin dan kemaksiatan bagi orang-orang kafir (dan agar Dia mencukupkan bagi mereka) yakni Allah mencukupkan bagi mereka; menurut suatu qiraat dibaca Walinuwaffiyahum (pekerjaan-pekerjaan mereka) maksudnya balasannya (sedangkan mereka tiada dirugikan) barang sedikit pun, misalkan untuk orang-orang mukmin dikurangi dan untuk orang-orang kafir ditambahi.",[["وَلِكُلٍّۢ","And for all"],["دَرَجَـٰتٌۭ","(are) degrees"],["مِّمَّا","for what"],["عَمِلُوا۟ ۖ","they did"],["وَلِيُوَفِّيَهُمْ","and that He may fully compensate them"],["أَعْمَـٰلَهُمْ","(for) their deeds"],["وَهُمْ","and they"],["لَا","will not be wronged"],["يُظْلَمُونَ","will not be wronged"]]],"4530":["(Dan ingatlah hari ketika orang-orang kafir dihadapkan ke neraka) neraka diperlihatkan-Nya kepada mereka, kemudian dikatakan kepada mereka, (\"Kalian telah menghabiskan) dapat dibaca Adzhabtum, A-adzhabtum atau Adzhabtum (rezeki kalian yang baik) dengan cara menghambur-hamburkannya demi kelezatan kalian (dalam kehidupan dunia kalian saja dan kalian telah bersenang-senang) bersuka-ria (dengannya, maka pada hari ini kalian dibalasi dengan azab yang menghinakan) atau azab yang mengerikan (karena kalian telah menyombongkan diri yaitu bersikap takabur (di muka bumi tanpa hak dan karena kalian telah fasik\") atau berbuat kefasikan padanya, maka karena itu kalian diazab.",[["وَيَوْمَ","And (the) Day"],["يُعْرَضُ","will be exposed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["عَلَى","to"],["ٱلنَّارِ","the Fire"],["أَذْهَبْتُمْ","You exhausted"],["طَيِّبَـٰتِكُمْ","your good things"],["فِى","in"],["حَيَاتِكُمُ","your life"],["ٱلدُّنْيَا","(of) the world"],["وَٱسْتَمْتَعْتُم","and you took your pleasures"],["بِهَا","therein"],["فَٱلْيَوْمَ","So today"],["تُجْزَوْنَ","you will be recompensed"],["عَذَابَ","(with) a punishment"],["ٱلْهُونِ","humiliating"],["بِمَا","because"],["كُنتُمْ","you were"],["تَسْتَكْبِرُونَ","arrogant"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بِغَيْرِ","without"],["ٱلْحَقِّ","[the] right"],["وَبِمَا","and because"],["كُنتُمْ","you were"],["تَفْسُقُونَ","defiantly disobedient"]]],"4531":["(Dan ingatlah saudara kaum Ad) yakni Nabi Hud a.s. (yaitu ketika) mulai lafal Idz dan seterusnya menjadi Badal Isytimal (dia memberi peringatan kepada kaumnya) maksudnya, mempertakuti mereka (di Al-Ahqaf) nama sebuah lembah tempat tinggal mereka yang terletak di negeri Yaman (dan sesungguhnya telah terdahulu beberapa orang pemberi peringatan) beberapa orang rasul (sebelumnya dan sesudahnya) sebelum Nabi Hud datang dan sesudahnya, kepada kaumnya masing-masing seraya mengatakan, (\"Janganlah kalian menyembah selain Allah) jumlah Waqad Khalat merupakan jumlah Mu'taridhah, atau kalimat sisipan (sesungguhnya aku khawatir kalian) jika kalian menyembah kepada selain Allah (akan ditimpa azab hari yang besar.\")",[["۞ وَٱذْكُرْ","And mention"],["أَخَا","(the) brother"],["عَادٍ","(of) Aad"],["إِذْ","when"],["أَنذَرَ","he warned"],["قَوْمَهُۥ","his people"],["بِٱلْأَحْقَافِ","in the Al-Ahqaf "],["وَقَدْ","and had already passed away"],["خَلَتِ","and had already passed away"],["ٱلنُّذُرُ","[the] warners"],["مِنۢ","before him"],["بَيْنِ","before him"],["يَدَيْهِ","before him"],["وَمِنْ","and after him"],["خَلْفِهِۦٓ","and after him"],["أَلَّا","That not"],["تَعْبُدُوٓا۟","you worship"],["إِلَّا","except"],["ٱللَّهَ","Allah"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["عَلَيْكُمْ","for you"],["عَذَابَ","a punishment"],["يَوْمٍ","(of) a Day"],["عَظِيمٍۢ","Great"]]],"4532":["(Mereka menjawab, \"Apakah kamu datang kepada kami untuk memalingkan kami dari menyembah tuhan-tuhan kami?) maksudnya kamu datang untuk memalingkan kami daripada menyembahnya. (Maka datangkanlah kepada kami azab yang telah kamu ancamkan kepada kami) bahwa jika kami menyembahnya pasti kami tertimpa azab (jika kamu termasuk orang-orang yang benar\") bahwasanya azab itu benar-benar menimpa kami.",[["قَالُوٓا۟","They said"],["أَجِئْتَنَا","Have you come to us"],["لِتَأْفِكَنَا","to turn us away"],["عَنْ","from"],["ءَالِهَتِنَا","our gods"],["فَأْتِنَا","Then bring us"],["بِمَا","what"],["تَعِدُنَآ","you threaten us"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"4533":["(Ia berkata) Nabi Hud berkata, (\"Sesungguhnya pengetahuan tentang itu hanya pada sisi Allah) artinya hanya Dialah yang mengetahui kapan azab itu menimpa kalian (dan aku hanya menyampaikan kepada kalian apa yang aku diutus dengan membawanya) untuk disampaikan kepada kalian (tetapi aku lihat kalian adalah kaum yang bodoh\") karena kalian meminta supaya azab didatangkan dengan segera.",[["قَالَ","He said"],["إِنَّمَا","Only"],["ٱلْعِلْمُ","the knowledge"],["عِندَ","(is) with Allah"],["ٱللَّهِ","(is) with Allah"],["وَأُبَلِّغُكُم","and I convey to you"],["مَّآ","what"],["أُرْسِلْتُ","I am sent"],["بِهِۦ","with it"],["وَلَـٰكِنِّىٓ","but"],["أَرَىٰكُمْ","I see you"],["قَوْمًۭا","a people"],["تَجْهَلُونَ","ignorant"]]],"4534":["(Maka tatkala mereka melihat azab itu) (berupa awan) atau mendung yang muncul di cakrawala langit (menuju ke lembah-lembah mereka, berkatalah mereka, \"Inilah awan yang akan menurunkan hujan kepada kami) maksudnya, awan yang membawa hujan buat kami, Allah swt. berfirman, ('Bahkan itulah azab yang kalian minta supaya datang dengan segera) maksudnya, azab itu yang kalian minta agar disegerakan datangnya (yaitu berupa angin) lafal Riihun menjadi Badal dari lafal Maa (yang mengandung azab yang pedih) yang menyakitkan.",[["فَلَمَّا","Then when"],["رَأَوْهُ","they saw it"],["عَارِضًۭا","(as) a cloud"],["مُّسْتَقْبِلَ","approaching"],["أَوْدِيَتِهِمْ","their valleys"],["قَالُوا۟","they said"],["هَـٰذَا","This"],["عَارِضٌۭ","(is) a cloud"],["مُّمْطِرُنَا ۚ","bringing us rain"],["بَلْ","Nay"],["هُوَ","it"],["مَا","(is) what"],["ٱسْتَعْجَلْتُم","you were asking it to be hastened"],["بِهِۦ ۖ","you were asking it to be hastened"],["رِيحٌۭ","a wind"],["فِيهَا","in it"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"]]],"4535":["(Yang menghancurkan) yang membinasakan (segala sesuatu) yang dilewatinya (dengan perintah Rabbnya) dengan seizin-Nya; maksudnya angin itu dapat membinasakan segala sesuatu yang dikehendaki-Nya untuk dibinasakan. Akhirnya binasalah kaum laki-laki dan wanita serta anak-anak mereka berikut dengan harta bendanya; semuanya terbawa terbang oleh angin yang besar itu antara langit dan bumi dalam keadaan tercabik-cabik. Kini yang tertinggal dalam keadaan selamat adalah Nabi Hud beserta orang-orang yang beriman kepadanya (maka jadilah mereka tidak ada yang kelihatan lagi kecuali bekas-bekas tempat tinggal mereka.' Demikianlah) sebagaimana Kami memberikan balasan kepada kaum Hud (Kami memberi balasan kepada kaum yang berdosa\") selain mereka.",[["تُدَمِّرُ","Destroying"],["كُلَّ","every"],["شَىْءٍۭ","thing"],["بِأَمْرِ","by (the) command"],["رَبِّهَا","(of) its Lord"],["فَأَصْبَحُوا۟","Then they became (such)"],["لَا","not"],["يُرَىٰٓ","is seen"],["إِلَّا","except"],["مَسَـٰكِنُهُمْ ۚ","their dwellings"],["كَذَٰلِكَ","Thus"],["نَجْزِى","We recompense"],["ٱلْقَوْمَ","the people"],["ٱلْمُجْرِمِينَ","[the] criminals"]]],"4536":["(Dan sesungguhnya Kami telah meneguhkan kedudukan mereka dalam hal-hal) (yang belum pernah) lafal In di sini dapat dikatakan sebagai In Nafiyah atau In Zaidah (Kami meneguhkan kedudukan kalian) hai penduduk Mekah (dalam hal itu) dalam hal kekuatan dan banyaknya harta benda (dan Kami telah memberikan kepada mereka pendengaran) lafal Sam'an bermakna Asmaa'an bermakna jamak (dan penglihatan serta hati) atau kalbu (tetapi pendengaran, penglihatan dan hati mereka itu tidak berguna sedikit jua pun bagi mereka) maksudnya, hal-hal tersebut sama sekali tidak dapat memberikan manfaat sedikit pun buat diri mereka; lafal Min di sini adalah Zaidah (karena) lafal Idz adalah yang dima'mulkan oleh lafal Aghnaa kemudian diberlakukan sebagai makna Ta'lil (mereka selalu mengingkari ayat-ayat Allah) yaitu hujah-hujah-Nya yang nyata (dan turunlah) yaitu menimpalah (kepada mereka apa yang dahulu selalu mereka memperolok-olokkannya) yaitu azab yang dahulu mereka suka memperolok-olokkannya.",[["وَلَقَدْ","And certainly"],["مَكَّنَّـٰهُمْ","We had established them"],["فِيمَآ","in what"],["إِن","not"],["مَّكَّنَّـٰكُمْ","We have established you"],["فِيهِ","in it"],["وَجَعَلْنَا","and We made"],["لَهُمْ","for them"],["سَمْعًۭا","hearing"],["وَأَبْصَـٰرًۭا","and vision"],["وَأَفْـِٔدَةًۭ","and hearts"],["فَمَآ","But not"],["أَغْنَىٰ","availed"],["عَنْهُمْ","them"],["سَمْعُهُمْ","their hearing"],["وَلَآ","and not"],["أَبْصَـٰرُهُمْ","their vision"],["وَلَآ","and not"],["أَفْـِٔدَتُهُم","their hearts"],["مِّن","any"],["شَىْءٍ","thing"],["إِذْ","when"],["كَانُوا۟","they were"],["يَجْحَدُونَ","rejecting"],["بِـَٔايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["وَحَاقَ","and enveloped"],["بِهِم","them"],["مَّا","what"],["كَانُوا۟","they used to"],["بِهِۦ","[at it]"],["يَسْتَهْزِءُونَ","ridicule"]]],"4537":["(Dan sesungguhnya Kami telah membinasakan negeri-negeri di sekitar kalian) yakni penduduk-penduduknya, seperti kaum Tsamud, kaum Ad dan kaum Luth (dan Kami telah mendatangkan tanda-tanda kebesaran Kami berulang-ulang) maksudnya Kami telah mengulang-ulang hujah-hujah Kami yang nyata (supaya mereka kembali.)",[["وَلَقَدْ","And certainly"],["أَهْلَكْنَا","We destroyed"],["مَا","what"],["حَوْلَكُم","surrounds you"],["مِّنَ","of"],["ٱلْقُرَىٰ","the towns"],["وَصَرَّفْنَا","and We have diversified"],["ٱلْـَٔايَـٰتِ","the Signs"],["لَعَلَّهُمْ","that they may"],["يَرْجِعُونَ","return"]]],"4538":["(Maka mengapa tidak) atau kenapa tidak (menolong mereka) dengan cara menolak azab dari diri mereka (sesembahan-sesembahan selain Allah yang mereka jadikan) selain dari Allah (sebagai taqarrub) untuk mendekatkan diri mereka kepada Allah (dan sebagai tuhan-tuhan) di samping Allah, yaitu berupa berhala-berhala. Maf'ul pertama dari lafal Ittakhadza adalah Dhamir yang tidak disebutkan yang kembali kepada Isim Maushul, yaitu lafal Hum, sedangkan Maf'ul keduanya adalah lafal Qurbaanan, dan lafal Aalihatan sebagai Badal dari lafal Qurbaanan. (Bahkan tuhan-tuhan itu telah lenyap) yakni pergi (dari mereka) sewaktu azab itu datang menimpa mereka. (Itulah) yakni pengambilan mereka terhadap berhala-berhala sebagai tuhan-tuhan untuk mendekatkan diri kepada Allah (akibat kebohongan mereka) kedustaan mereka (dan apa yang dahulu mereka ada-adakan) yang dahulu mereka buat-buat. Maa adalah Mashdariyah atau Maushulah, sedangkan Dhamir yang kembali kepadanya tidak disebutkan yaitu lafal Fiihi; lengkapnya: Wa Maa Kaanuu Fiihi Yaftaruuna.",[["فَلَوْلَا","Then why (did) not"],["نَصَرَهُمُ","help them"],["ٱلَّذِينَ","those whom"],["ٱتَّخَذُوا۟","they had taken"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["قُرْبَانًا","gods as a way of approach"],["ءَالِهَةًۢ ۖ","gods as a way of approach"],["بَلْ","Nay"],["ضَلُّوا۟","they were lost"],["عَنْهُمْ ۚ","from them"],["وَذَٰلِكَ","And that"],["إِفْكُهُمْ","(was) their falsehood"],["وَمَا","and what"],["كَانُوا۟","they were"],["يَفْتَرُونَ","inventing"]]],"4539":["(Dan) ingatlah (ketika Kami hadapkan) Kami cenderungkan (kepadamu serombongan jin) yaitu jin Nashibin dari negeri Yaman atau Jin Nainawi, jumlah mereka ada tujuh atau sembilan jin. Nabi saw. ketika itu berada di lembah Nakhl sedang melakukan salat Subuh berjemaah dengan para sahabatnya. Demikianlah menurut hadis yang diriwayatkan oleh Bukhari dan Muslim (yang mendengarkan Alquran, maka tatkala mereka menghadiri pembacaannya, lalu mereka berkata) sebagian dari mereka berkata kepada sebagian yang lain, (\"Diamlah kalian\") untuk mendengarkan bacaannya. (Ketika pembacaan telah selesai) ketika nabi selesai membaca Alquran (mereka kembali) pulang kembali (kepada kaumnya untuk memberi peringatan) artinya, mereka kembali setelah mendengarkan Alquran kepada kaumnya sebagai pemberi peringatan akan datangnya azab jika mereka tidak beriman kepada Nabi. Mereka sebelum itu pemeluk agama Yahudi, lalu setelah mendengarkan bacaan Alquran mereka masuk Islam.",[["وَإِذْ","And when"],["صَرَفْنَآ","We directed"],["إِلَيْكَ","to you"],["نَفَرًۭا","a party"],["مِّنَ","of"],["ٱلْجِنِّ","the jinn"],["يَسْتَمِعُونَ","listening"],["ٱلْقُرْءَانَ","(to) the Quran"],["فَلَمَّا","And when"],["حَضَرُوهُ","they attended it"],["قَالُوٓا۟","they said"],["أَنصِتُوا۟ ۖ","Listen quietly"],["فَلَمَّا","And when"],["قُضِىَ","it was concluded"],["وَلَّوْا۟","they turned back"],["إِلَىٰ","to"],["قَوْمِهِم","their people"],["مُّنذِرِينَ","(as) warners"]]],"4540":["(Mereka berkata, \"Hai kaum kami, sesungguhnya kami telah mendengarkan Kitab) yakni Alquran (yang telah diturunkan sesudah Musa yang membenarkan kitab-kitab sebelumnya) seperti kitab Taurat (lagi memimpin kepada kebenaran) kepada agama Islam (dan kepada jalan yang lurus) yaitu tuntunan agama Islam.",[["قَالُوا۟","They said"],["يَـٰقَوْمَنَآ","O our people"],["إِنَّا","Indeed, we"],["سَمِعْنَا","[we] have heard"],["كِتَـٰبًا","a Book"],["أُنزِلَ","revealed"],["مِنۢ","after"],["بَعْدِ","after"],["مُوسَىٰ","Musa"],["مُصَدِّقًۭا","confirming"],["لِّمَا","what"],["بَيْنَ","(was) before it"],["يَدَيْهِ","(was) before it"],["يَهْدِىٓ","guiding"],["إِلَى","to"],["ٱلْحَقِّ","the truth"],["وَإِلَىٰ","and to"],["طَرِيقٍۢ","a Path"],["مُّسْتَقِيمٍۢ","Straight"]]],"4541":["(Hai kaum kami! Terimalah seruan orang yang menyeru kepada Allah) yakni seruan iman yang dilakukan oleh Nabi Muhammad saw. (dan berimanlah kepada-Nya, niscaya Dia akan mengampuni) Allah pasti akan mengampuni (dosa-dosa kalian) sebagian dari dosa-dosa kalian, diartikan demikian karena di antara dosa-dosa itu terdapat jenis dosa yang tidak dapat diampuni melainkan setelah mendapat kerelaan dari orang yang dianiaya oleh orang yang bersangkutan (dan melindungi kalian dari azab yang pedih) atau azab yang menyakitkan.",[["يَـٰقَوْمَنَآ","O our people"],["أَجِيبُوا۟","Respond"],["دَاعِىَ","(to the) caller"],["ٱللَّهِ","(of) Allah"],["وَءَامِنُوا۟","and believe"],["بِهِۦ","in him"],["يَغْفِرْ","He will forgive"],["لَكُم","for you"],["مِّن","of"],["ذُنُوبِكُمْ","your sins"],["وَيُجِرْكُم","and will protect you"],["مِّنْ","from"],["عَذَابٍ","a punishment"],["أَلِيمٍۢ","painful"]]],"4542":["(Dan orang yang tidak menerima seruan orang yang menyeru kepada Allah maka dia tidak akan dapat melepaskan diri dari azab Allah di muka bumi) artinya ia tidak akan dapat melemahkan Allah dengan cara lari dari-Nya sehingga ia selamat dari azab-Nya (dan tidak ada baginya) yakni bagi orang yang tidak menerima seruan itu (selain Allah) (pelindung-pelindung) yang dapat menolak azab Allah daripada dirinya. (dalam kesesatan yang nyata\") jelas sesatnya.",[["وَمَن","And whoever"],["لَّا","(does) not"],["يُجِبْ","respond"],["دَاعِىَ","(to the) caller"],["ٱللَّهِ","(of) Allah"],["فَلَيْسَ","then not"],["بِمُعْجِزٍۢ","he can escape"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَلَيْسَ","and not"],["لَهُۥ","for him"],["مِن","besides Him"],["دُونِهِۦٓ","besides Him"],["أَوْلِيَآءُ ۚ","protectors"],["أُو۟لَـٰٓئِكَ","Those"],["فِى","(are) in"],["ضَلَـٰلٍۢ","error"],["مُّبِينٍ","clear"]]],"4543":["(Dan apakah mereka tidak memperhatikan) atau apakah orang-orang yang ingkar kepada hari berbangkit itu tidak mengetahui (bahwa sesungguhnya Allah yang menciptakan langit dan bumi dan Dia tidak merasa payah karena menciptakannya) artinya, Dia mampu menciptakan kesemuanya dengan mudah (kuasa) lafal Biqaadirin menjadi Khabar dari Anna, kemudian ditambahkan huruf Ba, karena pengertian ayat ini sejajar kekuatannya dengan kalimat Alaisallaahu Biqaadirin, artinya; Bukankah Allah kuasa (menghidupkan orang-orang mati? Ya) Dia Maha Kuasa untuk menghidupkan orang-orang mati (sesungguhnya Dia Maha Kuasa atas segala sesuatu.)",[["أَوَلَمْ","Do not"],["يَرَوْا۟","they see"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["ٱلَّذِى","(is) the One Who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["وَلَمْ","and (was) not"],["يَعْىَ","tired"],["بِخَلْقِهِنَّ","by their creation"],["بِقَـٰدِرٍ","(is) able"],["عَلَىٰٓ","to give life"],["أَن","to give life"],["يُحْـِۧىَ","to give life"],["ٱلْمَوْتَىٰ ۚ","(to) the dead"],["بَلَىٰٓ","Yes"],["إِنَّهُۥ","indeed He"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","All-Powerful"]]],"4544":["(Dan ingatlah hari ketika orang-orang kafir dihadapkan kepada neraka) ketika mereka diazab di dalamnya, lalu dikatakan kepada mereka, (\"Bukankah ini) yakni azab ini (benar?\" Mereka menjawab, \"Ya benar demi Rabb kami.\" Allah berfirman, \"Maka rasakanlah azab ini disebabkan kalian selalu ingkar.\")",[["وَيَوْمَ","And (the) Day"],["يُعْرَضُ","are exposed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["عَلَى","to"],["ٱلنَّارِ","the Fire"],["أَلَيْسَ","Is not"],["هَـٰذَا","this"],["بِٱلْحَقِّ ۖ","the truth"],["قَالُوا۟","They will say"],["بَلَىٰ","Yes"],["وَرَبِّنَا ۚ","by our Lord"],["قَالَ","He will say"],["فَذُوقُوا۟","Then taste"],["ٱلْعَذَابَ","the punishment"],["بِمَا","because"],["كُنتُمْ","you used to"],["تَكْفُرُونَ","disbelieve"]]],"4545":["(Maka bersabarlah kamu) di dalam menghadapi perlakuan kaummu yang menyakitkan itu (sebagaimana orang-orang yang mempunyai keteguhan hati) yaitu orang-orang yang teguh dan sabar di dalam menghadapi cobaan dan tantangan (dari rasul-rasul) sebelummu, karena itu kamu akan termasuk orang yang mempunyai keteguhan hati. Lafal Min di sini menunjukkan makna Bayan, sehingga pengertiannya menunjukkan, bahwa semua rasul-rasul itu mempunyai keteguhan hati. Tetapi menurut pendapat yang lain itu menunjukkan makna Lit Tab'idh, karena Nabi Adam bukanlah termasuk di antara mereka yang memiliki keteguhan hati, sebagaimana yang diungkapkan oleh ayat lain yaitu firman-Nya: \".. dan tidak Kami dapati padanya kemauan yang kuat.\" (Q.S. Thaha, 115) demikian pula Nabi Yunus tidak termasuk di antara mereka yang Ulil 'Azmi, sebagaimana yang diungkapkan oleh firman-Nya, \".. dan janganlah kamu seperti orang yang berada dalam (perut) ikan (Yunus).\" (Q.S. Al-Qalam, 48) (dan janganlah kamu meminta disegerakan azab bagi mereka) bagi kaummu yaitu disegerakan turunnya azab bagi mereka. Menurut pendapat lain, bahwa hal ini timbul sebagai reaksi dari sikap mereka terhadapnya, maka Nabi suka jika azab diturunkan kepada mereka, tetapi selanjutnya Nabi diperintahkan supaya bersabar dan jangan meminta supaya disegerakan azab bagi mereka. Karena sesungguhnya azab itu pasti akan menimpa mereka. (Pada hari mereka melihat apa yang diancamkan kepada mereka, mereka merasa seolah-olah) yang dimaksud adalah azab di akhirat mengingat lamanya masa di akhirat mereka merasa seolah-olah (tidak tinggal) di dunia menurut dugaan mereka (melainkan sesaat pada siang hari) Alquran ini adalah (suatu peringatan) peringatan dari Allah buat kalian (maka tidaklah) tiadalah (dibinasakan) sewaktu azab sudah di ambang pintu (melainkan orang-orang yang fasik) yaitu orang-orang yang kafir.",[["فَٱصْبِرْ","So be patient"],["كَمَا","as"],["صَبَرَ","had patience"],["أُو۟لُوا۟","those of determination"],["ٱلْعَزْمِ","those of determination"],["مِنَ","of"],["ٱلرُّسُلِ","the Messengers"],["وَلَا","and (do) not"],["تَسْتَعْجِل","seek to hasten"],["لَّهُمْ ۚ","for them"],["كَأَنَّهُمْ","As if they had"],["يَوْمَ","(the) Day"],["يَرَوْنَ","they see"],["مَا","what"],["يُوعَدُونَ","they were promised"],["لَمْ","not"],["يَلْبَثُوٓا۟","remained"],["إِلَّا","except"],["سَاعَةًۭ","an hour"],["مِّن","of"],["نَّهَارٍۭ ۚ","a day"],["بَلَـٰغٌۭ ۚ","A notification"],["فَهَلْ","But will"],["يُهْلَكُ","(any) be destroyed"],["إِلَّا","except"],["ٱلْقَوْمُ","the people "],["ٱلْفَـٰسِقُونَ","the defiantly disobedient"]]],"4546":["(Orang-orang yang kafir) dari kalangan penduduk Mekah (dan menghalang-halangi) orang-orang lainnya (dari jalan Allah) dari jalan keimanan (Allah melebur) menghapus (amal-amal mereka) seperti memberi makan dan menghubungkan silaturahim; mereka tidak akan melihat pahala amalnya di akhirat nanti dan mereka hanya mendapat balasan di dunia saja dari kemurahan-Nya.",[["ٱلَّذِينَ","Those who"],["كَفَرُوا۟","disbelieve"],["وَصَدُّوا۟","and turn away"],["عَن","from"],["سَبِيلِ","(the) way of Allah"],["ٱللَّهِ","(the) way of Allah"],["أَضَلَّ","He will cause to be lost"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4547":["(Dan orang-orang yang beriman) yaitu para sahabat Anshar dan lainnya (dan mengerjakan amal-amal yang saleh serta beriman pula kepada apa yang diturunkan kepada Muhammad) yakni Alquran (dan itulah yang hak dari Rabb mereka, Allah menghapuskan daripada mereka) artinya, Dia mengampuni (kesalahan-kesalahan mereka dan memperbaiki keadaan mereka) karena itu mereka tidak lagi mendurhakai-Nya.",[["وَٱلَّذِينَ","And those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["وَءَامَنُوا۟","and believe"],["بِمَا","in what"],["نُزِّلَ","is revealed"],["عَلَىٰ","to"],["مُحَمَّدٍۢ","Muhammad"],["وَهُوَ","and it"],["ٱلْحَقُّ","(is) the truth"],["مِن","from"],["رَّبِّهِمْ ۙ","their Lord"],["كَفَّرَ","He will remove"],["عَنْهُمْ","from them"],["سَيِّـَٔاتِهِمْ","their misdeeds"],["وَأَصْلَحَ","and improve"],["بَالَهُمْ","their condition"]]],"4548":["(Yang demikian) maksudnya penghapusan amal dan pengampunan kesalahan-kesalahan itu (adalah karena) disebabkan (orang-orang kafir mengikuti yang batil) yakni ajakan setan (dan sesungguhnya orang-orang yang beriman mengikuti yang hak) yakni Alquran (dari Rabb mereka. Demikianlah) sebagaimana penjelasan tersebut (Allah membuat untuk manusia perbandingan-perbandingan bagi mereka) untuk menjelaskan keadaan mereka, yaitu orang kafir amalnya akan dihapus, sedangkan orang mukmin kesalahan-kesalahannya akan diampuni.",[["ذَٰلِكَ","That"],["بِأَنَّ","(is) because"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["ٱتَّبَعُوا۟","follow"],["ٱلْبَـٰطِلَ","falsehood"],["وَأَنَّ","and that"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["ٱتَّبَعُوا۟","follow"],["ٱلْحَقَّ","(the) truth"],["مِن","from"],["رَّبِّهِمْ ۚ","their Lord"],["كَذَٰلِكَ","Thus"],["يَضْرِبُ","Allah presents"],["ٱللَّهُ","Allah presents"],["لِلنَّاسِ","to the people"],["أَمْثَـٰلَهُمْ","their similitudes"]]],"4549":["(Apabila kalian bertemu dengan orang-orang kafir di medan perang maka pancunglah batang leher mereka) lafal Dharbur Riqaab adalah bentuk Mashdar yang menggantikan kedudukan Fi'ilnya, karena asalnya adalah, Fadhribuu Riqaabahum artinya, maka pancunglah batang leher mereka. Maksudnya, bunuhlah mereka. Di sini diungkapkan dengan kalimat Dharbur Riqaab yang artinya memancung leher, karena pukulan yang mematikan itu kebanyakan dilakukan dengan cara memukul atau memancung batang leher. (Sehingga apabila kalian telah mengalahkan mereka) artinya kalian telah banyak membunuh mereka (maka kencangkanlah) tangkaplah dan tawanlah mereka lalu ikatlah mereka (ikatan mereka) dengan tali pengikat tawanan perang (dan sesudah itu kalian boleh membebaskan mereka) lafal Mannan adalah bentuk Mashdar yang menggantikan kedudukan Fi'ilnya; maksudnya, kalian memberikan anugerah kepada mereka, yaitu dengan cara melepaskan mereka tanpa imbalan apa-apa (atau menerima tebusan) artinya, kalian meminta tebusan berupa harta atau tukaran dengan kaum muslimin yang ditawan oleh mereka (sampai perang meletakkan) maksudnya, orang-orang yang terlibat di dalam peperangan itu meletakkan (senjatanya) artinya, menghentikan adu senjata dan adu lain-lainnya, misalnya orang-orang kafir menyerah kalah atau mereka menandatangani perjanjian gencatan senjata; hal inilah akhir dari suatu peperangan dan saling tawan-menawan. (Demikianlah) menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, yaitu perkara tentang menghadapi orang-orang kafir adalah sebagaimana yang telah disebutkan tadi (apabila Allah menghendaki niscaya Allah dapat menang atas mereka) tanpa melalui peperangan lagi (tetapi) Dia memerintahkan kalian supaya berperang (untuk menguji sebagian kalian dengan sebagian yang lain) di antara mereka dalam peperangan itu, sebagian orang yang gugur di antara kalian ada yang dimasukkan ke dalam surga, dan sebagian lagi dimasukkan ke dalam neraka. (Dan orang-orang yang gugur) menurut suatu qiraat dibaca Qaataluu dan seterusnya, ayat ini diturunkan pada waktu perang Uhud, karena banyak di antara pasukan kaum muslimin yang gugur dan mengalami luka-luka (di jalan Allah, Allah tidak akan menyia-nyiakan) maksudnya, tidak akan menghapuskan (amal mereka.)",[["فَإِذَا","So when"],["لَقِيتُمُ","you meet"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["فَضَرْبَ","then strike"],["ٱلرِّقَابِ","the necks"],["حَتَّىٰٓ","until"],["إِذَآ","when"],["أَثْخَنتُمُوهُمْ","you have subdued them"],["فَشُدُّوا۟","then bind firmly"],["ٱلْوَثَاقَ","the bond"],["فَإِمَّا","then either"],["مَنًّۢا","a favor"],["بَعْدُ","afterwards"],["وَإِمَّا","or"],["فِدَآءً","ransom"],["حَتَّىٰ","until"],["تَضَعَ","lays down"],["ٱلْحَرْبُ","the war"],["أَوْزَارَهَا ۚ","its burdens"],["ذَٰلِكَ","That"],["وَلَوْ","And if"],["يَشَآءُ","Allah had willed"],["ٱللَّهُ","Allah had willed"],["لَٱنتَصَرَ","surely, He could have taken retribution"],["مِنْهُمْ","from them"],["وَلَـٰكِن","but"],["لِّيَبْلُوَا۟","to test"],["بَعْضَكُم","some of you"],["بِبَعْضٍۢ ۗ","with others"],["وَٱلَّذِينَ","And those who"],["قُتِلُوا۟","are killed"],["فِى","in"],["سَبِيلِ","(the) way of Allah"],["ٱللَّهِ","(the) way of Allah"],["فَلَن","then never"],["يُضِلَّ","He will cause to be lost"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4550":["(Allah akan memberi petunjuk kepada mereka) di dunia dan di akhirat kepada yang bermanfaat buat diri mereka (dan memperbaiki keadaan mereka) di dunia dan di akhirat. Perbaikan di dunia adalah bagi mereka yang tidak gugur, yang termasuk ke dalam pengertian ungkapan Qutiluu dengan cara Taghlib, artinya lebih memprioritaskan mereka yang gugur di jalan Allah swt.",[["سَيَهْدِيهِمْ","He will guide them"],["وَيُصْلِحُ","and improve"],["بَالَهُمْ","their condition"]]],"4551":["(Dan memasukkan mereka ke dalam surga yang telah diperkenalkan) telah dijelaskan (kepada mereka) sehingga mereka mengetahui tempat-tempat tinggal mereka dalam surga itu dan mereka telah mengenal istri-istri mereka dan telah mengenal pelayan-pelayan yang akan melayani mereka tanpa membutuhkan petunjuk lagi.",[["وَيُدْخِلُهُمُ","And admit them"],["ٱلْجَنَّةَ","(to) Paradise"],["عَرَّفَهَا","He has made it known"],["لَهُمْ","to them"]]],"4552":["(Hai orang-orang yang beriman! Jika kalian menolong Allah) yakni agama-Nya dan Rasul-Nya (niscaya Dia menolong kalian) atas musuh-musuh kalian (dan meneguhkan telapak kaki kalian) di dalam medan perang.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوٓا۟","O you who believe"],["إِن","If"],["تَنصُرُوا۟","you help"],["ٱللَّهَ","Allah"],["يَنصُرْكُمْ","He will help you"],["وَيُثَبِّتْ","and make firm"],["أَقْدَامَكُمْ","your feet"]]],"4553":["(Dan orang-orang yang kafir) dari kalangan penduduk Mekah; lafal ayat ini berkedudukan menjadi Mubtada, sedangkan Khabarnya, niscaya mereka celaka. Pengertian ini disimpulkan dari firman selanjutnya yaitu (maka kecelakaanlah bagi mereka) yakni kebinasaan dan kekecewaanlah yang akan mereka terima dari Allah (dan Allah menyesatkan amal perbuatan mereka) lafal ayat ini diathafkan pada Ta'isuu yang keberadaannya diperkirakan.",[["وَٱلَّذِينَ","But those who"],["كَفَرُوا۟","disbelieve"],["فَتَعْسًۭا","destruction (is)"],["لَّهُمْ","for them"],["وَأَضَلَّ","and He will cause to be lost"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4554":["(Yang demikian itu) kecelakaan dan penyesatan itu (adalah karena sesungguhnya mereka benci kepada apa yang diturunkan Allah) yakni Alquran yang diturunkan-Nya, di dalamnya terkandung masalah-masalah taklif atau kewajiban-kewajiban (lalu Allah menghapuskan pahala amal-amal mereka.)",[["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because they"],["كَرِهُوا۟","hate"],["مَآ","what"],["أَنزَلَ","Allah has revealed"],["ٱللَّهُ","Allah has revealed"],["فَأَحْبَطَ","so He has made worthless"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4555":["(Maka apakah mereka tidak mengadakan perjalanan di bumi sehingga mereka dapat memperhatikan bagaimana kesudahan orang-orang yang sebelum mereka; Allah telah menimpakan kebinasaan atas mereka) atas diri mereka, dan anak-anak serta harta benda mereka (dan orang-orang kafir akan menerima hal yang seperti itu) yaitu mereka akan menerima akibat-akibat yang sama dengan apa yang telah diterima oleh orang-orang kafir sebelum mereka.",[["۞ أَفَلَمْ","Do not"],["يَسِيرُوا۟","they travel"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَيَنظُرُوا۟","and see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلَّذِينَ","(of) those"],["مِن","before them"],["قَبْلِهِمْ ۚ","before them"],["دَمَّرَ","Allah destroyed"],["ٱللَّهُ","Allah destroyed"],["عَلَيْهِمْ ۖ","[over] them"],["وَلِلْكَـٰفِرِينَ","and for the disbelievers"],["أَمْثَـٰلُهَا","its likeness"]]],"4556":["(Yang demikian itu) dimenangkannya orang-orang mukmin dan dikalahkannya orang-orang kafir (karena sesungguhnya Allah adalah pelindung) pelindung dan penolong (orang-orang yang beriman dan karena sesungguhnya orang-orang kafir itu tiada mempunyai pelindung.)",[["ذَٰلِكَ","That"],["بِأَنَّ","(is) because"],["ٱللَّهَ","Allah"],["مَوْلَى","(is the) Protector"],["ٱلَّذِينَ","(of) those who"],["ءَامَنُوا۟","believe"],["وَأَنَّ","and that"],["ٱلْكَـٰفِرِينَ","the disbelievers "],["لَا","(there is) no"],["مَوْلَىٰ","protector"],["لَهُمْ","for them"]]],"4557":["(Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal saleh ke dalam surga yang mengalir di bawahnya sungai-sungai. Dan orang-orang yang kafir itu bersenang-senang) di dunia (dan mereka makan seperti makannya binatang-binatang) tiada lagi yang menjadi kepentingan mereka selain dari perut dan nafsu syahwatnya dan mereka sama sekali tidak menoleh sedikit pun kepada masalah akhirat. (Dan neraka adalah tempat tinggal mereka) atau, tempat menetap dan tempat kembali mereka untuk selama-lamanya.",[["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يُدْخِلُ","will admit"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["جَنَّـٰتٍۢ","(to) Gardens"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath it"],["ٱلْأَنْهَـٰرُ ۖ","the rivers"],["وَٱلَّذِينَ","but those who"],["كَفَرُوا۟","disbelieve"],["يَتَمَتَّعُونَ","they enjoy"],["وَيَأْكُلُونَ","and eat"],["كَمَا","as"],["تَأْكُلُ","eat"],["ٱلْأَنْعَـٰمُ","the cattle"],["وَٱلنَّارُ","and the Fire"],["مَثْوًۭى","(will be) an abode"],["لَّهُمْ","for them"]]],"4558":["(Dan berapa banyaknya) sudah berapa banyak (negeri-negeri) yakni penduduknya (yang lebih kuat dari penduduk negerimu) lebih kuat daripada penduduk negeri Mekah (yang telah mengusirmu itu) Dhamir di sini lebih memperhatikan lafal Qaryah (Kami telah membinasakan mereka) di sini lebih diperhatikan makna yang terkandung pada lafal Qaryah yang pertama (maka tidak ada seorang penolong pun bagi mereka) dari kebinasaan yang Kami lakukan.",[["وَكَأَيِّن","And how many"],["مِّن","of"],["قَرْيَةٍ","a town"],["هِىَ","which"],["أَشَدُّ","(was) stronger"],["قُوَّةًۭ","(in) strength"],["مِّن","than"],["قَرْيَتِكَ","your town"],["ٱلَّتِىٓ","which"],["أَخْرَجَتْكَ","has driven you out"],["أَهْلَكْنَـٰهُمْ","We destroyed them"],["فَلَا","so no"],["نَاصِرَ","helper"],["لَهُمْ","for them"]]],"4559":["(Maka apakah orang yang berpegang pada keterangan) yakni hujah dan argumentasi (yang datang dari Rabbnya) mereka adalah orang-orang mukmin (sama dengan orang yang dihiasi oleh keburukan amal perbuatannya) karena itu lalu ia memandangnya sebagai perbuatan yang baik, mereka adalah orang-orang kafir Mekah (dan mengikuti hawa nafsunya?) dalam menyembah berhala-berhala, maksudnya tentu saja tidak ada persamaan di antara keduanya.",[["أَفَمَن","Then is (he) who"],["كَانَ","is"],["عَلَىٰ","on"],["بَيِّنَةٍۢ","a clear proof"],["مِّن","from"],["رَّبِّهِۦ","his Lord"],["كَمَن","like (he) who"],["زُيِّنَ","is made attractive"],["لَهُۥ","to him"],["سُوٓءُ","(the) evil"],["عَمَلِهِۦ","(of) his deeds"],["وَٱتَّبَعُوٓا۟","while they follow"],["أَهْوَآءَهُم","their desires"]]],"4560":["(Perumpamaan) gambaran tentang (surga yang dijanjikan kepada orang-orang yang bertakwa) dan yang menjadi milik bersama bagi orang-orang yang memasukinya. Lafal ayat ini menjadi Mubtada, sedangkan Khabarnya ialah (yang di dalamnya ada sungai-sungai dari air yang tiada berubah rasa dan baunya) dapat dibaca Aasinin atau Asinin, jika dibaca Aasinin wazannya sama dengan lafal Dhaaribin, jika dibaca Asinin Wazannya sama dengan lafal Hadzirun. Artinya, airnya tidak berubah atau tidak berbeda dengan air dunia yang dapat berubah karena ada sesuatu yang mencampurinya (sungai-sungai dari air susu yang tiada berubah rasanya) berbeda dengan air susu di dunia, karena air susu di dunia keluar dari susu (sungai-sungai dari khamar yang lezat rasanya) sangat lezat rasanya (bagi peminumnya) berbeda halnya dengan khamar di dunia, khamar dunia rasanya tidak enak bila diminum (dan sungai-sungai dari madu yang disaring) berbeda dengan madu di dunia, karena madu di dunia keluar dari perut tawon kemudian bercampur dengan lilin dan lain sebagainya (dan mereka memperoleh di dalamnya) berbagai macam jenis (dari aneka ragam buah-buahan, dan ampunan dari Rabb mereka) Rabb mereka rela terhadap mereka di samping kebaikan-Nya yang terus melimpah bagi mereka tanpa henti-hentinya, yaitu berupa kenikmatan-kenikmatan yang telah disebutkan tadi. Berbeda halnya dengan perihal seorang tuan atau pemilik hamba sahaya di dunia, karena sesungguhnya sekalipun majikan dari hamba sahaya itu berbuat baik kepadanya hal itu dibarengi dengan amarahnya, yakni terkadang sang majikan memarahinya (sama dengan orang yang kekal dalam neraka) lafal ayat ini menjadi Khabar dari Mubtada yang diperkirakan keberadaannya yakni, apakah orang yang berada dalam kenikmatan tersebut sama dengan orang yang kekal di dalam neraka (dan diberi minuman dengan air yang mendidih) yakni air yang sangat panas (sehingga memotong-motong ususnya?) artinya, minuman itu menghancurkan dan mencabik-cabik isi perutnya. Lafal Am'aa adalah bentuk jamak dari lafal Mi'a, sedangkan huruf Alifnya adalah ganti dari huruf Ya, karena sebagian dari mereka ada yang mengatakan Mi'yaani.",[["مَّثَلُ","A parable"],["ٱلْجَنَّةِ","(of) Paradise"],["ٱلَّتِى","which"],["وُعِدَ","is promised"],["ٱلْمُتَّقُونَ ۖ","(to) the righteous"],["فِيهَآ","Therein"],["أَنْهَـٰرٌۭ","(are) rivers"],["مِّن","of"],["مَّآءٍ","water"],["غَيْرِ","not"],["ءَاسِنٍۢ","polluted"],["وَأَنْهَـٰرٌۭ","and rivers"],["مِّن","of"],["لَّبَنٍۢ","milk"],["لَّمْ","not"],["يَتَغَيَّرْ","changes"],["طَعْمُهُۥ","its taste"],["وَأَنْهَـٰرٌۭ","and rivers"],["مِّنْ","of"],["خَمْرٍۢ","wine"],["لَّذَّةٍۢ","delicious"],["لِّلشَّـٰرِبِينَ","for (the) drinkers"],["وَأَنْهَـٰرٌۭ","and rivers"],["مِّنْ","of"],["عَسَلٍۢ","honey"],["مُّصَفًّۭى ۖ","purified"],["وَلَهُمْ","and for them"],["فِيهَا","therein"],["مِن","of"],["كُلِّ","all"],["ٱلثَّمَرَٰتِ","fruits"],["وَمَغْفِرَةٌۭ","and forgiveness"],["مِّن","from"],["رَّبِّهِمْ ۖ","their Lord"],["كَمَنْ","like he who"],["هُوَ","like he who"],["خَـٰلِدٌۭ","(will) abide forever"],["فِى","in"],["ٱلنَّارِ","the Fire"],["وَسُقُوا۟","and they will be given to drink"],["مَآءً","water"],["حَمِيمًۭا","boiling"],["فَقَطَّعَ","so it cuts into pieces"],["أَمْعَآءَهُمْ","their intestines"]]],"4561":["(Dan di antara mereka) orang-orang kafir itu (ada orang yang mendengarkan perkataanmu) sewaktu kamu berkhutbah Jumat, mereka adalah orang-orang munafik (sehingga apabila mereka keluar dari sisimu mereka berkata kepada orang-orang yang telah diberi ilmu pengetahuan) dari kalangan sahabat Nabi saw. antara lain adalah Ibnu Masud dan Ibnu Abbas r.a.; mereka mengatakan kepadanya dengan nada sinis dan mengejek, (\"Apakah yang dikatakannya tadi?\") dapat dibaca Aanifan atau Anifan, maksudnya kami kurang jelas. (Mereka itulah orang-orang yang dikunci mati hati mereka oleh Allah) dengan kekafiran (dan mengikuti hawa nafsu mereka) dalam kemunafikan.",[["وَمِنْهُم","And among them"],["مَّن","(are some) who"],["يَسْتَمِعُ","listen"],["إِلَيْكَ","to you"],["حَتَّىٰٓ","until"],["إِذَا","when"],["خَرَجُوا۟","they depart"],["مِنْ","from"],["عِندِكَ","you"],["قَالُوا۟","they say"],["لِلَّذِينَ","to those who"],["أُوتُوا۟","were given"],["ٱلْعِلْمَ","the knowledge"],["مَاذَا","What"],["قَالَ","(has) he said"],["ءَانِفًا ۚ","just now"],["أُو۟لَـٰٓئِكَ","Those "],["ٱلَّذِينَ","(are) the ones"],["طَبَعَ","Allah has set a seal"],["ٱللَّهُ","Allah has set a seal"],["عَلَىٰ","upon"],["قُلُوبِهِمْ","their hearts"],["وَٱتَّبَعُوٓا۟","and they follow"],["أَهْوَآءَهُمْ","their desires"]]],"4562":["(Dan orang-orang yang mendapat petunjuk) mereka adalah orang-orang mukmin (Dia menambah kepada mereka) yakni Allah swt. (petunjuk dan memberikan kepada mereka -balasan- ketakwaannya) maksudnya, Allah memberikan ilham kepada mereka untuk mengamalkan hal-hal yang dapat memelihara diri mereka dari neraka.",[["وَٱلَّذِينَ","And those who"],["ٱهْتَدَوْا۟","accept guidance"],["زَادَهُمْ","He increases them"],["هُدًۭى","(in) guidance"],["وَءَاتَىٰهُمْ","and gives them"],["تَقْوَىٰهُمْ","their righteousness"]]],"4563":["(Maka tidaklah yang mereka tunggu-tunggu) maksudnya tiadalah yang ditunggu-tunggu, oleh orang-orang kafir Mekah (melainkan hari kiamat yaitu kedatangannya kepada mereka) lafal An Ta'tiyahum menjadi Badal Isytimal dari lafal As-Saa'ah; yakni, perkaranya tiada lain hanyalah menunggu kedatangan kiamat kepada mereka (dengan tiba-tiba) atau secara sekonyong-konyong (karena sesungguhnya telah datang tanda-tandanya) alamat-alamatnya, antara lain diutusnya Nabi saw., terbelahnya bulan dan munculnya Ad-Dukhaan. (Maka apabila ia datang kepada mereka apakah faedahnya) yang dimaksud adalah kedatangan hari kiamat (kesadaran mereka) keinsafan mereka, tidak ada manfaatnya lagi buat mereka.",[["فَهَلْ","Then do"],["يَنظُرُونَ","they wait"],["إِلَّا","but"],["ٱلسَّاعَةَ","(for) the Hour"],["أَن","that"],["تَأْتِيَهُم","it should come to them"],["بَغْتَةًۭ ۖ","suddenly"],["فَقَدْ","But indeed"],["جَآءَ","have come"],["أَشْرَاطُهَا ۚ","its indications"],["فَأَنَّىٰ","Then how"],["لَهُمْ","to them"],["إِذَا","when"],["جَآءَتْهُمْ","has come to them"],["ذِكْرَىٰهُمْ","their reminder"]]],"4564":["(Maka ketahuilah, bahwa sesungguhnya tidak ada Tuhan melainkan Allah) maksudnya, tetaplah engkau hai Muhammad pada prinsipmu yang demikian itu, karena itu bermanfaat kelak di hari kiamat (dan mohonlah ampunan bagi dosamu) yakni demi dosamu. Menurut suatu pendapat disebutkan, bahwa dikatakan demikian kepada Nabi Muhammad saw. dimaksud sebagai pelajaran buat umatnya, supaya mereka meniru jejaknya. Sedangkan bagi nabi dima'shum atau terpelihara dari perbuatan dosa. Memang Nabi saw. telah mengerjakan hal ini sebagaimana yang diungkapkan di dalam salah satu sabdanya yang mengatakan, \"Sesungguhnya aku selalu memohon ampun kepada Allah sebanyak seratus kali untuk setiap harinya.\" (dan bagi dosa orang-orang mukmin, laki-laki dan perempuan) di dalam ungkapan ayat ini terkandung penghormatan buat mereka, karena Allah swt. memerintahkan kepada nabi supaya memintakan ampun buat mereka. (Dan Allah mengetahui tempat kalian berusaha) tempat kalian bergerak di siang hari dalam rangka mencari upaya penghidupan (dan tempat tinggal kalian) maksudnya, tempat kalian beristirahat di tempat tidur kalian pada malam hari. Makna yang dimaksud ialah bahwa Allah swt. mengetahui semua hal ikhwal kalian, tiada sesuatu pun yang samar bagi-Nya, maka berhati-hatilah kalian kepada-Nya. Khitab dalam ayat ini ditujukan kepada orang-orang mukmin dan lain-lainnya.",[["فَٱعْلَمْ","So know"],["أَنَّهُۥ","that [He] "],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","but"],["ٱللَّهُ","Allah"],["وَٱسْتَغْفِرْ","and ask forgiveness"],["لِذَنۢبِكَ","for your sin"],["وَلِلْمُؤْمِنِينَ","and for the believing men"],["وَٱلْمُؤْمِنَـٰتِ ۗ","and the believing women"],["وَٱللَّهُ","And Allah"],["يَعْلَمُ","knows"],["مُتَقَلَّبَكُمْ","your movement"],["وَمَثْوَىٰكُمْ","and your resting places"]]],"4565":["(Dan orang-orang yang beriman berkata) dalam rangka meminta berjihad, (\"Mengapa tidak) atau kenapa tidak (diturunkan suatu surah?\") yang di dalamnya disebutkan masalah jihad. (Maka apabila diturunkan suatu surah yang muhkam) tiada suatu ayat pun darinya yang dimansukh (dan disebutkan di dalamnya perintah perang) anjuran untuk berperang bagi kalian (kalian lihat orang-orang yang di dalam hatinya ada penyakit) berupa keragu-raguan dalam memeluk agamamu, mereka adalah orang-orang munafik (melihat kepadamu dengan pandangan seperti orang yang pingsan) tidak sadarkan diri (karena takut mati) khawatir akan mati dan benci kepadanya; maksudnya mereka takut menghadapi peperangan dan sangat benci kepadanya. (Maka hal yang lebih utama bagi mereka) lafal ayat ini berkedudukan menjadi Mubtada, sedangkan Khabarnya ialah:",[["وَيَقُولُ","And say"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["لَوْلَا","Why not"],["نُزِّلَتْ","has been revealed"],["سُورَةٌۭ ۖ","a Surah"],["فَإِذَآ","But when"],["أُنزِلَتْ","is revealed"],["سُورَةٌۭ","a Surah"],["مُّحْكَمَةٌۭ","precise"],["وَذُكِرَ","and is mentioned"],["فِيهَا","in it"],["ٱلْقِتَالُ ۙ","the fighting"],["رَأَيْتَ","you see"],["ٱلَّذِينَ","those who"],["فِى","in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌۭ","(is) a disease"],["يَنظُرُونَ","looking"],["إِلَيْكَ","at you "],["نَظَرَ","a look"],["ٱلْمَغْشِىِّ","(of) one fainting"],["عَلَيْهِ","(of) one fainting"],["مِنَ","from"],["ٱلْمَوْتِ ۖ","the death"],["فَأَوْلَىٰ","But more appropriate"],["لَهُمْ","for them"]]],"4566":["(Adalah taat dan mengucapkan perkataan yang baik) artinya bersikap baik terhadapmu. (Apabila telah tetap perintah) maksudnya, perang telah difardukan. (Maka jika mereka menepati kepada Allah) dalam beriman dan taat kepada-Nya (niscaya yang demikian itu lebih baik bagi mereka) Jumlah yang jatuh sesudah Lau merupakan Jawab dari lafal Idzaa.",[["طَاعَةٌۭ","(Is) obedience"],["وَقَوْلٌۭ","and a word"],["مَّعْرُوفٌۭ ۚ","kind"],["فَإِذَا","And when"],["عَزَمَ","(is) determined"],["ٱلْأَمْرُ","the matter"],["فَلَوْ","then if"],["صَدَقُوا۟","they had been true"],["ٱللَّهَ","(to) Allah"],["لَكَانَ","surely, it would have been"],["خَيْرًۭا","better"],["لَّهُمْ","for them"]]],"4567":["(Maka apakah sekiranya) dapat dibaca `Asaitum atau `Asiitum, di dalam ungkapan ini terkandung ungkapan Iltifat dari Ghaibah kepada Mukhathab; maksudnya barangkali kalian (jika kalian berpaling) memalingkan diri dari iman (kalian akan membuat kerusakan di muka bumi dan memutuskan hubungan kekeluargaan) maksudnya, kalian akan kembali kepada akhlak jahiliyah, yaitu gemar mengadakan kerusakan dan peperangan.",[["فَهَلْ","Then would"],["عَسَيْتُمْ","you perhaps"],["إِن","if"],["تَوَلَّيْتُمْ","you are given authority"],["أَن","that"],["تُفْسِدُوا۟","you cause corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَتُقَطِّعُوٓا۟","and cut off"],["أَرْحَامَكُمْ","your ties of kinship"]]],"4568":["(Mereka itulah) yakni orang-orang yang merusak itu (orang-orang yang dilaknati Allah dan ditulikan-Nya telinga mereka) dari mendengarkan perkara yang hak (dan dibutakan-Nya mata mereka) dari jalan petunjuk.",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones"],["لَعَنَهُمُ","Allah has cursed them"],["ٱللَّهُ","Allah has cursed them"],["فَأَصَمَّهُمْ","so He made them deaf"],["وَأَعْمَىٰٓ","and blinded"],["أَبْصَـٰرَهُمْ","their vision"]]],"4569":["(Maka apakah mereka tidak memperhatikan Alquran) yang dapat membimbing mereka untuk mengetahui perkara yang hak (ataukah) sebenarnya (pada hati) mereka (terdapat kuncinya) karena itu mereka tidak dapat memahami kebenaran.",[["أَفَلَا","Then do not"],["يَتَدَبَّرُونَ","they ponder"],["ٱلْقُرْءَانَ","(over) the Quran"],["أَمْ","or"],["عَلَىٰ","upon"],["قُلُوبٍ","(their) hearts"],["أَقْفَالُهَآ","(are) locks"]]],"4570":["(Sesungguhnya orang-orang yang kembali) karena nifaq (ke belakang sesudah petunjuk itu jelas bagi mereka, setan telah menjadikan mereka memandang baik) artinya, setan telah menghiasi mereka (dan memanjangkan angan-angan mereka) dapat dibaca Umlii atau Amlaa; yang memanjangkan angan-angan mereka adalah setan berdasarkan kehendak dari Allah swt. karena pada kenyataannya Dialah yang menyesatkan mereka.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ٱرْتَدُّوا۟","return"],["عَلَىٰٓ","on"],["أَدْبَـٰرِهِم","their backs"],["مِّنۢ","after"],["بَعْدِ","after"],["مَا","what"],["تَبَيَّنَ","(has) become clear"],["لَهُمُ","to them"],["ٱلْهُدَى ۙ","(of) the guidance"],["ٱلشَّيْطَـٰنُ","Shaitaan"],["سَوَّلَ","enticed"],["لَهُمْ","[for] them"],["وَأَمْلَىٰ","and prolonged hope"],["لَهُمْ","for them"]]],"4571":["(Yang demikian itu) yakni kesesatan mereka itu (karena sesungguhnya mereka itu berkata kepada orang-orang yang benci kepada apa yang diturunkan Allah) yakni berkata kepada orang-orang musyrik, (\"Kami akan mematuhi kalian dalam beberapa urusan\") yaitu bersedia untuk membantu dalam memusuhi Nabi saw. dan menghasut kaum muslimin supaya mereka tidak mau berjihad bersamanya. Orang-orang munafik itu mengatakan demikian secara rahasia, akan tetapi kemudian Allah swt. menampakkannya (sedangkan Allah mengetahui rahasia mereka) kalau dibaca Asraarahum berarti bentuk jamak dari lafal Sirrun yang artinya rahasia, kalau dibaca Israarahum berarti Mashdar.",[["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because they"],["قَالُوا۟","[they] said"],["لِلَّذِينَ","to those who"],["كَرِهُوا۟","hate"],["مَا","what"],["نَزَّلَ","Allah has revealed"],["ٱللَّهُ","Allah has revealed"],["سَنُطِيعُكُمْ","We will obey you"],["فِى","in"],["بَعْضِ","part"],["ٱلْأَمْرِ ۖ","(of) the matter"],["وَٱللَّهُ","But Allah"],["يَعْلَمُ","knows"],["إِسْرَارَهُمْ","their secrets"]]],"4572":["(Bagaimanakah) keadaan mereka (apabila malaikat mencabut nyawa mereka seraya memukul) lafal Yadhribuuna merupakan Hal atau kata keterangan keadaan dari malaikat (muka dan punggung mereka) dengan pemukul-pemukul dari besi.",[["فَكَيْفَ","Then how"],["إِذَا","when"],["تَوَفَّتْهُمُ","take them in death"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["يَضْرِبُونَ","striking"],["وُجُوهَهُمْ","their faces"],["وَأَدْبَـٰرَهُمْ","and their backs"]]],"4573":["(Yang demikian itu) yakni, kematian mereka seperti yang telah disebutkan tadi (karena sesungguhnya mereka mengikuti apa yang menimbulkan kemurkaan Allah dan karena mereka membenci keridaan-Nya) artinya, mereka tidak mau mengamalkan hal-hal yang membuat keridaan-Nya (sebab itu Allah menghapus pahala amal-amal mereka.)",[["ذَٰلِكَ","That"],["بِأَنَّهُمُ","(is) because they"],["ٱتَّبَعُوا۟","followed"],["مَآ","what"],["أَسْخَطَ","angered"],["ٱللَّهَ","Allah"],["وَكَرِهُوا۟","and hated"],["رِضْوَٰنَهُۥ","His pleasure"],["فَأَحْبَطَ","so He made worthless"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4574":["(Atau apakah orang-orang yang ada penyakit dalam kalbunya mengira bahwa Allah tidak akan menampakkan kedengkian mereka) kepada Nabi saw. dan orang-orang mukmin?",[["أَمْ","Or do"],["حَسِبَ","think"],["ٱلَّذِينَ","those who"],["فِى","in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌ","(is) a disease"],["أَن","that"],["لَّن","never"],["يُخْرِجَ","will Allah bring forth"],["ٱللَّهُ","will Allah bring forth"],["أَضْغَـٰنَهُمْ","their hatred"]]],"4575":["(Dan kalau Kami menghendaki, niscaya Kami tunjukkan mereka kepadamu) atau Kami kenalkan mereka kepadamu, kemudian huruf Lam Taukid diulangi pada firman berikutnya (sehingga kamu benar-benar dapat mengenal mereka dengan tanda-tanda) berikut ciri-ciri khas mereka. (Dan sungguh kamu benar-benar akan mengenal mereka) huruf Wawu menunjukkan makna bagi Qasam atau sumpah yang tidak disebutkan, sedangkan lafal sesudahnya merupakan Jawabnya (dari kiasan-kiasan perkataan mereka) atau makna perkataan mereka, bilamana mereka berkata di hadapanmu mereka pasti menyindir dengan kata-kata yang mengandung hinaan terhadap perkara kaum muslimin (dan Allah mengetahui perbuatan-perbuatan kalian.)",[["وَلَوْ","And if"],["نَشَآءُ","We willed"],["لَأَرَيْنَـٰكَهُمْ","surely, We could show them to you"],["فَلَعَرَفْتَهُم","and you would know them"],["بِسِيمَـٰهُمْ ۚ","by their marks"],["وَلَتَعْرِفَنَّهُمْ","but surely, you will know them"],["فِى","by"],["لَحْنِ","(the) tone"],["ٱلْقَوْلِ ۚ","(of their) speech"],["وَٱللَّهُ","And Allah"],["يَعْلَمُ","knows"],["أَعْمَـٰلَكُمْ","your deeds"]]],"4576":["(Dan sesungguhnya Kami benar-benar akan menguji kalian) mencoba kalian dengan berjihad dan lainnya (agar Kami mengetahui) dengan pengetahuan yang tampak (orang-orang yang berjihad dan bersabar di antara kalian) dalam berjihad dan lainnya (dan agar Kami menyatakan) menampakkan (hal ikhwal kalian) tentang ketaatan kalian dan kedurhakaan kalian di dalam masalah jihad dan masalah-masalah lainnya. Ketiga Fi'il yang ada dalam ayat ini, ketiga-tiganya dapat dibaca dengan memakai huruf Mudhara'ah Ya atau Nun.",[["وَلَنَبْلُوَنَّكُمْ","And surely We will test you"],["حَتَّىٰ","until"],["نَعْلَمَ","We make evident"],["ٱلْمُجَـٰهِدِينَ","those who strive"],["مِنكُمْ","among you"],["وَٱلصَّـٰبِرِينَ","and the patient ones"],["وَنَبْلُوَا۟","and We will test"],["أَخْبَارَكُمْ","your affairs"]]],"4577":["(Sesungguhnya orang-orang kafir dan menghalang-halangi jalan Allah) jalan yang hak (dan memusuhi rasul) atau menentangnya (setelah petunjuk itu jelas bagi mereka) yang dimaksud petunjuk adalah jalan Allah tadi (mereka tidak dapat memberi mudarat kepada Allah sedikit pun. Dan Allah akan menghapuskan amal mereka) seperti sedekah dan lain-lainnya, yaitu pahalanya. Di akhirat kelak mereka tidak akan dapat melihat pahalanya. Ayat ini diturunkan berkenaan dengan orang-orang kafir yang terlibat dalam perang Badar, atau orang-orang kafir Bani Quraizhah dan Bani Nadhir.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["وَصَدُّوا۟","and turn away"],["عَن","from"],["سَبِيلِ","(the) way of Allah"],["ٱللَّهِ","(the) way of Allah"],["وَشَآقُّوا۟","and oppose"],["ٱلرَّسُولَ","the Messenger"],["مِنۢ","after"],["بَعْدِ","after"],["مَا","[what]"],["تَبَيَّنَ","(has been) made clear"],["لَهُمُ","to them"],["ٱلْهُدَىٰ","the guidance"],["لَن","never"],["يَضُرُّوا۟","will they harm"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا","(in) anything"],["وَسَيُحْبِطُ","and He will make worthless"],["أَعْمَـٰلَهُمْ","their deeds"]]],"4578":["(Hai orang-orang yang beriman! Taatlah kepada Allah dan taatlah kepada rasul dan janganlah kalian merusakkan amal-amal kalian) dengan melakukan perbuatan-perbuatan maksiat, umpamanya.",[["۞ يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوٓا۟","O you who believe"],["أَطِيعُوا۟","Obey"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","and obey"],["ٱلرَّسُولَ","the Messenger"],["وَلَا","and (do) not"],["تُبْطِلُوٓا۟","make vain"],["أَعْمَـٰلَكُمْ","your deeds"]]],"4579":["(Sesungguhnya orang-orang yang kafir dan menghalangi jalan Allah) tuntunan-Nya, yaitu jalan petunjuk (kemudian mereka mati dalam keadaan kafir, maka sekali-kali Allah tidak akan memberi ampun kepada mereka) ayat ini diturunkan berkenaan dengan orang-orang kafir yang dikubur di Al-Qulaib, seusai perang Badar.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["وَصَدُّوا۟","and turn away"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["ثُمَّ","then"],["مَاتُوا۟","died"],["وَهُمْ","while they"],["كُفَّارٌۭ","(were) disbelievers"],["فَلَن","never"],["يَغْفِرَ","will Allah forgive"],["ٱللَّهُ","will Allah forgive"],["لَهُمْ","them"]]],"4580":["(Janganlah kalian lemah) merasa lemah (dan minta damai) dapat dibaca As-Salmi atau As-Silmi, artinya damai bersama dengan orang-orang kafir bila kalian bertemu dengan mereka dalam perang (padahal kalianlah yang di atas) lafal Al-A'launa asalnya adalah Al-A'lawuuna, kemudian Wawu Lam Fi'ilnya dibuang sehingga jadilah Al-A'launa, artinya, yang menang dan yang mengalahkan (dan Allah pun beserta kalian) yakni bantuan dan pertolongan-Nya (dan Dia sekali-kali tidak akan mengurangi) Allah tidak akan mengurangi kalian (amal-amal kalian) pahala amal-amal kalian.",[["فَلَا","So (do) not"],["تَهِنُوا۟","weaken"],["وَتَدْعُوٓا۟","and call"],["إِلَى","for"],["ٱلسَّلْمِ","peace"],["وَأَنتُمُ","while you"],["ٱلْأَعْلَوْنَ","(are) superior"],["وَٱللَّهُ","and Allah"],["مَعَكُمْ","(is) with you"],["وَلَن","and never"],["يَتِرَكُمْ","will deprive you"],["أَعْمَـٰلَكُمْ","(of) your deeds"]]],"4581":["(Sesungguhnya kehidupan dunia) maksudnya, menyibukkan diri dalam kehidupan dunia (hanyalah permainan dan senda gurau. Dan jika kalian beriman serta bertakwa) kepada Allah, yang demikian itu adalah termasuk perkara akhirat (Allah akan memberikan pahala kepada kalian dan Dia tidak akan meminta harta-harta kalian) semuanya, melainkan hanya zakat yang diwajibkan.",[["إِنَّمَا","Only"],["ٱلْحَيَوٰةُ","the life"],["ٱلدُّنْيَا","(of) the world"],["لَعِبٌۭ","(is) play"],["وَلَهْوٌۭ ۚ","and amusement"],["وَإِن","And if"],["تُؤْمِنُوا۟","you believe"],["وَتَتَّقُوا۟","and fear (Allah)"],["يُؤْتِكُمْ","He will give you"],["أُجُورَكُمْ","your rewards"],["وَلَا","and not"],["يَسْـَٔلْكُمْ","will ask you"],["أَمْوَٰلَكُمْ","(for) your wealth"]]],"4582":["(Jika Dia memintanya dari kalian lalu mendesak kalian) mendesak meminta zakat tersebut (niscaya kalian akan kikir dan keluarlah) karena kekikiran kalian (kedengkian kalian) terhadap agama Islam.",[["إِن","If"],["يَسْـَٔلْكُمُوهَا","He were to ask you for it"],["فَيُحْفِكُمْ","and press you"],["تَبْخَلُوا۟","you will withhold"],["وَيُخْرِجْ","and He will bring forth"],["أَضْغَـٰنَكُمْ","your hatred"]]],"4583":["(Ingatlah kalian) wahai, kalian ingatlah (kalian ini orang-orang yang diajak untuk menafkahkan harta kalian pada jalan Allah) maksudnya untuk menafkahkan apa yang telah diwajibkan atas kalian, yaitu zakat. (Maka di antara kalian ada orang yang kikir, dan siapa yang kikir sesungguhnya dia hanyalah kikir terhadap dirinya sendiri) lafal Bakhila dapat bermuta'addikan 'Ala atau 'An, untuk itu dapat dikatakan Rakhila 'Alaihi dan Bakhila 'Anhu. (Dan Allahlah Yang Maha Kaya) artinya, tidak membutuhkan infak kalian (sedangkan kalianlah orang-orang yang berhajat) kepada-Nya (dan jika kalian berpaling) dari taat kepada-Nya (niscaya Dia akan mengganti kalian dengan kaum yang lain) Dia akan menjadikan yang lain sebagai pengganti kalian (dan mereka tidak akan seperti kalian) tidak akan berpaling dari taat kepada-Nya, bahkan mereka benar-benar akan taat kepada-Nya.",[["هَـٰٓأَنتُمْ","Here you are "],["هَـٰٓؤُلَآءِ","these"],["تُدْعَوْنَ","called"],["لِتُنفِقُوا۟","to spend"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah "],["فَمِنكُم","but among you"],["مَّن","(are some) who"],["يَبْخَلُ ۖ","withhold"],["وَمَن","and whoever"],["يَبْخَلْ","withholds"],["فَإِنَّمَا","then only"],["يَبْخَلُ","he withholds"],["عَن","from"],["نَّفْسِهِۦ ۚ","himself"],["وَٱللَّهُ","But Allah"],["ٱلْغَنِىُّ","(is) Free of need"],["وَأَنتُمُ","while you"],["ٱلْفُقَرَآءُ ۚ","(are) the needy"],["وَإِن","And if"],["تَتَوَلَّوْا۟","you turn away"],["يَسْتَبْدِلْ","He will replace you"],["قَوْمًا","(with) a people"],["غَيْرَكُمْ","other than you"],["ثُمَّ","then"],["لَا","not"],["يَكُونُوٓا۟","they will be"],["أَمْثَـٰلَكُم","(the) likes of you"]]],"4584":["(Sesungguhnya Kami telah memberikan kemenangan kepadamu) maksudnya Kami telah memastikan kemenangan bagimu atas kota Mekah dan kota-kota lainnya di masa mendatang secara paksa melalui jihadmu (yaitu kemenangan yang nyata) artinya, kemenangan yang jelas dan nyata.",[["إِنَّا","Indeed"],["فَتَحْنَا","We have given victory"],["لَكَ","to you"],["فَتْحًۭا","a victory"],["مُّبِينًۭا","clear"]]],"4585":["(Supaya Allah memberi ampunan kepadamu) berkat jihadmu itu (terhadap dosamu yang telah lalu dan yang akan datang) supaya umatmu mau berjihad karena akan mendapat ampunan seperti kamu. Pengertian ayat ini mengandung penakwilan, mengingat para nabi maksum dari segala perbuatan dosa yang hal ini telah ditetapkan berdasarkan dalil aqli dan naqli. Dengan demikian maka huruf Lam pada permulaan ayat ini menunjukkan makna Illatul Ghaaiyyah dan lafal yang dimasukinya merupakan Musabbab bukan Sebab (serta menyempurnakan) melalui kemenangan tersebut (nikmat-Nya) pemberian nikmat-Nya (atasmu dan memimpin kamu) melalui kemenangan itu (kepada jalan) yakni tuntunan (yang lurus) artinya Allah memantapkan kamu pada agama Islam.",[["لِّيَغْفِرَ","That may forgive"],["لَكَ","for you"],["ٱللَّهُ","Allah"],["مَا","what"],["تَقَدَّمَ","preceded"],["مِن","of"],["ذَنۢبِكَ","your sins"],["وَمَا","and what"],["تَأَخَّرَ","will follow"],["وَيُتِمَّ","and complete"],["نِعْمَتَهُۥ","His favor"],["عَلَيْكَ","upon you"],["وَيَهْدِيَكَ","and guide you"],["صِرَٰطًۭا","(to) a Path"],["مُّسْتَقِيمًۭا","Straight"]]],"4586":["(Dan supaya Allah menolongmu) melalui agama Islam itu (dengan pertolongan yang mulia) tidak pernah hina atau pertolongan yang kuat dan tidak dapat dikalahkan.",[["وَيَنصُرَكَ","And Allah may help you"],["ٱللَّهُ","And Allah may help you"],["نَصْرًا","(with) a help"],["عَزِيزًا","mighty"]]],"4587":["(Dialah yang telah menurunkan ketenangan) yakni ketenteraman (ke dalam kalbu orang-orang mukmin supaya keimanan mereka bertambah di samping keimanan mereka) kepada syariat-syariat agama, yaitu sewaktu turun salah satu daripadanya mereka langsung beriman antara lain ialah syariat berjihad. (Dan kepunyaan Allahlah tentara langit dan bumi) jika Dia menghendaki untuk menolong agama-Nya tanpa kalian, niscaya Dia dapat melakukannya (dan adalah Allah Maha Mengetahui) semua makhluk-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya, yakni Dia terus-menerus bersifat demikian.",[["هُوَ","He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنزَلَ","sent down"],["ٱلسَّكِينَةَ","[the] tranquility"],["فِى","in(to)"],["قُلُوبِ","(the) hearts"],["ٱلْمُؤْمِنِينَ","(of) the believers"],["لِيَزْدَادُوٓا۟","that they may increase"],["إِيمَـٰنًۭا","(in) faith"],["مَّعَ","with"],["إِيمَـٰنِهِمْ ۗ","their faith"],["وَلِلَّهِ","And for Allah"],["جُنُودُ","(are the) hosts"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَكَانَ","and Allah"],["ٱللَّهُ","and Allah"],["عَلِيمًا","(is) All-Knower"],["حَكِيمًۭا","All-Wise"]]],"4588":["(Supaya Dia memasukkan) lafal Liyudkhila ini berta'alluq kepada lafal yang tidak disebutkan, yakni Dia memerintahkan berjihad supaya memasukkan (orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dan supaya Dia menutupi kesalahan-kesalahan mereka. Dan yang demikian itu adalah keberuntungan yang besar di sisi Allah.)",[["لِّيُدْخِلَ","That He may admit"],["ٱلْمُؤْمِنِينَ","the believing men"],["وَٱلْمُؤْمِنَـٰتِ","and the believing women"],["جَنَّـٰتٍۢ","(to) Gardens"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","(to) abide forever"],["فِيهَا","therein"],["وَيُكَفِّرَ","and (to) remove"],["عَنْهُمْ","from them"],["سَيِّـَٔاتِهِمْ ۚ","their misdeeds"],["وَكَانَ","and is"],["ذَٰلِكَ","that"],["عِندَ","with"],["ٱللَّهِ","Allah"],["فَوْزًا","a success"],["عَظِيمًۭا","great"]]],"4589":["(Dan supaya Dia mengazab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrik laki-laki dan perempuan yang mereka itu berprasangka buruk terhadap Allah) dapat dibaca As-Sau' atau As-Suu' dan demikian pula pada ayat selanjutnya. Mereka berprasangka bahwa Allah pasti tidak akan menolong Nabi Muhammad saw. dan orang-orang mukmin. (Mereka akan mendapat giliran yang amat buruk) yaitu akan mendapatkan kehinaan dan azab (dan Allah memurkai mereka dan mengutuk mereka) artinya menjauhkan mereka dari rahmat-Nya (serta menyediakan bagi mereka neraka Jahanam. Dan neraka Jahanam itulah seburuk-buruk tempat kembali) tempat kembali yang paling buruk.",[["وَيُعَذِّبَ","And He (may) punish"],["ٱلْمُنَـٰفِقِينَ","the hypocrite men"],["وَٱلْمُنَـٰفِقَـٰتِ","and the hypocrite women"],["وَٱلْمُشْرِكِينَ","and the polytheist men"],["وَٱلْمُشْرِكَـٰتِ","and the polytheist women"],["ٱلظَّآنِّينَ","who assume"],["بِٱللَّهِ","about Allah"],["ظَنَّ","an assumption"],["ٱلسَّوْءِ ۚ","evil"],["عَلَيْهِمْ","Upon them"],["دَآئِرَةُ","(is) a turn"],["ٱلسَّوْءِ ۖ","(of) evil"],["وَغَضِبَ","and Allah's wrath (is)"],["ٱللَّهُ","and Allah's wrath (is)"],["عَلَيْهِمْ","upon them"],["وَلَعَنَهُمْ","and He has cursed them"],["وَأَعَدَّ","and prepared"],["لَهُمْ","for them"],["جَهَنَّمَ ۖ","Hell"],["وَسَآءَتْ","and evil"],["مَصِيرًۭا","(is the) destination"]]],"4590":["(Dan kepunyaan Allahlah tentara langit dan bumi. Dan adalah Allah Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya, yakni Dia terus-menerus bersifat demikian.",[["وَلِلَّهِ","And for Allah"],["جُنُودُ","(are the) hosts"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَكَانَ","and Allah"],["ٱللَّهُ","and Allah"],["عَزِيزًا","(is) All-Mighty"],["حَكِيمًا","All-Wise"]]],"4591":["(Sesungguhnya Kami mengutus kamu sebagai saksi) atas umatmu pada hari kiamat nanti (dan pembawa berita gembira) kepada mereka di dunia (dan pemberi peringatan) maksudnya memberi peringatan dan mempertakuti mereka selama di dunia akan siksa neraka kelak di akhirat bila mereka melakukan perbuatan yang berdosa.",[["إِنَّآ","Indeed, We"],["أَرْسَلْنَـٰكَ","[We] have sent you"],["شَـٰهِدًۭا","(as) a witness"],["وَمُبَشِّرًۭا","and (as) a bearer of glad tidings"],["وَنَذِيرًۭا","and (as) a warner"]]],"4592":["(Supaya kamu sekalian beriman kepada Allah dan Rasul-Nya) lafal Litu`minuu dapat dibaca Liyu`minuu, demikian pula pada tiga tempat lainnya dalam ayat ini, sesudahnya (menguatkan agama-Nya) maksudnya supaya kalian menolong agama-Nya; dan menurut suatu qiraat lafal Tu'azziruuhu dibaca Tu'azzizuuhu (membesarkan-Nya) artinya supaya kalian mengagungkan-Nya, Dhamir pada kedua fi'il tersebut dapat merujuk, kepada Allah atau Rasul-Nya (dan supaya kalian bertasbih kepada-Nya) yakni kepada Allah (di waktu pagi dan petang) pada setiap pagi dan sore.",[["لِّتُؤْمِنُوا۟","That you may believe"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِۦ","and His Messenger"],["وَتُعَزِّرُوهُ","and (may) honor him"],["وَتُوَقِّرُوهُ","and respect him"],["وَتُسَبِّحُوهُ","and glorify Him"],["بُكْرَةًۭ","morning"],["وَأَصِيلًا","and evening"]]],"4593":["(Sesungguhnya orang-orang yang berjanji setia kepada kamu) yaitu melakukan baiat Ridwan di Hudaibiah (sesungguhnya mereka berjanji setia kepada Allah) pengertian ini sama dengan makna yang terkandung dalam ayat lainnya, yaitu firman-Nya, \"Barang siapa yang menaati rasul, sesungguhnya ia telah menaati Allah.\" (Q.S. An-Nisa, 80). (Tangan kekuasaan Allah berada di atas tangan mereka) yang berbaiat kepada Nabi saw. Maksudnya, bahwa Allah swt. menyaksikan pembaiatan mereka, maka Dia kelak akan memberikan balasan pahala-Nya kepada mereka (maka barang siapa yang melanggar janjinya) yakni merusak baiatnya (maka sesungguhnya ia hanya melanggar) karena itu akibat dari pelanggarannya akan menimpa (dirinya sendiri dan barang siapa menepati janjinya kepada Allah maka Allah akan memberinya) dapat dibaca Fasaya`tiihi atau Fasanu`tiihi, kalau dibaca Fasanu`tihi artinya, Kami akan memberinya (pahala yang besar.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يُبَايِعُونَكَ","pledge allegiance to you"],["إِنَّمَا","only"],["يُبَايِعُونَ","they pledge allegiance"],["ٱللَّهَ","(to) Allah"],["يَدُ","(The) Hand"],["ٱللَّهِ","(of) Allah"],["فَوْقَ","(is) over"],["أَيْدِيهِمْ ۚ","their hands"],["فَمَن","Then whoever"],["نَّكَثَ","breaks (his oath)"],["فَإِنَّمَا","then only"],["يَنكُثُ","he breaks"],["عَلَىٰ","against"],["نَفْسِهِۦ ۖ","himself"],["وَمَنْ","and whoever"],["أَوْفَىٰ","fulfils"],["بِمَا","what"],["عَـٰهَدَ","he has covenanted"],["عَلَيْهُ","(with)"],["ٱللَّهَ","Allah"],["فَسَيُؤْتِيهِ","soon He will give him"],["أَجْرًا","a reward"],["عَظِيمًۭا","great"]]],"4594":["(Orang-orang Badui yang tertinggal akan mengatakan) yang dimaksud adalah mereka yang tinggal di sekitar kota Madinah yang tidak mau ikut dengan kamu sewaktu kamu meminta mereka supaya berangkat bersamamu ke Mekah pada tahun perjanjian Hudaibiah karena merasa takut orang-orang Quraisy nanti akan mencegatmu. Mereka akan mengatakan sekembalimu dari Mekah, (\"Harta dan keluarga kami telah merintangi kami) sehingga kami tidak dapat keluar untuk berangkat bersamamu (maka mohonkanlah ampunan untuk kami\") kepada Allah, karena kami tidak dapat ikut keluar bersamamu. Lalu Allah menjawab kepada mereka seraya mendustakan alasan mereka itu melalui firman selanjutnya, (\"Mereka mengucapkan dengan lidahnya) yaitu meminta untuk memohonkan ampunan buat mereka dan perkataan mereka yang lainnya sebelum itu (apa yang tidak ada dalam hatinya) karena mereka adalah orang-orang yang berdusta di dalam alasannya. (Katakanlah, \"Maka siapakah) Istifham atau kata tanya di sini mengandung makna negatif, yakni tidak ada seorang pun (yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki kemudaratan bagi kalian) dapat dibaca Dharran atau Dhurran (atau jika Dia menghendaki manfaat bagi kalian.\" Sebenarnya Allah Maha Mengetahui apa yang kalian kerjakan) artinya Dia terus-menerus bersifat demikian.",[["سَيَقُولُ","Will say"],["لَكَ","to you"],["ٱلْمُخَلَّفُونَ","those who remained behind"],["مِنَ","of"],["ٱلْأَعْرَابِ","the Bedouins"],["شَغَلَتْنَآ","Kept us busy"],["أَمْوَٰلُنَا","our properties"],["وَأَهْلُونَا","and our families"],["فَٱسْتَغْفِرْ","so ask forgiveness"],["لَنَا ۚ","for us"],["يَقُولُونَ","They say"],["بِأَلْسِنَتِهِم","with their tongues"],["مَّا","what"],["لَيْسَ","is not"],["فِى","in"],["قُلُوبِهِمْ ۚ","their hearts"],["قُلْ","Say"],["فَمَن","Then who"],["يَمْلِكُ","has power"],["لَكُم","for you"],["مِّنَ","against"],["ٱللَّهِ","Allah"],["شَيْـًٔا","(in) anything"],["إِنْ","if"],["أَرَادَ","He intends"],["بِكُمْ","for you"],["ضَرًّا","harm"],["أَوْ","or"],["أَرَادَ","He intends"],["بِكُمْ","for you"],["نَفْعًۢا ۚ","a benefit"],["بَلْ","Nay"],["كَانَ","is"],["ٱللَّهُ","Allah"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["خَبِيرًۢا","All-Aware"]]],"4595":["(Tetapi) lafal Bal pada kedua tempat, yakni pada ayat ini dan ayat sebelumnya, menunjukkan makna Intiqal atau perpindahan dari suatu pembahasan kepada pembahasan yang lain (kalian menyangka bahwa rasul dan orang-orang mukmin tidak sekali-kali akan kembali kepada keluarganya untuk selama-lamanya dan hal tersebut dipandang baik menurut hati kalian) yakni bahwa mereka mengharapkan supaya rasul dan orang-orang mukmin tertumpas habis sehingga mereka tidak kembali lagi ke Madinah (dan kalian telah menyangka dengan sangkaan-sangkaan yang buruk) yakni sangkaan seperti ini dan sangkaan-sangkaan yang buruk lainnya (dan kalian menjadi kaum yang binasa) lafal Buura adalah bentuk jamak dari lafal Baairun, yakni binasa menurut Allah dengan berprasangka seperti itu.",[["بَلْ","Nay"],["ظَنَنتُمْ","you thought"],["أَن","that"],["لَّن","(would) never"],["يَنقَلِبَ","return"],["ٱلرَّسُولُ","the Messenger"],["وَٱلْمُؤْمِنُونَ","and the believers"],["إِلَىٰٓ","to"],["أَهْلِيهِمْ","their families"],["أَبَدًۭا","ever"],["وَزُيِّنَ","that was made fair-seeming"],["ذَٰلِكَ","that was made fair-seeming"],["فِى","in"],["قُلُوبِكُمْ","your hearts"],["وَظَنَنتُمْ","And you assumed"],["ظَنَّ","an assumption"],["ٱلسَّوْءِ","evil"],["وَكُنتُمْ","and you became"],["قَوْمًۢا","a people"],["بُورًۭا","ruined"]]],"4596":["(Dan barang siapa yang tidak beriman kepada Allah dan rasul-Nya maka sesungguhnya Kami menyediakan untuk orang-orang kafir neraka yang menyala-nyala) neraka yang apinya sangat besar nyalanya.",[["وَمَن","And whoever"],["لَّمْ","(has) not believed"],["يُؤْمِنۢ","(has) not believed"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِۦ","and His Messenger"],["فَإِنَّآ","then indeed, We"],["أَعْتَدْنَا","[We] have prepared"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["سَعِيرًۭا","a Blazing Fire"]]],"4597":["(Dan hanya kepunyaan Allahlah kerajaan langit dan bumi, Dia memberi ampun kepada siapa yang dikehendaki-Nya dan mengazab siapa yang dikehendaki-Nya Dan adalah Allah Maha Pengampun lagi Maha Penyayang\") Dia terus menerus bersifat demikian.",[["وَلِلَّهِ","And for Allah"],["مُلْكُ","(is the) kingdom"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["يَغْفِرُ","He forgives"],["لِمَن","whom"],["يَشَآءُ","He wills"],["وَيُعَذِّبُ","and punishes"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["غَفُورًۭا","Oft-Forgiving"],["رَّحِيمًۭا","Most Merciful"]]],"4598":["(Orang-orang yang tertinggal itu akan berkata) yakni mereka yang telah disebutkan tadi (apabila kalian berangkat menuju tempat barang rampasan) yang dimaksud adalah ganimah perang Khaibar (untuk mengambilnya, \"Biarkanlah kami) maksudnya janganlah kalian halangi kami (mengikuti kalian\") supaya kami dapat mengambil sebagian dari ganimah tersebut (mereka bermaksud) dengan sikap mereka yang demikian itu (hendak merubah keputusan Allah) menurut suatu qiraat dibaca Kalimullah artinya, janji atau ancaman-Nya. Maksudnya, mereka mengubah ancaman Allah dengan ganimah Khaibar yang khusus hanya untuk mereka yang ikut dalam baiat Ridwan di Hudaibiyah. (Katakanlah, \"Kalian sekali-kali tidak boleh mengikuti kami; demikian Allah telah menetapkan sebelumnya\") sebelum kami kembali (mereka akan mengatakan, \"Sebenarnya kalian dengki kepada kami\") bila kami ikut memperoleh ganimah bersama kalian, karena bagian kalian akan berkurang jadinya. (Bahkan mereka tidak mengerti) masalah agama (melainkan sedikit sekali) dari kalangan mereka yang mengerti tentangnya.",[["سَيَقُولُ","Will say"],["ٱلْمُخَلَّفُونَ","those who remained behind"],["إِذَا","when"],["ٱنطَلَقْتُمْ","you set forth"],["إِلَىٰ","towards"],["مَغَانِمَ","(the) spoils of war"],["لِتَأْخُذُوهَا","to take it"],["ذَرُونَا","Allow us"],["نَتَّبِعْكُمْ ۖ","(to) follow you"],["يُرِيدُونَ","They wish"],["أَن","to"],["يُبَدِّلُوا۟","change"],["كَلَـٰمَ","(the) Words"],["ٱللَّهِ ۚ","(of) Allah"],["قُل","Say"],["لَّن","Never"],["تَتَّبِعُونَا","will you follow us"],["كَذَٰلِكُمْ","Thus"],["قَالَ","Allah said"],["ٱللَّهُ","Allah said"],["مِن","before"],["قَبْلُ ۖ","before"],["فَسَيَقُولُونَ","Then they will say"],["بَلْ","Nay"],["تَحْسُدُونَنَا ۚ","you envy us"],["بَلْ","Nay"],["كَانُوا۟","they were"],["لَا","not"],["يَفْقَهُونَ","understanding"],["إِلَّا","except"],["قَلِيلًۭا","a little"]]],"4599":["(Katakanlah kepada orang-orang Badui yang tertinggal,) yakni orang-orang Badui yang tertinggal tadi sebagai cobaan buat mereka (\"Kalian akan diajak untuk memerangi kaum yang mempunyai) kaum yang memiliki (kekuatan yang besar) menurut suatu pendapat dikatakan, bahwa yang dimaksud adalah menghadapi orang-orang Bani Hanifah yang menguasai tanah Yamamah, dan menurut pendapat yang lain lagi, yang dimaksud adalah kerajaan Persia dan kerajaan Romawi (kalian akan memerangi mereka) lafal ayat ini menjadi Hal atau kata keterangan keadaan bagi lafal yang diperkirakan keberadaannya, yaitu kaum yang dimaksud tadi (atau) mereka (menyerah) karena itu maka kalian tidak berperang lagi. (Maka jika kalian patuhi) ajakan untuk memerangi mereka itu (niscaya Allah akan memberikan kepada kalian pahala yang baik dan jika kalian berpaling sebagaimana kalian telah berpaling sebelumnya, niscaya Dia akan mengazab kalian dengan azab yang pedih\") azab yang menyakitkan.",[["قُل","Say"],["لِّلْمُخَلَّفِينَ","to those who remained behind"],["مِنَ","of"],["ٱلْأَعْرَابِ","the Bedouins"],["سَتُدْعَوْنَ","You will be called"],["إِلَىٰ","to"],["قَوْمٍ","a people"],["أُو۟لِى","possessors of military might"],["بَأْسٍۢ","possessors of military might"],["شَدِيدٍۢ","great"],["تُقَـٰتِلُونَهُمْ","you will fight them"],["أَوْ","or"],["يُسْلِمُونَ ۖ","they will submit"],["فَإِن","Then if"],["تُطِيعُوا۟","you obey"],["يُؤْتِكُمُ","Allah will give you"],["ٱللَّهُ","Allah will give you"],["أَجْرًا","a reward"],["حَسَنًۭا ۖ","good"],["وَإِن","but if"],["تَتَوَلَّوْا۟","you turn away"],["كَمَا","as"],["تَوَلَّيْتُم","you turned away"],["مِّن","before"],["قَبْلُ","before"],["يُعَذِّبْكُمْ","He will punish you"],["عَذَابًا","(with) a punishment"],["أَلِيمًۭا","painful"]]],"4600":["(Tiada dosa atas orang-orang yang buta dan atas orang yang pincang dan atas orang yang sakit) apabila tidak ikut berjihad. (Dan barang siapa yang taat kepada Allah dan Rasul-Nya, niscaya Allah akan memasukkannya) dapat dibaca Yudkhilhu atau Nudkhilhu, kalau dibaca Nudkhilhu artinya, niscaya Kami akan memasukkannya (ke dalam surga yang mengalir di bawahnya sungai-sungai dan barang siapa yang berpaling niscaya akan diazab-Nya) dapat dibaca Yu'adzdzibhu atau Nu'adzdzibhu, kalau dibaca Nu'adzdzibhu artinya, niscaya Kami akan mengazabnya (dengan azab yang pedih.)",[["لَّيْسَ","Not is"],["عَلَى","upon"],["ٱلْأَعْمَىٰ","the blind"],["حَرَجٌۭ","any blame"],["وَلَا","and not"],["عَلَى","on"],["ٱلْأَعْرَجِ","the lame"],["حَرَجٌۭ","any blame"],["وَلَا","and not"],["عَلَى","on"],["ٱلْمَرِيضِ","the sick"],["حَرَجٌۭ ۗ","any blame"],["وَمَن","And whoever"],["يُطِعِ","obeys"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["يُدْخِلْهُ","He will admit him"],["جَنَّـٰتٍۢ","(to) Gardens"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ ۖ","the rivers"],["وَمَن","but whoever"],["يَتَوَلَّ","turns away"],["يُعَذِّبْهُ","He will punish him"],["عَذَابًا","(with) a punishment"],["أَلِيمًۭا","painful"]]],"4601":["(Sesungguhnya Allah telah rida terhadap orang-orang mukmin ketika mereka berjanji setia kepadamu) di Hudaibiyah (di bawah pohon) yaitu pohon Samurah, jumlah mereka yang menyatakan baiat itu ada seribu tiga ratus orang atau lebih. Kemudian mereka berbaiat kepada Nabi saw. yaitu hendaknya mereka saling bahu-membahu melawan orang-orang Quraisy dan janganlah mereka lari karena takut mati (maka Dia mengetahui) yakni Allah mengetahui (apa yang ada dalam hati mereka) yaitu kejujuran dan kesetiaan mereka (lalu menurunkan ketenangan atas mereka dan memberi balasan kepada mereka dengan kemenangan yang dekat waktunya) yaitu takluknya tanah Khaibar sesudah mereka kembali dari Hudaibiyah.",[["۞ لَّقَدْ","Certainly"],["رَضِىَ","Allah was pleased"],["ٱللَّهُ","Allah was pleased"],["عَنِ","with"],["ٱلْمُؤْمِنِينَ","the believers"],["إِذْ","when"],["يُبَايِعُونَكَ","they pledged allegiance to you"],["تَحْتَ","under"],["ٱلشَّجَرَةِ","the tree"],["فَعَلِمَ","and He knew"],["مَا","what"],["فِى","(was) in"],["قُلُوبِهِمْ","their hearts"],["فَأَنزَلَ","so He sent down"],["ٱلسَّكِينَةَ","the tranquility"],["عَلَيْهِمْ","upon them"],["وَأَثَـٰبَهُمْ","and rewarded them"],["فَتْحًۭا","(with) a victory"],["قَرِيبًۭا","near"]]],"4602":["(Serta harta rampasan yang banyak yang dapat mereka ambil) dari tanah Khaibar. (Dan adalah Allah Maha Perkasa lagi Maha Bijaksana) Dia terus-menerus bersifat demikian.",[["وَمَغَانِمَ","And spoils of war"],["كَثِيرَةًۭ","much"],["يَأْخُذُونَهَا ۗ","that they will take"],["وَكَانَ","and is"],["ٱللَّهُ","Allah"],["عَزِيزًا","All-Mighty"],["حَكِيمًۭا","All-Wise"]]],"4603":["(Allah menjanjikan kepada kalian harta rampasan yang banyak yang dapat kalian ambil) dari penaklukan-penaklukan (maka disegerakan-Nya harta rampasan ini untuk kalian) yang dimaksud adalah harta rampasan tanah Khaibar (dan Dia menahan tangan manusia dari kalian) yakni ulah mereka terhadap anak-anak dan istri-istri kalian sewaktu kalian berangkat berperang dan memang orang-orang Yahudi, sewaktu kalian keluar bermaksud untuk membinasakan mereka, akan tetapi Allah melemparkan ke dalam hati mereka rasa takut sehingga mereka tidak berani melakukannya (dan agar hal itu) yakni harta rampasan yang disegerakan itu; lafal ayat ini diathafkan kepada lafal yang diperkirakan keberadaannya; yaitu lafal Litasykuruuhu yang artinya, supaya kalian bersyukur kepada-Nya (menjadi bukti bagi orang-orang mukmin) yang menunjukkan bahwa mereka mendapat pertolongan dari Allah (dan agar Dia menunjuki kalian kepada jalan yang lurus) yakni jalan untuk bertawakal dan menyerahkan segala sesuatu kepada Allah swt.",[["وَعَدَكُمُ","Allah has promised you"],["ٱللَّهُ","Allah has promised you"],["مَغَانِمَ","spoils of war"],["كَثِيرَةًۭ","much"],["تَأْخُذُونَهَا","that you will take it"],["فَعَجَّلَ","and He has hastened"],["لَكُمْ","for you"],["هَـٰذِهِۦ","this"],["وَكَفَّ","and has withheld"],["أَيْدِىَ","(the) hands"],["ٱلنَّاسِ","(of) the people"],["عَنكُمْ","from you "],["وَلِتَكُونَ","that it may be"],["ءَايَةًۭ","a sign"],["لِّلْمُؤْمِنِينَ","for the believers"],["وَيَهْدِيَكُمْ","and He may guide you"],["صِرَٰطًۭا","(to the) Path"],["مُّسْتَقِيمًۭا","Straight"]]],"4604":["(Dan harta-harta rampasan yang lain) lafal Ukhraa ini menjadi Sifat dari lafal yang diperkirakan keberadaannya yaitu Maghaanima yang berkedudukan menjadi Mubtada (yang kalian belum dapat menguasainya) yaitu harta rampasan dari negeri Persia dan negeri Romawi (yang sungguh Allah telah meliputinya) dengan ilmu-Nya bahwa semuanya kelak akan kalian raih. (Dan adalah Allah Maha Kuasa atas segala sesuatu) yakni Dia terus menerus bersifat demikian.",[["وَأُخْرَىٰ","And others"],["لَمْ","not"],["تَقْدِرُوا۟","you had power"],["عَلَيْهَا","over them"],["قَدْ","surely"],["أَحَاطَ","Allah encompassed"],["ٱللَّهُ","Allah encompassed"],["بِهَا ۚ","them"],["وَكَانَ","and is"],["ٱللَّهُ","Allah"],["عَلَىٰ","over"],["كُلِّ","all"],["شَىْءٍۢ","things"],["قَدِيرًۭا","All-Powerful"]]],"4605":["(Dan sekiranya orang-orang kafir itu memerangi kalian) sewaktu kalian di Hudaibiah (pastilah mereka berbalik melarikan diri ke belakang, kemudian mereka tiada memperoleh pelindung) yang dapat memelihara dan menjaga mereka (dan tidak pula penolong.)",[["وَلَوْ","And if"],["قَـٰتَلَكُمُ","fight you"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لَوَلَّوُا۟","surely they would turn"],["ٱلْأَدْبَـٰرَ","the backs"],["ثُمَّ","Then"],["لَا","not"],["يَجِدُونَ","they would find"],["وَلِيًّۭا","any protector"],["وَلَا","and not"],["نَصِيرًۭا","any helper"]]],"4606":["(Sebagai suatu sunatullah) lafal ayat ini adalah Mashdar yang berfungsi mengukuhkan makna jumlah kalimat sebelumnya, yaitu mengenai kalahnya orang-orang kafir dan ditolong-Nya orang-orang mukmin. Maksudnya yang demikian itu merupakan suatu sunatullah (yang telah berlaku sejak dahulu, kamu sekali-kali tidak akan menemukan perubahan bagi sunatullah itu) sebagai ganti darinya.",[["سُنَّةَ","(The established) way"],["ٱللَّهِ","(of) Allah"],["ٱلَّتِى","which"],["قَدْ","passed away"],["خَلَتْ","passed away"],["مِن","before"],["قَبْلُ ۖ","before"],["وَلَن","and never"],["تَجِدَ","you will find"],["لِسُنَّةِ","in (the) way of Allah"],["ٱللَّهِ","in (the) way of Allah"],["تَبْدِيلًۭا","any change"]]],"4607":["(Dan Dialah yang menahan tangan mereka dari kalian dan tangan kalian dari mereka di lembah Mekah) yakni di Hudaibiah (sesudah Allah memenangkan kalian atas mereka) karena sesungguhnya delapan puluh orang lelaki dari kalangan mereka mengelilingi perkemahan kalian dengan tujuan untuk menyergap kalian, tetapi akhirnya mereka dapat dilumpuhkan dan mereka dihadapkan kepada Rasulullah saw. maka ia memberi maaf kepada mereka lalu dilepaskannya mereka dengan bebas. Hal ini merupakan penyebab adanya perjanjian gencatan senjata (dan adalah Allah Maha Melihat apa yang kalian kerjakan.) Lafal Ta'maluuna dapat dibaca Ya'maluuna, kalau dibaca Ya'maluuna maka artinya, \"Dan adalah Allah Maha Melihat apa yang mereka kerjakan.\" Maksud ungkapan ayat ini ialah bahwa Allah masih tetap bersifat demikian.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["كَفَّ","withheld"],["أَيْدِيَهُمْ","their hands"],["عَنكُمْ","from you"],["وَأَيْدِيَكُمْ","and your hands"],["عَنْهُم","from them"],["بِبَطْنِ","within"],["مَكَّةَ","Makkah"],["مِنۢ","after"],["بَعْدِ","after"],["أَنْ","that"],["أَظْفَرَكُمْ","He gave you victory"],["عَلَيْهِمْ ۚ","over them"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["بَصِيرًا","All-Seer"]]],"4608":["(Merekalah orang-orang yang kafir yang menghalangi kalian dari Masjidilharam) yakni menghalangi kalian untuk memasukinya (dan hewan kurban) diathafkan kepada Dhamir Kum yang ada pada lafal Washadduukum (dalam keadaan tertahan) yakni terhenti, lafal ini menjadi Hal atau kata keterangan keadaan (tidak dapat mencapai tempatnya) yaitu tempat penyembelihannya sebagaimana biasanya, lafal ayat ini berkedudukan menjadi Badal Isytimal. (Dan kalau tidaklah karena laki-laki yang mukmin dan perempuan-perempuan yang mukmin) yang masih ada tinggal bersama dengan orang-orang kafir di Mekah (yang tiada kalian ketahui) keimanan mereka (bahwa kalian akan membunuh mereka) kalian akan membunuh mereka bersama dengan orang-orang kafir, sekiranya kalian diizinkan-Nya untuk melakukan penaklukan. Lafal ayat ini menjadi Badal Isytimal dari Dhamir Hum yang terdapat pada lafal Lam Ta'lamuuhum (yang menyebabkan kalian berdosa) yakni perbuatan yang berdosa (tanpa pengetahuan) kalian tentangnya. Semua Dhamir Ghaibah yang ada menunjukkan makna untuk kedua jenis, yaitu jenis lelaki dan perempuan, hal tersebut hanya memprioritaskan Mudzakkar. Jawab dari lafal Laulaa tidak disebutkan, yakni tentulah Allah mengizinkan kalian untuk melakukan penaklukan, tetapi ketika itu Dia ternyata tidak mengizinkan kalian melakukan hal itu. (Supaya Allah memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya) seperti orang-orang mukmin yang telah disebutkan tadi. (Sekiranya mereka tidak bercampur-baur) seandainya mereka membedakan dari orang-orang kafir (tentulah Kami akan mengazab orang-orang kafir di antara mereka) yakni di antara penduduk Mekah pada saat itu juga, seumpamanya Kami memberikan izin kepada kalian untuk melakukan penaklukan (dengan azab yang pedih) azab yang menyakitkan.",[["هُمُ","They"],["ٱلَّذِينَ","(are) those who"],["كَفَرُوا۟","disbelieved"],["وَصَدُّوكُمْ","and hindered you"],["عَنِ","from"],["ٱلْمَسْجِدِ","Al-Masjid Al-Haraam"],["ٱلْحَرَامِ","Al-Masjid Al-Haraam"],["وَٱلْهَدْىَ","while the offering"],["مَعْكُوفًا","(was) prevented"],["أَن","from"],["يَبْلُغَ","reaching"],["مَحِلَّهُۥ ۚ","its place (of sacrifice)"],["وَلَوْلَا","And if not"],["رِجَالٌۭ","(for) men"],["مُّؤْمِنُونَ","believing"],["وَنِسَآءٌۭ","and women"],["مُّؤْمِنَـٰتٌۭ","believing"],["لَّمْ","not"],["تَعْلَمُوهُمْ","you knew them"],["أَن","that"],["تَطَـُٔوهُمْ","you may trample them"],["فَتُصِيبَكُم","and would befall you"],["مِّنْهُم","from them"],["مَّعَرَّةٌۢ","any harm"],["بِغَيْرِ","without"],["عِلْمٍۢ ۖ","knowledge"],["لِّيُدْخِلَ","That Allah may admit"],["ٱللَّهُ","That Allah may admit"],["فِى","to"],["رَحْمَتِهِۦ","His Mercy"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["لَوْ","If"],["تَزَيَّلُوا۟","they had been apart"],["لَعَذَّبْنَا","surely, We would have punished"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["مِنْهُمْ","among them"],["عَذَابًا","(with) a punishment"],["أَلِيمًا","painful"]]],"4609":["(Ketika menanamkan) berta'alluq kepada lafal La'adzdzabnaa (orang-orang kafir itu) menjadi Fa'il dari lafal Ja'ala (ke dalam hati mereka kesombongan) perasaan tinggi diri dari sesuatu (yaitu kesombongan jahiliah) menjadi Badal dari lafal Hamiyah. Makna yang dimaksud ialah hambatan dan cegahan mereka terhadap Nabi dan para sahabatnya untuk mencapai Masjidilharam (lalu Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang mukmin) lalu akhirnya Nabi saw. dan para sahabatnya mengadakan perdamaian dengan mereka, yaitu hendaknya mereka diperbolehkan kembali ke Mekah tahun depan dan ternyata mereka tidak terbakar atau terpancing oleh panasnya perasaan, tidak sebagaimana yang menimpa orang-orang kafir, akhirnya peperangan antara mereka terhindarkan (dan Allah mewajibkan kepada mereka) yakni kepada orang-orang mukmin (kalimat takwa) yaitu \"Tiada Tuhan selain Allah dan Muhammad utusan Allah\", kalimat ini dikaitkan dengan takwa, karena merupakan penyebabnya (dan adalah mereka lebih berhak dengannya) yakni dengan kalimat takwa itu daripada orang-orang kafir (dan patut memilikinya) merupakan Athaf Tafsir. (Dan adalah Allah Maha Mengetahui segala sesuatu) artinya Dia tetap bersifat demikian, dan di antara apa yang diketahui oleh Allah swt. ialah bahwa orang-orang mukmin itu berhak memiliki kalimat takwa itu.",[["إِذْ","When"],["جَعَلَ","had put"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["فِى","in"],["قُلُوبِهِمُ","their hearts"],["ٱلْحَمِيَّةَ","disdain "],["حَمِيَّةَ","(the) disdain"],["ٱلْجَـٰهِلِيَّةِ","(of the time of) ignorance"],["فَأَنزَلَ","Then Allah sent down"],["ٱللَّهُ","Then Allah sent down"],["سَكِينَتَهُۥ","His tranquility"],["عَلَىٰ","upon"],["رَسُولِهِۦ","His Messenger"],["وَعَلَى","and upon"],["ٱلْمُؤْمِنِينَ","the believers"],["وَأَلْزَمَهُمْ","and made them adhere"],["كَلِمَةَ","(to the) word"],["ٱلتَّقْوَىٰ","(of) righteousness"],["وَكَانُوٓا۟","and they were"],["أَحَقَّ","more deserving"],["بِهَا","of it"],["وَأَهْلَهَا ۚ","and worthy of it"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["بِكُلِّ","of every"],["شَىْءٍ","thing"],["عَلِيمًۭا","All-Knower"]]],"4610":["(Sesungguhnya Allah akan membuktikan kepada Rasul-Nya tentang kebenaran mimpinya dengan sebenarnya) Rasulullah saw. bermimpi pada tahun terjadinya perjanjian Hudaibiah, yaitu sebelum beliau berangkat menuju ke Hudaibiah, bahwasanya ia memasuki kota Mekah bersama-sama dengan para sahabatnya dalam keadaan aman hingga mereka dapat bercukur dan ada pula yang hanya memendekkan rambutnya. Kemudian Rasulullah saw. menceritakan hal mimpinya itu kepada para sahabatnya, maka mereka sangat gembira mendengarnya. Ketika para sahabat berangkat bersama Rasulullah menuju Mekah, tiba-tiba mereka dihalang-halangi oleh orang-orang kafir sewaktu mereka sampai di Hudaibiah. Akhirnya mereka kembali ke Madinah dengan perasaan yang berat, pada saat itu timbullah rasa keraguan di dalam hati sebagian orang-orang munafik, lalu turunlah ayat ini. Firman-Nya, \"Bil haqqi\" berta'alluq kepada lafal Shadaqa, atau merupakan Hal atau kata keterangan keadaan dari lafal Ar-Ru'yaa sedangkan kalimat sesudahnya berfungsi menjadi penafsirnya (yaitu bahwa sesungguhnya kamu sekalian pasti akan memasuki Masjidilharam, insya Allah) lafal Insya Allah artinya, jika Allah menghendaki, hanyalah sebagai kalimat Tabarruk saja, yaitu untuk meminta keberkahan (dalam keadaan aman dengan mencukur rambut kepala) mencukur semua rambut kepala (dan mengguntingnya) yakni menggunting sebagiannya saja; kedua lafal ini merupakan Hal bagi lafal yang diperkirakan keberadaannya (sedangkan kalian tidak merasa takut) selama-lamanya (Maka Allah mengetahui) di dalam perjanjian damai itu (apa yang tidak kalian ketahui) mengenai kemaslahatan yang terkandung di dalamnya (dan Dia memberikan sebelum itu) sebelum kalian memasuki Mekah (kemenangan yang dekat) yaitu ditaklukkannya tanah Khaibar, kemudian mimpi itu menjadi kenyataan pada tahun berikutnya.",[["لَّقَدْ","Certainly"],["صَدَقَ","Allah has fulfilled"],["ٱللَّهُ","Allah has fulfilled"],["رَسُولَهُ","His Messenger's"],["ٱلرُّءْيَا","vision"],["بِٱلْحَقِّ ۖ","in truth"],["لَتَدْخُلُنَّ","Surely, you will enter"],["ٱلْمَسْجِدَ","Al-Masjid Al-Haraam"],["ٱلْحَرَامَ","Al-Masjid Al-Haraam"],["إِن","if"],["شَآءَ","Allah wills"],["ٱللَّهُ","Allah wills"],["ءَامِنِينَ","secure"],["مُحَلِّقِينَ","having shaved"],["رُءُوسَكُمْ","your heads"],["وَمُقَصِّرِينَ","and shortened"],["لَا","not"],["تَخَافُونَ ۖ","fearing"],["فَعَلِمَ","But He knew"],["مَا","what"],["لَمْ","not"],["تَعْلَمُوا۟","you knew"],["فَجَعَلَ","and He made"],["مِن","besides"],["دُونِ","besides"],["ذَٰلِكَ","that"],["فَتْحًۭا","a victory"],["قَرِيبًا","near"]]],"4611":["(Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang hak agar dimenangkan-Nya) agama yang hak itu (terhadap semua agama) atas agama-agama yang lainnya. (Dan cukuplah Allah sebagai saksi) bahwasanya kamu diutus untuk membawa hal tersebut, sebagaimana yang diungkapkan-Nya pada ayat berikut ini.",[["هُوَ","He"],["ٱلَّذِىٓ","(is) the One Who"],["أَرْسَلَ","(has) sent"],["رَسُولَهُۥ","His Messenger"],["بِٱلْهُدَىٰ","with guidance"],["وَدِينِ","and (the) religion"],["ٱلْحَقِّ","the true"],["لِيُظْهِرَهُۥ","that He (may) make it prevail"],["عَلَى","over"],["ٱلدِّينِ","the religions"],["كُلِّهِۦ ۚ","all"],["وَكَفَىٰ","And sufficient is"],["بِٱللَّهِ","Allah"],["شَهِيدًۭا","(as) a Witness"]]],"4612":["(Muhammad itu) lafal ayat ini berkedudukan menjadi Mubtada (adalah utusan Allah) menjadi Khabar dari Mubtada (dan orang-orang yang bersama dengan dia) yakni para sahabatnya yang terdiri dari kaum mukminin. Lafal ayat ini menjadi Mubtada sedangkan Khabarnya ialah (adalah keras) yakni mereka adalah orang-orang yang bersikap keras (terhadap orang-orang kafir) mereka tidak mengasihaninya (tetapi berkasih sayang sesama mereka) menjadi Khabar yang kedua; yakni mereka saling kasih-mengasihi di antara sesama mukmin bagaikan kasih orang tua kepada anaknya (kamu lihat mereka) kamu perhatikan mereka (rukuk dan sujud) keduanya merupakan Hal atau kata keterangan keadaan (mencari) lafal ayat ini merupakan jumlah Isti`naf, yakni mereka melakukan demikian dalam rangka mencari (karunia Allah dan keridaan-Nya, tanda-tanda mereka) ciri-ciri mereka, lafal ayat ini menjadi Mubtada (tampak pada muka mereka) menjadi Khabar dari Mubtada. Tanda-tanda tersebut berupa nur dan sinar yang putih bersih yang menjadi ciri khas mereka kelak di akhirat, sebagai pertanda bahwa mereka orang-orang yang gemar bersujud sewaktu di dunia (dari bekas sujud.) Lafal ayat ini berta'alluq kepada lafal yang menjadi Ta'alluq atau gantungan bagi Khabar, yaitu lafal Kaainatan. Kemudian dii'rabkan sebagai Hal karena mengingat Dhamirnya yang dipindahkan kepada Khabar. (Demikianlah) sifat-sifat yang telah disebutkan tadi (sifat-sifat mereka) yakni gambaran tentang mereka, kalimat ayat ini menjadi Mubtada (di dalam kitab Taurat) menjadi Khabarnya (dan sifat-sifat mereka dalam kitab Injil) menjadi Mubtada, sedangkan Khabarnya adalah (yaitu seperti tanaman yang mengeluarkan tunasnya) dapat dibaca Syath`ahu atau Syatha`ahu, yakni tunasnya (maka tunas itu menjadikan tanaman itu kuat) dapat dibaca Fa`aazarahuu atau Fa`azarahu, yakni tunas itu membuat tanaman menjadi kuat (lalu menjadi besarlah dia) membesarlah dia (dan tegak lurus) yakni kuat dan tegak lurus (di atas pokoknya) lafal Suuq ini adalah bentuk jamak dari lafal Saaqun (tanaman itu menyenangkan hati penanam-penanamnya) karena keindahannya. Perumpamaan ini merupakan gambaran tentang keadaan para sahabat karena mereka pada mulanya berjumlah sedikit lagi masih lemah, kemudian jumlah mereka makin bertambah banyak dan bertambah kuat dengan sistem yang sangat rapi (karena Allah hendak menjengkelkan hati orang-orang kafir dengan kekuatan orang-orang mukmin) lafal ayat ini berta'alluq kepada lafal yang tidak disebutkan yang disimpulkan dari kalimat sebelumnya, yakni mereka diserupakan demikian karena Allah hendak menjengkelkan hati orang-orang kafir (Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang saleh dari kalangan mereka) yakni para sahabat; huruf Min di sini menunjukkan makna Bayanul Jinsi atau untuk menjelaskan jenis, bukan untuk menunjukkan makna Tab'idh atau sebagian, demikian itu karena para sahabat semuanya memiliki sifat-sifat tersebut (ampunan dan pahala yang besar) yakni surga; kedua pahala itu berlaku pula bagi orang-orang sesudah mereka, sebagaimana yang telah dijelaskan dalam berbagai ayat lainnya",[["مُّحَمَّدٌۭ","Muhammad"],["رَّسُولُ","(is the) Messenger"],["ٱللَّهِ ۚ","of Allah"],["وَٱلَّذِينَ","and those who"],["مَعَهُۥٓ","(are) with him"],["أَشِدَّآءُ","(are) firm"],["عَلَى","against"],["ٱلْكُفَّارِ","the disbelievers"],["رُحَمَآءُ","and merciful"],["بَيْنَهُمْ ۖ","among themselves"],["تَرَىٰهُمْ","You see them"],["رُكَّعًۭا","bowing"],["سُجَّدًۭا","and prostrating"],["يَبْتَغُونَ","seeking"],["فَضْلًۭا","Bounty"],["مِّنَ","from Allah"],["ٱللَّهِ","from Allah"],["وَرِضْوَٰنًۭا ۖ","and pleasure"],["سِيمَاهُمْ","Their mark"],["فِى","(is) on"],["وُجُوهِهِم","their faces"],["مِّنْ","from"],["أَثَرِ","(the) trace"],["ٱلسُّجُودِ ۚ","(of) the prostration"],["ذَٰلِكَ","That"],["مَثَلُهُمْ","(is) their similitude"],["فِى","in"],["ٱلتَّوْرَىٰةِ ۚ","the Taurah"],["وَمَثَلُهُمْ","And their similitude"],["فِى","in"],["ٱلْإِنجِيلِ","the Injeel"],["كَزَرْعٍ","(is) like a seed"],["أَخْرَجَ","(which) sends forth"],["شَطْـَٔهُۥ","its shoot"],["فَـَٔازَرَهُۥ","then strengthens it"],["فَٱسْتَغْلَظَ","then it becomes thick"],["فَٱسْتَوَىٰ","and it stands"],["عَلَىٰ","upon"],["سُوقِهِۦ","its stem"],["يُعْجِبُ","delighting"],["ٱلزُّرَّاعَ","the sowers"],["لِيَغِيظَ","that He (may) enrage"],["بِهِمُ","by them"],["ٱلْكُفَّارَ ۗ","the disbelievers"],["وَعَدَ","Allah has promised"],["ٱللَّهُ","Allah has promised"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["مِنْهُم","among them"],["مَّغْفِرَةًۭ","forgiveness"],["وَأَجْرًا","and a reward"],["عَظِيمًۢا","great"]]],"4613":["(Hai orang-orang yang beriman, janganlah kalian mendahului) berasal dari lafal Qadima yang maknanya sama dengan lafal Taqaddama artinya, janganlah kalian mendahului baik melalui perkataan atau perbuatan kalian (di hadapan Allah dan Rasul-Nya) yang menyampaikan wahyu dari-Nya, makna yang dimaksud ialah janganlah kalian mendahului Allah dan Rasul-Nya tanpa izin dari keduanya (dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Mendengar) semua perkataan kalian (lagi Maha Mengetahui) semua perbuatan kalian. Ayat ini diturunkan berkenaan dengan perdebatan antara Abu Bakar r.a., dan sahabat Umar r.a. Mereka berdua melakukan perdebatan di hadapan Nabi saw. mengenai pengangkatan Aqra' bin Habis atau Qa'qa' bin Ma'bad. Ayat selanjutnya diturunkan berkenaan dengan orang yang mengangkat suaranya keras-keras di hadapan Nabi saw. yaitu firman-Nya:",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["لَا","(Do) not"],["تُقَدِّمُوا۟","put (yourselves) forward "],["بَيْنَ","before Allah"],["يَدَىِ","before Allah"],["ٱللَّهِ","before Allah"],["وَرَسُولِهِۦ ۖ","and His Messenger"],["وَٱتَّقُوا۟","and fear Allah"],["ٱللَّهَ ۚ","and fear Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَمِيعٌ","(is) All-Hearer"],["عَلِيمٌۭ","All-Knower"]]],"4614":["(\"Hai orang-orang beriman janganlah kalian meninggikan suara kalian) bila kalian berbicara (lebih dari suara Nabi) bila ia berbicara (dan janganlah kalian berkata kepadanya dengan suara keras) bila kalian berbicara dengannya (sebagaimana kerasnya suara sebagian kalian terhadap sebagian yang lain) tetapi rendahkanlah suara kalian di bawah suaranya demi untuk menghormati dan mengagungkannya (supaya tidak dihapus pahala amal kalian sedangkan kalian tidak menyadarinya\") maksudnya, takutlah kalian akan hal tersebut disebabkan suara kalian yang tinggi dan keras di hadapannya. Ayat berikutnya diturunkan berkenaan dengan orang-orang yang merendahkan suaranya di hadapan Nabi saw.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["لَا","(Do) not"],["تَرْفَعُوٓا۟","raise"],["أَصْوَٰتَكُمْ","your voices"],["فَوْقَ","above"],["صَوْتِ","(the) voice"],["ٱلنَّبِىِّ","(of) the Prophet"],["وَلَا","and (do) not"],["تَجْهَرُوا۟","be loud"],["لَهُۥ","to him"],["بِٱلْقَوْلِ","in speech"],["كَجَهْرِ","like (the) loudness"],["بَعْضِكُمْ","(of) some of you"],["لِبَعْضٍ","to others"],["أَن","lest"],["تَحْبَطَ","become worthless"],["أَعْمَـٰلُكُمْ","your deeds"],["وَأَنتُمْ","while you"],["لَا","(do) not"],["تَشْعُرُونَ","perceive"]]],"4615":["(\"Sesungguhnya orang-orang yang merendahkan suaranya di sisi Rasulullah, mereka itulah orang-orang yang telah diuji) dicoba (hati mereka oleh Allah untuk bertakwa) artinya, ujian untuk menampakkan ketakwaan mereka. (Bagi mereka ampunan dan pahala yang besar\") yakni surga. Ayat berikutnya diturunkan berkenaan dengan orang-orang yang datang di waktu tengah hari kepada Nabi saw. sedangkan Nabi saw. pada saat itu berada di dalam rumahnya, lalu mereka memanggil-manggilnya, yaitu firman-Nya:",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَغُضُّونَ","lower"],["أَصْوَٰتَهُمْ","their voices"],["عِندَ","(in) presence"],["رَسُولِ","(of the) Messenger of Allah "],["ٱللَّهِ","(of the) Messenger of Allah "],["أُو۟لَـٰٓئِكَ","those"],["ٱلَّذِينَ","(are) the ones"],["ٱمْتَحَنَ","Allah has tested"],["ٱللَّهُ","Allah has tested"],["قُلُوبَهُمْ","their hearts"],["لِلتَّقْوَىٰ ۚ","for righteousness"],["لَهُم","For them"],["مَّغْفِرَةٌۭ","(is) forgiveness"],["وَأَجْرٌ","and a reward"],["عَظِيمٌ","great"]]],"4616":["(\"Sesungguhnya orang-orang yang memanggil kamu dari luar kamar) yakni dari luar kamar istri-istrinya. Lafal Hujuraat bentuk jamak dari lafal Hujratun, yang artinya; sepetak tanah yang dikelilingi oleh tembok atau lainnya, yang digunakan sebagai tempat tinggal. Masing-masing di antara mereka memanggil Nabi saw. dari belakang kamar-kamarnya, karena mereka tidak mengetahui di kamar manakah Nabi saw. berada. Mereka memanggilnya dengan suara yang biasa dilakukan oleh orang-orang Arab Badui, yaitu dengan suara yang keras dan kasar (kebanyakan mereka tidak mengerti) tentang apa yang harus mereka kerjakan di dalam menghadapi kedudukanmu yang tinggi, dan sikap penghormatan manakah yang pantas mereka lakukan untukmu.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يُنَادُونَكَ","call you"],["مِن","from"],["وَرَآءِ","behind"],["ٱلْحُجُرَٰتِ","the private chambers"],["أَكْثَرُهُمْ","most of them"],["لَا","(do) not"],["يَعْقِلُونَ","understand"]]],"4617":["(Dan kalau sekiranya mereka bersabar) lafal Annahum berada dalam Mahall Rafa' sebagai Mubtada. Tetapi menurut pendapat lain menjadi Fa'il dari Fi'il yang diperkirakan keberadaannya, yaitu lafal Tsabata (sampai kamu keluar menemui mereka, sesungguhnya itu adalah lebih baik bagi mereka, dan Allah Maha Pengampun lagi Maha Penyayang\") kepada orang yang bertobat di antara mereka. Ayat berikut ini diturunkan berkenaan dengan Walid bin Uqbah. Ia telah diutus oleh Nabi saw. ke Bani Mushthaliq untuk menarik zakat, tetapi ia merasa takut terhadap mereka, karena dahulu di masa jahiliah ia bermusuhan dengan mereka. Akhirnya di tengah perjalanan ia kembali lagi seraya melaporkan, bahwa mereka tidak mau membayar zakat dan bahkan mereka hampir saja membunuhnya. Karena itu hampir saja Nabi saw. bermaksud untuk memerangi mereka, hanya karena mereka keburu datang menghadap Nabi saw. seraya mengingkari apa yang telah dikatakan oleh Walid mengenai mereka.",[["وَلَوْ","And if"],["أَنَّهُمْ","they"],["صَبَرُوا۟","had been patient"],["حَتَّىٰ","until"],["تَخْرُجَ","you came out"],["إِلَيْهِمْ","to them"],["لَكَانَ","certainly it would be"],["خَيْرًۭا","better"],["لَّهُمْ ۚ","for them"],["وَٱللَّهُ","And Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"4618":["(Hai orang-orang yang beriman! Jika datang kepada kalian orang fasik membawa suatu berita) (maka periksalah oleh kalian) kebenaran beritanya itu, apakah ia benar atau berdusta. Menurut suatu qiraat dibaca Fatatsabbatuu berasal dari lafal Ats-Tsabaat, artinya telitilah terlebih dahulu kebenarannya (agar kalian tidak menimpakan musibah kepada suatu kaum) menjadi Maf'ul dari lafal Fatabayyanuu, yakni dikhawatirkan hal tersebut akan menimpa musibah kepada suatu kaum (tanpa mengetahui keadaannya) menjadi Hal atau kata keterangan keadaan dari Fa'il, yakni tanpa sepengetahuannya (yang menyebabkan kalian) membuat kalian (atas perbuatan kalian itu) yakni berbuat kekeliruan terhadap kaum tersebut (menyesal) selanjutnya Rasulullah saw. mengutus Khalid kepada mereka sesudah mereka kembali ke negerinya. Ternyata Khalid tiada menjumpai mereka melainkan hanya ketaatan dan kebaikan belaka, lalu ia menceritakan hal tersebut kepada Nabi saw.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوٓا۟","O you who believe"],["إِن","If"],["جَآءَكُمْ","comes to you"],["فَاسِقٌۢ","a wicked person"],["بِنَبَإٍۢ","with information"],["فَتَبَيَّنُوٓا۟","investigate"],["أَن","lest"],["تُصِيبُوا۟","you harm"],["قَوْمًۢا","a people"],["بِجَهَـٰلَةٍۢ","in ignorance"],["فَتُصْبِحُوا۟","then you become"],["عَلَىٰ","over"],["مَا","what"],["فَعَلْتُمْ","you have done"],["نَـٰدِمِينَ","regretful"]]],"4619":["(Dan ketahuilah oleh kamu sekalian bahwa di kalangan kalian ada Rasulullah) maka janganlah sekali-kali kalian mengatakan hal-hal yang batil, karena sesungguhnya Allah akan memberitahukannya seketika itu juga. (Kalau ia menuruti kemauan kalian dalam banyak urusan) yang kalian beritakan tidak sesuai dengan kenyataannya, oleh karena itu maka hasilnya sesuai dengan apa yang kalian beritakan itu (niscaya kalian akan mendapat dosa) yakni benar-benar kalian mendapat dosa karena hal itu, yaitu dosa memberikan keterangan yang palsu (tetapi Allah menjadikan kalian cinta kepada keimanan dan menjadikan iman itu indah) yakni dipandang baik (dalam hati kalian serta menjadikan kalian benci kepada kekafiran, kefasikan dan kedurhakaan) pengertian Istidrak yang dikandung oleh lafal Laakin dipandang dari segi makna bukan lafalnya, karena sesungguhnya orang yang cinta kepada keimanan memiliki sifat-sifat berbeda dengan sifat-sifat yang dimiliki oleh orang-orang yang telah disebutkan tadi. (Mereka itulah) di dalam ungkapan ini terkandung iltifat dari Mukhathab (orang-orang yang mengikuti jalan yang lurus) yakni orang-orang yang teguh dalam agamanya.",[["وَٱعْلَمُوٓا۟","And know"],["أَنَّ","that"],["فِيكُمْ","among you"],["رَسُولَ","(is the) Messenger of Allah"],["ٱللَّهِ ۚ","(is the) Messenger of Allah"],["لَوْ","If"],["يُطِيعُكُمْ","he were to obey you"],["فِى","in"],["كَثِيرٍۢ","much"],["مِّنَ","of"],["ٱلْأَمْرِ","the matter"],["لَعَنِتُّمْ","surely you would be in difficulty"],["وَلَـٰكِنَّ","but"],["ٱللَّهَ","Allah"],["حَبَّبَ","has endeared"],["إِلَيْكُمُ","to you"],["ٱلْإِيمَـٰنَ","the Faith"],["وَزَيَّنَهُۥ","and has made it pleasing"],["فِى","in"],["قُلُوبِكُمْ","your hearts"],["وَكَرَّهَ","and has made hateful"],["إِلَيْكُمُ","to you"],["ٱلْكُفْرَ","disbelief"],["وَٱلْفُسُوقَ","and defiance"],["وَٱلْعِصْيَانَ ۚ","and disobedience"],["أُو۟لَـٰٓئِكَ","Those"],["هُمُ","(are) they "],["ٱلرَّٰشِدُونَ","the guided ones"]]],"4620":["(Sebagai karunia dari Allah) lafal Fadhlan adalah Mashdar yang dinashabkan oleh Fi'ilnya yang keberadaannya diperkirakan sebelumnya, yaitu lafal Afdhala (dan nikmat) dari-Nya. (Dan Allah Maha Mengetahui) keadaan mereka (lagi Maha Bijaksana) di dalam memberikan nikmat-Nya kepada mereka.",[["فَضْلًۭا","A Bounty"],["مِّنَ","from Allah"],["ٱللَّهِ","from Allah"],["وَنِعْمَةًۭ ۚ","and favor"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"4621":["(Dan jika ada dua golongan dari orang-orang mukmin) hingga akhir ayat. Ayat ini diturunkan berkenaan dengan suatu masalah, yaitu bahwa Nabi saw. pada suatu hari menaiki keledai kendaraannya, lalu ia melewati Ibnu Ubay. Ketika melewatinya tiba-tiba keledai yang dinaikinya itu kencing, lalu Ibnu Ubay menutup hidungnya, maka berkatalah Ibnu Rawwahah kepadanya, \"Demi Allah, sungguh bau kencing keledainya jauh lebih wangi daripada bau minyak kesturimu itu,\" maka terjadilah antara kaum mereka berdua saling baku hantam dengan tangan, terompah dan pelepah kurma (berperang) Dhamir yang ada pada ayat ini dijamakkan karena memandang dari segi makna yang dikandung lafal Thaaifataani, karena masing-masing Thaaifah atau golongan terdiri dari sekelompok orang. Menurut suatu qiraat ada pula yang membacanya Iqtatalataa, yakni hanya memandang dari segi lafal saja (maka damaikanlah antara keduanya) dan Dhamir pada lafal ini ditatsniyahkan karena memandang dari segi lafal. (Jika berbuat aniaya) atau berbuat melewati batas (salah satu dari kedua golongan itu terhadap golongan yang lain maka perangilah golongan yang berbuat aniaya itu sehingga golongan itu kembali) artinya, rujuk kembali (kepada perintah Allah) kepada jalan yang benar (jika golongan itu telah kembali kepada perintah Allah maka damaikanlah antara keduanya dengan adil) yaitu dengan cara pertengahan (dan berlaku adillah) bersikap jangan memihaklah. (Sesungguhnya Allah menyukai orang-orang yang berlaku adil.)",[["وَإِن","And if"],["طَآئِفَتَانِ","two parties"],["مِنَ","among"],["ٱلْمُؤْمِنِينَ","the believers"],["ٱقْتَتَلُوا۟","fight"],["فَأَصْلِحُوا۟","then make peace"],["بَيْنَهُمَا ۖ","between both of them"],["فَإِنۢ","But if"],["بَغَتْ","oppresses"],["إِحْدَىٰهُمَا","one of them"],["عَلَى","on"],["ٱلْأُخْرَىٰ","the other"],["فَقَـٰتِلُوا۟","then fight"],["ٱلَّتِى","one which"],["تَبْغِى","oppresses"],["حَتَّىٰ","until"],["تَفِىٓءَ","it returns"],["إِلَىٰٓ","to"],["أَمْرِ","(the) command"],["ٱللَّهِ ۚ","(of) Allah"],["فَإِن","Then if"],["فَآءَتْ","it returns"],["فَأَصْلِحُوا۟","then make peace"],["بَيْنَهُمَا","between them"],["بِٱلْعَدْلِ","with justice"],["وَأَقْسِطُوٓا۟ ۖ","and act justly"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يُحِبُّ","loves"],["ٱلْمُقْسِطِينَ","those who act justly"]]],"4622":["(Sesungguhnya orang-orang mukmin adalah saudara) dalam seagama (karena itu damaikanlah antara kedua saudara kalian) apabila mereka berdua bersengketa. Menurut qiraat yang lain dibaca Ikhwatikum, artinya saudara-saudara kalian (dan bertakwalah kepada Allah supaya kalian mendapat rahmat.)",[["إِنَّمَا","Only"],["ٱلْمُؤْمِنُونَ","the believers"],["إِخْوَةٌۭ","(are) brothers"],["فَأَصْلِحُوا۟","so make peace"],["بَيْنَ","between"],["أَخَوَيْكُمْ ۚ","your brothers"],["وَٱتَّقُوا۟","and fear Allah"],["ٱللَّهَ","and fear Allah"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"4623":["(Hai orang-orang yang beriman, janganlah berolok-olokan) dan seterusnya, ayat ini diturunkan berkenaan dengan delegasi dari Bani Tamim sewaktu mereka mengejek orang-orang muslim yang miskin, seperti Ammar bin Yasir dan Shuhaib Ar-Rumi. As-Sukhriyah artinya merendahkan dan menghina (suatu kaum) yakni sebagian di antara kalian (kepada kaum yang lain karena boleh jadi mereka yang diolok-olokkan lebih baik dari mereka yang mengolok-olokkan) di sisi Allah (dan jangan pula wanita-wanita) di antara kalian mengolok-olokkan (wanita-wanita lain karena boleh jadi wanita-wanita yang diperolok-olokkan lebih baik dari wanita-wanita yang mengolok-olokkan dan janganlah kalian mencela diri kalian sendiri) artinya, janganlah kalian mencela, maka karenanya kalian akan dicela; makna yang dimaksud ialah, janganlah sebagian dari kalian mencela sebagian yang lain (dan janganlah kalian panggil-memanggil dengan gelar-gelar yang buruk) yaitu janganlah sebagian di antara kalian memanggil sebagian yang lain dengan nama julukan yang tidak disukainya, antara lain seperti, hai orang fasik, atau hai orang kafir. (Seburuk-buruk nama) panggilan yang telah disebutkan di atas, yaitu memperolok-olokkan orang lain mencela dan memanggil dengan nama julukan yang buruk (ialah nama yang buruk sesudah iman) lafal Al-Fusuuq merupakan Badal dari lafal Al-Ismu, karena nama panggilan yang dimaksud memberikan pengertian fasik dan juga karena nama panggilan itu biasanya diulang-ulang (dan barang siapa yang tidak bertobat) dari perbuatan tersebut (maka mereka itulah orang-orang yang lalim.)",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["لَا","(Let) not"],["يَسْخَرْ","ridicule"],["قَوْمٌۭ","a people"],["مِّن","[of]"],["قَوْمٍ","(another) people"],["عَسَىٰٓ","perhaps"],["أَن","that"],["يَكُونُوا۟","they may be"],["خَيْرًۭا","better"],["مِّنْهُمْ","than them"],["وَلَا","and (let) not"],["نِسَآءٌۭ","women"],["مِّن","[of]"],["نِّسَآءٍ","(other) women"],["عَسَىٰٓ","perhaps"],["أَن","that"],["يَكُنَّ","they may be"],["خَيْرًۭا","better"],["مِّنْهُنَّ ۖ","than them"],["وَلَا","And (do) not"],["تَلْمِزُوٓا۟","insult"],["أَنفُسَكُمْ","yourselves"],["وَلَا","and (do) not"],["تَنَابَزُوا۟","call each other"],["بِٱلْأَلْقَـٰبِ ۖ","by nicknames"],["بِئْسَ","Wretched is"],["ٱلِٱسْمُ","the name"],["ٱلْفُسُوقُ","(of) disobedience"],["بَعْدَ","after"],["ٱلْإِيمَـٰنِ ۚ","the faith"],["وَمَن","And whoever"],["لَّمْ","(does) not"],["يَتُبْ","repent"],["فَأُو۟لَـٰٓئِكَ","then those "],["هُمُ","they"],["ٱلظَّـٰلِمُونَ","(are) the wrongdoers"]]],"4624":["(Hai orang-orang yang beriman, jauhilah kebanyakan dari prasangka, sesungguhnya sebagian prasangka itu adalah dosa) artinya, menjerumuskan kepada dosa, jenis prasangka itu cukup banyak, antara lain ialah berburuk sangka kepada orang mukmin yang selalu berbuat baik. Orang-orang mukmin yang selalu berbuat baik itu cukup banyak, berbeda keadaannya dengan orang-orang fasik dari kalangan kaum muslimin, maka tiada dosa bila kita berburuk sangka terhadapnya menyangkut masalah keburukan yang tampak dari mereka (dan janganlah kalian mencari-cari kesalahan orang lain) lafal Tajassasuu pada asalnya adalah Tatajassasuu, lalu salah satu dari kedua huruf Ta dibuang sehingga jadilah Tajassasuu, artinya janganlah kalian mencari-cari aurat dan keaiban mereka dengan cara menyelidikinya (dan janganlah sebagian kalian menggunjing sebagian yang lain) artinya, janganlah kamu mempergunjingkan dia dengan sesuatu yang tidak diakuinya, sekalipun hal itu benar ada padanya. (Sukakah salah seorang di antara kalian memakan daging saudaranya yang sudah mati?) lafal Maytan dapat pula dibaca Mayyitan; maksudnya tentu saja hal ini tidak layak kalian lakukan. (Maka tentulah kalian merasa jijik kepadanya) maksudnya, mempergunjingkan orang semasa hidupnya sama saja artinya dengan memakan dagingnya sesudah ia mati. Kalian jelas tidak akan menyukainya, oleh karena itu janganlah kalian melakukan hal ini. (Dan bertakwalah kepada Allah) yakni takutlah akan azab-Nya bila kalian hendak mempergunjingkan orang lain, maka dari itu bertobatlah kalian dari perbuatan ini (sesungguhnya Allah Maha Penerima tobat) yakni selalu menerima tobat orang-orang yang bertobat (lagi Maha Penyayang) kepada mereka yang bertobat.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["ٱجْتَنِبُوا۟","Avoid"],["كَثِيرًۭا","much"],["مِّنَ","of"],["ٱلظَّنِّ","the assumption"],["إِنَّ","Indeed"],["بَعْضَ","some"],["ٱلظَّنِّ","assumption"],["إِثْمٌۭ ۖ","(is) sin"],["وَلَا","And (do) not"],["تَجَسَّسُوا۟","spy"],["وَلَا","and (do) not"],["يَغْتَب","backbite"],["بَّعْضُكُم","some of you"],["بَعْضًا ۚ","(to) others"],["أَيُحِبُّ","Would like"],["أَحَدُكُمْ","one of you"],["أَن","to"],["يَأْكُلَ","eat"],["لَحْمَ","(the) flesh"],["أَخِيهِ","(of) his brother"],["مَيْتًۭا","dead"],["فَكَرِهْتُمُوهُ ۚ","Nay, you would hate it"],["وَٱتَّقُوا۟","And fear Allah"],["ٱللَّهَ ۚ","And fear Allah"],["إِنَّ","indeed"],["ٱللَّهَ","Allah"],["تَوَّابٌۭ","(is) Oft-Returning"],["رَّحِيمٌۭ","Most Merciful"]]],"4625":["(Hai manusia, sesungguhnya Kami menciptakan kalian dari seorang laki-laki dan seorang perempuan) yakni dari Adam dan Hawa (dan Kami menjadikan kalian berbangsa-bangsa) lafal Syu'uuban adalah bentuk jamak dari lafal Sya'bun, yang artinya tingkatan nasab keturunan yang paling tinggi (dan bersuku-suku) kedudukan suku berada di bawah bangsa, setelah suku atau kabilah disebut Imarah, lalu Bathn, sesudah Bathn adalah Fakhdz dan yang paling bawah adalah Fashilah. Contohnya ialah Khuzaimah adalah nama suatu bangsa, Kinanah adalah nama suatu kabilah atau suku, Quraisy adalah nama suatu Imarah, Qushay adalah nama suatu Bathn, Hasyim adalah nama suatu Fakhdz, dan Al-Abbas adalah nama suatu Fashilah (supaya kalian saling kenal-mengenal) lafal Ta'aarafuu asalnya adalah Tata'aarafuu, kemudian salah satu dari kedua huruf Ta dibuang sehingga jadilah Ta'aarafuu; maksudnya supaya sebagian dari kalian saling mengenal sebagian yang lain bukan untuk saling membanggakan ketinggian nasab atau keturunan, karena sesungguhnya kebanggaan itu hanya dinilai dari segi ketakwaan. (Sesungguhnya orang yang paling mulia di antara kalian di sisi Allah ialah orang yang paling bertakwa. Sesungguhnya Allah Maha Mengetahui) tentang kalian (lagi Maha Mengenal) apa yang tersimpan di dalam batin kalian.",[["يَـٰٓأَيُّهَا","O mankind"],["ٱلنَّاسُ","O mankind"],["إِنَّا","Indeed, We"],["خَلَقْنَـٰكُم","created you"],["مِّن","from"],["ذَكَرٍۢ","a male"],["وَأُنثَىٰ","and a female"],["وَجَعَلْنَـٰكُمْ","and We made you"],["شُعُوبًۭا","nations"],["وَقَبَآئِلَ","and tribes"],["لِتَعَارَفُوٓا۟ ۚ","that you may know one another"],["إِنَّ","Indeed"],["أَكْرَمَكُمْ","(the) most noble of you"],["عِندَ","near"],["ٱللَّهِ","Allah"],["أَتْقَىٰكُمْ ۚ","(is the) most righteous of you"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌ","(is) All-Knower"],["خَبِيرٌۭ","All-Aware"]]],"4626":["(Orang-orang Arab Badui itu berkata,) yang dimaksud adalah segolongan dari kalangan Bani Asad (\"Kami telah beriman\") yakni hati kami telah beriman. (Katakanlah) kepada mereka, (\"Kalian belum beriman, tetapi katakanlah, 'Kami telah berserah diri,'\") artinya, kami telah tunduk secara lahiriah (karena masih belumlah) yakni masih belum lagi (iman masuk ke dalam hati kalian) sampai sekarang hanya saja hal itu baru merupakan dugaan bagi kalian (dan jika kalian taat kepada Allah dan Rasul-Nya) yakni dengan cara beriman yang sesungguhnya dan taat dalam segala hal (Dia tidak akan mengurangi) Dia tidak akan mengurangkan (amal-amal kalian) yakni pahala amal-amal kalian (barang sedikit pun; sesungguhnya Allah Maha Pengampun) kepada orang-orang mukmin (lagi Maha Penyayang\") kepada mereka.",[["۞ قَالَتِ","Say"],["ٱلْأَعْرَابُ","the Bedouins"],["ءَامَنَّا ۖ","We believe"],["قُل","Say"],["لَّمْ","Not"],["تُؤْمِنُوا۟","you believe"],["وَلَـٰكِن","but"],["قُولُوٓا۟","say"],["أَسْلَمْنَا","We have submitted"],["وَلَمَّا","and has not yet"],["يَدْخُلِ","entered"],["ٱلْإِيمَـٰنُ","the faith"],["فِى","in"],["قُلُوبِكُمْ ۖ","your hearts"],["وَإِن","But if"],["تُطِيعُوا۟","you obey"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["لَا","not"],["يَلِتْكُم","He will deprive you"],["مِّنْ","of"],["أَعْمَـٰلِكُمْ","your deeds"],["شَيْـًٔا ۚ","anything"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌ","Most Merciful"]]],"4627":["(Sesungguhnya orang-orang yang beriman) yakni orang-orang yang benar-benar beriman, sebagaimana yang telah diterangkan sebelumnya (hanyalah orang-orang yang beriman kepada Allah dan Rasul-Nya kemudian mereka tidak ragu-ragu) dalam keimanannya (dan mereka berjihad dengan harta dan jiwa mereka pada jalan Allah) mereka benar-benar berjihad berkat kesungguhan iman mereka (mereka itulah orang-orang yang benar) dalam keimanan mereka, bukan seperti orang-orang yang mengatakan, \"Kami telah beriman\", sedangkan dalam diri mereka yang dijumpai hanya ketundukan belaka.",[["إِنَّمَا","Only"],["ٱلْمُؤْمِنُونَ","the believers"],["ٱلَّذِينَ","(are) those who"],["ءَامَنُوا۟","believe"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِۦ","and His Messenger"],["ثُمَّ","then"],["لَمْ","(do) not"],["يَرْتَابُوا۟","doubt"],["وَجَـٰهَدُوا۟","but strive"],["بِأَمْوَٰلِهِمْ","with their wealth"],["وَأَنفُسِهِمْ","and their lives"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۚ","(of) Allah"],["أُو۟لَـٰٓئِكَ","Those"],["هُمُ","[they]"],["ٱلصَّـٰدِقُونَ","(are) the truthful"]]],"4628":["(Katakanlah) kepada mereka (\"Apakah kalian akan memberitahukan kepada Allah tentang agama kalian) lafal Tu'allimuuna berasal dari 'Allama yang artinya Sya'ara atau memberitahukan. Maksudnya, apakah kalian melalui perkataan kalian, 'Kami telah beriman', hendak memberitahukan kepada Allah tentang keyakinan kalian (padahal Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan Allah Mengetahui segala sesuatu.\")",[["قُلْ","Say"],["أَتُعَلِّمُونَ","Will you acquaint"],["ٱللَّهَ","Allah"],["بِدِينِكُمْ","with your religion"],["وَٱللَّهُ","while Allah"],["يَعْلَمُ","knows"],["مَا","what"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and what"],["فِى","(is) in"],["ٱلْأَرْضِ ۚ","the earth"],["وَٱللَّهُ","And Allah"],["بِكُلِّ","of every"],["شَىْءٍ","thing"],["عَلِيمٌۭ","(is) All-Knower"]]],"4629":["(Mereka telah merasa memberi nikmat kepadamu dengan keislaman mereka) tanpa melalui perang, berbeda dengan orang-orang selain mereka yang masuk Islam setelah melalui peperangan terlebih dahulu. (Katakanlah, \"Janganlah kalian merasa telah memberi nikmat kepadaku dengan keislaman kalian) lafal Islamakum dinashabkan karena huruf Jarrnya yaitu Ba dicabut darinya, sebagaimana keberadaan huruf Ba ini diperkirakan pula sebelum An pada permulaan ayat (sebenarnya Allah Dialah yang melimpahkan nikmat kepada kalian dengan menunjuki kalian kepada keimanan, jika kalian adalah orang-orang yang benar\") di dalam perkataan kalian yang menyatakan, \"Kami telah beriman.\"",[["يَمُنُّونَ","They consider (it) a favor"],["عَلَيْكَ","to you"],["أَنْ","that"],["أَسْلَمُوا۟ ۖ","they have accepted Islam"],["قُل","Say"],["لَّا","(Do) not"],["تَمُنُّوا۟","consider a favor"],["عَلَىَّ","on me "],["إِسْلَـٰمَكُم ۖ","your Islam"],["بَلِ","Nay"],["ٱللَّهُ","Allah"],["يَمُنُّ","has conferred a favor"],["عَلَيْكُمْ","upon you"],["أَنْ","that"],["هَدَىٰكُمْ","He has guided you"],["لِلْإِيمَـٰنِ","to the faith"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"4630":["(Sesungguhnya Allah mengetahui apa yang gaib di langit dan di bumi) yakni apa-apa yang tidak kelihatan pada keduanya. (Dan Allah Maha Melihat apa yang kalian kerjakan) dapat dibaca Ta'maluuna atau Ya'maluuna, kalau dibaca Ya'maluuna artinya, Allah Maha Melihat apa yang mereka kerjakan. Maksudnya tiada sesuatu pun darinya yang samar bagi-Nya.",[["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَعْلَمُ","knows"],["غَيْبَ","(the) unseen"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَٱللَّهُ","And Allah"],["بَصِيرٌۢ","(is) All-Seer"],["بِمَا","of what"],["تَعْمَلُونَ","you do"]]],"4631":["(Qaaf) hanya Allah saja yang mengetahui arti dan maksudnya. (Demi Alquran yang sangat agung) artinya, yang sangat mulia, tiadalah orang-orang kafir Mekah beriman kepada Nabi Muhammad saw.",[["قٓ ۚ","Qaf"],["وَٱلْقُرْءَانِ","By the Quran"],["ٱلْمَجِيدِ","the Glorious"]]],"4632":["(Bahkan mereka tercengang karena telah datang kepada mereka seorang pemberi peringatan dari kalangan mereka sendiri) yakni seorang rasul yang memperingatkan mereka tentang adanya azab neraka sesudah hari berbangkit, bila mereka tidak beriman (maka berkatalah orang-orang kafir, \"Ini) tentang peringatan itu (adalah suatu hal yang amat ajaib.)",[["بَلْ","Nay"],["عَجِبُوٓا۟","they wonder"],["أَن","that"],["جَآءَهُم","has come to them"],["مُّنذِرٌۭ","a warner"],["مِّنْهُمْ","from them"],["فَقَالَ","So say"],["ٱلْكَـٰفِرُونَ","the disbelievers"],["هَـٰذَا","This"],["شَىْءٌ","(is) a thing"],["عَجِيبٌ","amazing"]]],"4633":["(Apakah bila) dapat dibaca Tahqiq, dapat pula dibaca Tas-hil (kami telah mati dan setelah menjadi tanah) kami akan kembali menjadi hidup? (itu adalah suatu pengembalian yang tidak mungkin\") yakni sangat jauh dari kemungkinan.",[["أَءِذَا","What! When"],["مِتْنَا","we die"],["وَكُنَّا","and have become"],["تُرَابًۭا ۖ","dust"],["ذَٰلِكَ","That"],["رَجْعٌۢ","(is) a return"],["بَعِيدٌۭ","far"]]],"4634":["(Sesungguhnya Kami telah mengetahui apa yang dihancurkan oleh bumi) apa yang telah dimakan olehnya (dari tubuh-tubuh mereka, dan pada sisi Kami ada kitab yang memelihara) yaitu Lohmahfuz, di dalamnya telah tertera segala sesuatu yang telah dipastikan ketentuannya.",[["قَدْ","Certainly"],["عَلِمْنَا","We know"],["مَا","what"],["تَنقُصُ","diminishes"],["ٱلْأَرْضُ","the earth"],["مِنْهُمْ ۖ","of them"],["وَعِندَنَا","and with Us"],["كِتَـٰبٌ","(is) a Book"],["حَفِيظٌۢ","guarded"]]],"4635":["(Sebenarnya mereka telah mendustakan kebenaran) yakni Alquran (tatkala kebenaran itu datang kepada mereka, maka mereka) menanggapi tentang perihal Nabi saw. dan Alquran (berada dalam keadaan kacau-balau) yakni tidak menentu, terkadang mereka mengatakan, bahwa Nabi adalah penyihir dan Alquran adalah sihir, terkadang juga mengatakan bahwa dia adalah penyair dan Alquran adalah syairnya, terkadang mereka mengatakan bahwa dia adalah seorang peramal dan Alquran adalah ramalannya.",[["بَلْ","Nay"],["كَذَّبُوا۟","they denied"],["بِٱلْحَقِّ","the truth"],["لَمَّا","when"],["جَآءَهُمْ","it came (to) them"],["فَهُمْ","so they"],["فِىٓ","(are) in"],["أَمْرٍۢ","a state"],["مَّرِيجٍ","confused"]]],"4636":["(Maka apakah mereka tidak melihat) dengan mata mereka. Padahal mata itu, dipasang untuk mengambil pelajaran dari apa yang dilihatnya, yaitu sewaktu mereka ingkar kepada adanya hari berbangkit (akan langit) yang ada (di atas mereka bagaimana Kami telah membangunnya) tanpa tiang penyangga (dan Kami hiasi dia) dengan bintang-bintang (dan langit itu tidak mempunyai retak-retak sedikit pun?) yakni tidak ada celah-celah yang membuatnya cacat.",[["أَفَلَمْ","Then do not"],["يَنظُرُوٓا۟","they look"],["إِلَى","at"],["ٱلسَّمَآءِ","the sky"],["فَوْقَهُمْ","above them "],["كَيْفَ","how"],["بَنَيْنَـٰهَا","We structured it"],["وَزَيَّنَّـٰهَا","and adorned it"],["وَمَا","and not"],["لَهَا","for it"],["مِن","any"],["فُرُوجٍۢ","rifts"]]],"4637":["(Dan bumi itu) di'athafkan kepada kedudukan lafal As-samaa' yakni, dan bumi itu bagaimana (Kami hamparkan) Kami jadikan terhampar menurut pandangan mata di atas permukaan air (dan Kami letakkan padanya gunung-gunung) yang memantapkannya (dan Kami tumbuhkan padanya segala macam tanaman) segala jenis tumbuh-tumbuhan (yang indah) yang tampak sangat indah dipandang mata karena keindahannya.",[["وَٱلْأَرْضَ","And the earth"],["مَدَدْنَـٰهَا","We have spread it out"],["وَأَلْقَيْنَا","and cast"],["فِيهَا","therein"],["رَوَٰسِىَ","firmly set mountains"],["وَأَنۢبَتْنَا","and We made to grow"],["فِيهَا","therein"],["مِن","of"],["كُلِّ","every"],["زَوْجٍۭ","kind"],["بَهِيجٍۢ","beautiful"]]],"4638":["(Untuk menjadi pelajaran) menjadi maf'ul lah, yakni, Kami lakukan hal tersebut sebagai pemberian pelajaran dari Kami (dan peringatan) untuk dijadikan sebagai peringatan (bagi tiap-tiap hamba yang kembali) untuk taat kepada Kami.",[["تَبْصِرَةًۭ","Giving insight"],["وَذِكْرَىٰ","and a reminder"],["لِكُلِّ","for every"],["عَبْدٍۢ","slave"],["مُّنِيبٍۢ","who turns"]]],"4639":["(Dan Kami turunkan dari langit air yang penuh keberkatan) berkah dan manfaatnya (lalu Kami tumbuhkan dengan air itu pohon-pohon) maksudnya kebun-kebun (dan biji-biji tanaman) yakni ladang-ladang (yang diketam) yang dipanen.",[["وَنَزَّلْنَا","And We have sent down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["مُّبَـٰرَكًۭا","blessed"],["فَأَنۢبَتْنَا","then We made to grow"],["بِهِۦ","thereby"],["جَنَّـٰتٍۢ","gardens"],["وَحَبَّ","and grain"],["ٱلْحَصِيدِ","(for) the harvest"]]],"4640":["(Dan pohon-pohon kurma yang tinggi-tinggi) lafal Baasiqaatin ini berkedudukan menjadi Hal bagi lafal yang diperkirakan keberadaannya (yang mempunyai mayang yang bersusun-susun) yaitu sebagian di antaranya bertumpuk di atas sebagian yang lain.",[["وَٱلنَّخْلَ","And the palms trees"],["بَاسِقَـٰتٍۢ","tall "],["لَّهَا","for it"],["طَلْعٌۭ","(are) layers"],["نَّضِيدٌۭ","arranged"]]],"4641":["(Untuk menjadi rezeki bagi hamba-hamba) Kami; lafal Rizqan menjadi Maf'ul Lah (dan Kami hidupkan dengan air itu tanah yang mati) lafal Maytan dapat digunakan untuk Mudzakkar dan Muannats. (Seperti itulah) dengan cara itulah (terjadinya kebangkitan) dari kubur, maka mengapa kalian mengingkarinya? Istifham atau kata tanya mengandung makna Taqrir, makna yang dimaksud adalah bahwa mereka melihat dan mengetahui hal tersebut.",[["رِّزْقًۭا","A provision"],["لِّلْعِبَادِ ۖ","for the slaves"],["وَأَحْيَيْنَا","and We give life"],["بِهِۦ","therewith"],["بَلْدَةًۭ","(to) a land"],["مَّيْتًۭا ۚ","dead"],["كَذَٰلِكَ","Thus"],["ٱلْخُرُوجُ","(will be) the coming forth"]]],"4642":["(Sebelum mereka telah mendustakan pula kaum Nuh) di-ta`nits-kannya dhamir yang ada pada lafal Kadzdzabat karena memandang makna yang terkandung dalam lafal Qaumun (dan penduduk Rass) Rass adalah nama sebuah sumur yang di sekitarnya tinggal suatu kaum berikut ternak mereka; mereka menyembah berhala, menurut suatu pendapat nabi mereka bernama Hanzhalah bin Shafwan; menurut pendapat lainnya bukanlah dia, (dan Tsamud) yaitu kaum Nabi Shaleh.",[["كَذَّبَتْ","Denied"],["قَبْلَهُمْ","before them"],["قَوْمُ","(the) people"],["نُوحٍۢ","(of) Nuh"],["وَأَصْحَـٰبُ","and (the) companions"],["ٱلرَّسِّ","(of) Ar-Raas"],["وَثَمُودُ","and Thamud"]]],"4643":["(Dan kaum Ad) kaum Nabi Hud (kaum Firaun dan kaum Luth.)",[["وَعَادٌۭ","And Aad"],["وَفِرْعَوْنُ","and Firaun"],["وَإِخْوَٰنُ","and (the) brothers"],["لُوطٍۢ","(of) Lut"]]],"4644":["(Dan penduduk Aikah) yakni penduduk Ghaidhah kaum Nabi Syuaib (serta kaum Tubba') Tubba' adalah nama raja di negeri Yaman; ia masuk Islam lalu menyeru kaumnya untuk masuk Islam, tetapi mereka mendustakannya (masing-masing) dari kaum-kaum yang telah disebutkan tadi (mendustakan rasul-rasul) sebagaimana yang dilakukan oleh kabilah Quraisy (maka sudah semestinya mereka mendapat ancaman-Ku) artinya sudah semestinya semuanya menerima azab-Ku, maka janganlah kamu susah dengan kekafiran orang-orang Quraisy terhadap dirimu.",[["وَأَصْحَـٰبُ","And (the) companions"],["ٱلْأَيْكَةِ","(of) the wood"],["وَقَوْمُ","and (the) people"],["تُبَّعٍۢ ۚ","(of) Tubba"],["كُلٌّۭ","All"],["كَذَّبَ","denied"],["ٱلرُّسُلَ","the Messengers"],["فَحَقَّ","so was fulfilled"],["وَعِيدِ","My Threat"]]],"4645":["(Maka apakah Kami letih dengan penciptaan yang pertama?) maksudnya, Kami tidak merasa letih dengan penciptaan yang pertama itu, demikian pula Kami tidak merasa letih untuk mengembalikan mereka. (Sebenarnya mereka dalam keadaan ragu-ragu) yakni berada dalam keragu-raguan (tentang penciptaan yang baru) yaitu membangkitkan mereka menjadi hidup kembali pada hari berbangkit nanti.",[["أَفَعَيِينَا","Were We then tired"],["بِٱلْخَلْقِ","with the creation"],["ٱلْأَوَّلِ ۚ","the first"],["بَلْ","Nay"],["هُمْ","they"],["فِى","(are) in"],["لَبْسٍۢ","doubt"],["مِّنْ","about"],["خَلْقٍۢ","a creation"],["جَدِيدٍۢ","new"]]],"4646":["(Dan sesungguhnya Kami telah menciptakan manusia sedangkan Kami mengetahui) lafal Na'lamu ini berkedudukan menjadi Hal atau kata keterangan keadaan dan sebelumnya diperkirakan adanya lafal Nahnu (apa) huruf Maa di sini adalah Mashdariyah (yang dibisikkan) dibicarakan (oleh dia) yakni oleh manusia, huruf Ba di sini adalah Zaidah, atau untuk Ta'diyah (dalam hatinya, dan Kami lebih dekat kepadanya) maksudnya ilmu Kami (daripada urat lehernya) Idhafah di sini mengandung makna Bayan atau untuk menjelaskan, dan pengertian yang dimaksud dari lafal Al-Wariid adalah dua urat vital yang terdapat pada bagian belakang leher.",[["وَلَقَدْ","And certainly"],["خَلَقْنَا","We created"],["ٱلْإِنسَـٰنَ","man"],["وَنَعْلَمُ","and We know"],["مَا","what"],["تُوَسْوِسُ","whispers"],["بِهِۦ","to him"],["نَفْسُهُۥ ۖ","his soul"],["وَنَحْنُ","and We"],["أَقْرَبُ","(are) nearer"],["إِلَيْهِ","to him"],["مِنْ","than"],["حَبْلِ","(his) jugular vein"],["ٱلْوَرِيدِ","(his) jugular vein"]]],"4647":["(Ingatlah ketika) lafal Idz di sini dinashabkan oleh lafal Udzkur yang keberadaannya diperkirakan (mencatat) yakni menulis (dua malaikat pencatat amal) artinya, yang diserahi tugas oleh Allah untuk mencatat amal perbuatan yang dilakukan oleh manusia (yang satu berada di sebelah kanan dan yang lain berada di sebelah kiri) manusia (dalam keadaan duduk) yakni keduanya duduk, lafal Qa'iid ini adalah Mubtada dan Khabarnya adalah lafal sebelumnya.",[["إِذْ","When"],["يَتَلَقَّى","receive"],["ٱلْمُتَلَقِّيَانِ","the two receivers"],["عَنِ","on"],["ٱلْيَمِينِ","the right"],["وَعَنِ","and on"],["ٱلشِّمَالِ","the left"],["قَعِيدٌۭ","seated"]]],"4648":["(Tiada suatu ucapan pun yang dikatakan melainkan ada malaikat pengawas) yakni malaikat pencatat amal (yang selalu hadir) selalu berada di sisinya; lafal Raqiib dan 'Atiid ini keduanya mengandung makna Mutsanna.",[["مَّا","Not"],["يَلْفِظُ","he utters"],["مِن","any"],["قَوْلٍ","word"],["إِلَّا","but"],["لَدَيْهِ","with him"],["رَقِيبٌ","(is) an observer"],["عَتِيدٌۭ","ready"]]],"4649":["(Dan datanglah sakaratul maut) yakni kesusahan dan rasa sakit yang memuncak menjelang maut (dengan membawa kebenaran) yakni perkara akhirat, hingga orang yang ingkar kepada hari akhirat dapat melihatnya secara nyata, hal ini termasuk pula hal yang menyakitkan. (Itulah) kematian itu (hal yang kamu tidak dapat menghindar darinya) yakni tidak dapat melarikan diri darinya.",[["وَجَآءَتْ","And will come"],["سَكْرَةُ","(the) stupor"],["ٱلْمَوْتِ","(of) death"],["بِٱلْحَقِّ ۖ","in truth"],["ذَٰلِكَ","That"],["مَا","(is) what"],["كُنتَ","you were"],["مِنْهُ","[from it]"],["تَحِيدُ","avoiding"]]],"4650":["(Dan ditiuplah sangkakala) untuk membangkitkan manusia. (Itulah) yakni hari peniupan itu (hari terlaksananya ancaman) bagi orang-orang kafir, yaitu mereka akan mengalami siksaan.",[["وَنُفِخَ","And will be blown"],["فِى","[in]"],["ٱلصُّورِ ۚ","the trumpet"],["ذَٰلِكَ","That"],["يَوْمُ","(is the) Day"],["ٱلْوَعِيدِ","(of) the Warning"]]],"4651":["(Dan datanglah) pada hari itu (tiap-tiap diri) ke tempat mereka dikumpulkan yaitu padang Mahsyar (bersama dengan dia penggiringnya) yaitu malaikat yang menggiringnya ke padang Mahsyar (dan pemberi saksi) yang akan memberikan kesaksian tentang semua amal perbuatannya, yaitu tangan dan kakinya serta anggota-anggota tubuhnya yang lain. Kemudian pada saat itu dikatakan kepada orang yang kafir:",[["وَجَآءَتْ","And will come"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["مَّعَهَا","with it"],["سَآئِقٌۭ","a driver"],["وَشَهِيدٌۭ","and a witness"]]],"4652":["(\"Sesungguhnya kamu) sewaktu di dunia (berada dalam keadaan lalai dari hal ini) yang sekarang menimpa kamu (maka Kami singkapkan daripadamu tutupmu) maksudnya, Kami lenyapkan kelalaianmu dengan apa yang kamu saksikan sekarang ini (maka penglihatanmu pada hari ini tajam\") yakni menjadi terang dan dapat melihat apa yang kamu ingkari sewaktu di dunia.",[["لَّقَدْ","Certainly"],["كُنتَ","you were"],["فِى","in"],["غَفْلَةٍۢ","heedlessness"],["مِّنْ","of"],["هَـٰذَا","this"],["فَكَشَفْنَا","So We have removed"],["عَنكَ","from you"],["غِطَآءَكَ","your cover"],["فَبَصَرُكَ","so your sight"],["ٱلْيَوْمَ","today"],["حَدِيدٌۭ","(is) sharp"]]],"4653":["(Dan yang menyertai dia berkata,) yakni malaikat yang diserahi tugas mencatat amal perbuatannya: (\"Inilah apa) yakni catatan amalmu (yang ada pada sisiku\") yakni catatan amalmu yang ada padaku. Lalu dikatakan kepada malaikat Malik:",[["وَقَالَ","And (will) say"],["قَرِينُهُۥ","his companion"],["هَـٰذَا","This"],["مَا","(is) what"],["لَدَىَّ","(is) with me"],["عَتِيدٌ","ready"]]],"4654":["(\"Lemparkanlah olehmu ke dalam neraka Jahanam) maksudnya, lemparkanlah, atau cepat lemparkan. Menurut bacaan atau qiraat Imam Al-Hasan lafal Alqiyaa dibaca Alqiyan. Jadi asal kata lafal Alqiyaa adalah Alqiyan, kemudian huruf Nun Taukidnya diganti menjadi Alif sehingga jadilah Alqiyaa (semua orang yang ingkar dan keras kepala) maksudnya, membangkang terhadap perkara yang hak.",[["أَلْقِيَا","Throw"],["فِى","in (to)"],["جَهَنَّمَ","Hell"],["كُلَّ","every"],["كَفَّارٍ","disbeliever"],["عَنِيدٍۢ","stubborn"]]],"4655":["(Yang sangat menghalangi kebaikan) seperti perkara zakat (melanggar batas) yakni suka berbuat zalim (lagi ragu-ragu) ragu dalam agamanya.",[["مَّنَّاعٍۢ","Forbidder"],["لِّلْخَيْرِ","of good"],["مُعْتَدٍۢ","transgressor"],["مُّرِيبٍ","doubter"]]],"4656":["(Yang menjadikan tuhan lain di samping Allah) lafal ayat ini berkedudukan menjadi Mubtada yang mengandung makna Syarat, sedangkan Khabarnya ialah: (maka lemparkanlah dia ke dalam siksaan yang keras\") penafsiran lafal ayat ini sama dengan ayat yang semisal dengannya di atas tadi.",[["ٱلَّذِى","Who"],["جَعَلَ","made"],["مَعَ","with"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","a god"],["ءَاخَرَ","another"],["فَأَلْقِيَاهُ","so throw him"],["فِى","in(to)"],["ٱلْعَذَابِ","the punishment"],["ٱلشَّدِيدِ","the severe"]]],"4657":["(Yang menyertai dia berkata) yakni setannya mengatakan: (\"Ya Rabb kami! Aku tidak menyesatkannya) kami tidak membuatnya sesat (tetapi dialah yang berada dalam kesesatan yang jauh\") lalu kami mengajaknya dan ternyata ia memenuhi ajakanku. Sedangkan dia menjawab, \"Setanlah yang menyesatkan aku\", yaitu melalui ajakannya.",[["۞ قَالَ","Will say"],["قَرِينُهُۥ","his companion"],["رَبَّنَا","Our Lord"],["مَآ","not"],["أَطْغَيْتُهُۥ","I made him transgress"],["وَلَـٰكِن","but"],["كَانَ","he was"],["فِى","in"],["ضَلَـٰلٍۭ","error"],["بَعِيدٍۢ","far"]]],"4658":["(Allah berfirman,) Maha Tinggi Dia (\"Janganlah kalian bertengkar di hadapan-Ku) maksudnya, tiada gunanya pertengkaran kalian di sini (padahal sesungguhnya Aku dahulu telah memberikan kepada kalian) sewaktu kalian hidup di dunia (ancaman) akan adanya azab di akhirat jika kalian tidak beriman, dan ini merupakan suatu kepastian yang tidak dapat dihindari lagi.",[["قَالَ","He will say"],["لَا","(Do) not"],["تَخْتَصِمُوا۟","dispute"],["لَدَىَّ","(in) My presence"],["وَقَدْ","and indeed"],["قَدَّمْتُ","I sent forth"],["إِلَيْكُم","to you"],["بِٱلْوَعِيدِ","the Warning"]]],"4659":["(Tidaklah dapat diganti) diubah (keputusan yang ada di sisi-Ku) mengenai hal tersebut (dan Aku sekali-kali tidak menganiaya hamba-hamba-Ku) yaitu dengan cara Aku mengazab mereka tanpa dosa; lafal Zhallaamin bermakna seperti lafal Dzuu Zhulmin yaitu menganiaya, demikian itu karena ada firman lainnya yang mengatakan, \"Tidak ada yang dianiaya pada hari ini.\" (Q.S. Al-Mukmin, 17)",[["مَا","Not"],["يُبَدَّلُ","will be changed"],["ٱلْقَوْلُ","the word"],["لَدَىَّ","with Me"],["وَمَآ","and not"],["أَنَا۠","I Am"],["بِظَلَّـٰمٍۢ","unjust"],["لِّلْعَبِيدِ","to My slaves"]]],"4660":["(Pada hari) lafal ini dinashabkan oleh lafal Zhallaamin (Kami bertanya) dapat dibaca Naquulu atau Yaquulu, kalau dibaca Yaquulu artinya, Allah bertanya (kepada neraka Jahanam, \"Apakah kamu sudah penuh?\") kata tanya di sini dimaksud mengecek ancaman-Nya yang menyatakan akan memenuhinya. (Dan dia menjawab, \"Masih adakah tambahan?\") maksudnya, kami tidak memuat melainkan hanya apa yang telah Engkau penuhkan kepada kami. Artinya kami telah penuh.",[["يَوْمَ","(The) Day"],["نَقُولُ","We will say"],["لِجَهَنَّمَ","to Hell"],["هَلِ","Are"],["ٱمْتَلَأْتِ","you filled"],["وَتَقُولُ","And it will say"],["هَلْ","Are"],["مِن","(there) any"],["مَّزِيدٍۢ","more"]]],"4661":["(Dan didekatkanlah surga itu) atau dijadikan dekat (kepada orang-orang yang bertakwa) surga itu didekatkan pada suatu tempat (yang tidak jauh) dari orang-orang yang bertakwa, sehingga mereka dapat melihatnya dengan jelas, kemudian dikatakan kepada mereka:",[["وَأُزْلِفَتِ","And will be brought near"],["ٱلْجَنَّةُ","the Paradise"],["لِلْمُتَّقِينَ","to the righteous"],["غَيْرَ","not"],["بَعِيدٍ","far"]]],"4662":["(Inilah) artinya, pemandangan yang dilihat ini (yang dijanjikan kepada kalian) dapat dibaca Tuu'aduuna atau Yuu'aduuna, kalau dibaca Yuu'aduuna artinya, yang dijanjikan kepada mereka sewaktu mereka di dunia. Kemudian lafal Al-Muttaqiina tadi dijelaskan melalui firman selanjutnya, yaitu: (kepada setiap hamba yang selalu kembali) yakni kembali kepada jalan ketaatan kepada Allah (lagi memelihara) batasan-batasan-Nya.",[["هَـٰذَا","This"],["مَا","(is) what"],["تُوعَدُونَ","you were promised"],["لِكُلِّ","for everyone"],["أَوَّابٍ","who turns"],["حَفِيظٍۢ","(and) who keeps"]]],"4663":["(Yaitu orang yang takut kepada Yang Maha Pemurah sedangkan Dia tidak kelihatan olehnya) sekalipun ia tidak melihat-Nya (dan dia datang dengan kalbu yang bertobat) yakni dengan kalbu yang taat kepada-Nya. Dan dikatakan pula kepada orang-orang yang bertakwa:",[["مَّنْ","Who"],["خَشِىَ","feared"],["ٱلرَّحْمَـٰنَ","the Most Gracious"],["بِٱلْغَيْبِ","in the unseen"],["وَجَآءَ","and came"],["بِقَلْبٍۢ","with a heart"],["مُّنِيبٍ","returning"]]],"4664":["(\"Masukilah surga itu dengan aman) artinya, dengan perasaan yang aman dari semua hal yang menakutkan. Atau dengan selamat, yakni selamatlah dan masuklah kalian ke dalamnya (itulah) yaitu hari sewaktu mereka memasuki surga itu (hari kekekalan\") artinya hidup abadi di dalam surga.",[["ٱدْخُلُوهَا","Enter it"],["بِسَلَـٰمٍۢ ۖ","in peace"],["ذَٰلِكَ","That"],["يَوْمُ","(is) a Day"],["ٱلْخُلُودِ","(of) Eternity"]]],"4665":["(Mereka di dalamnya memperoleh apa yang mereka kehendaki; dan pada sisi Kami ada tambahannya) yakni sebagai pahala tambahan dari apa yang telah kalian amalkan, dan sebagai tambahan dari apa yang telah kalian minta.",[["لَهُم","For them"],["مَّا","whatever"],["يَشَآءُونَ","they wish"],["فِيهَا","therein"],["وَلَدَيْنَا","and with Us"],["مَزِيدٌۭ","(is) more"]]],"4666":["(Dan berapa banyaknya umat-umat yang telah Kami binasakan sebelum mereka) sebelum orang-orang kafir Quraisy Kami telah membinasakan banyak umat yang kafir (yang mereka itu lebih besar kekuatannya daripada mereka ini) maksudnya umat-umat dahulu itu jauh lebih kuat daripada mereka (maka mereka telah pernah menjelajah) telah mengembara (di beberapa negeri. Adakah mereka mendapat tempat lari) dari kematian; yang dimaksud adalah mereka yang telah dibinasakan atau lainnya. Maka ternyata mereka tidak dapat menemukan jalan untuk melarikan diri dari kematian.",[["وَكَمْ","And how many"],["أَهْلَكْنَا","We destroyed"],["قَبْلَهُم","before them"],["مِّن","of"],["قَرْنٍ","a generation"],["هُمْ","they"],["أَشَدُّ","(were) stronger"],["مِنْهُم","than them"],["بَطْشًۭا","(in) power"],["فَنَقَّبُوا۟","so they explored"],["فِى","throughout"],["ٱلْبِلَـٰدِ","the lands"],["هَلْ","Is (there)"],["مِن","any"],["مَّحِيصٍ","place of escape"]]],"4667":["(Sesungguhnya pada yang demikian itu) pada hal-hal yang telah disebutkan itu (benar-benar terdapat peringatan) yakni pelajaran (bagi orang yang mempunyai akal) pikiran (atau yang menggunakan pendengarannya) artinya, mau mendengar nasihat (sedangkan dia menyaksikannya) maksudnya, hatinya hadir.",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَذِكْرَىٰ","surely, is a reminder"],["لِمَن","for (one) who"],["كَانَ","is "],["لَهُۥ","for him"],["قَلْبٌ","a heart"],["أَوْ","or"],["أَلْقَى","(who) gives ear"],["ٱلسَّمْعَ","(who) gives ear"],["وَهُوَ","while he"],["شَهِيدٌۭ","(is) a witness"]]],"4668":["(Dan sesungguhnya telah Kami ciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam hari) pada permulaannya adalah hari Ahad dan selesai pada hari Jumat (dan Kami sedikit pun tidak ditimpa keletihan) kepayahan. Ayat ini diturunkan sebagai sanggahan terhadap orang-orang Yahudi yang telah mengatakan bahwa Allah swt. pada hari Sabtu-Nya beristirahat. Ditiadakannya sifat lebih daripada-Nya karena memang Dia Maha Suci dari sifat-sifat yang dimiliki oleh makhluk-Nya, dan pula karena tiada kesamaan antara Allah dan selain-Nya. Di dalam ayat lain sehubungan dengan masalah penciptaan ini disebutkan melalui firman-Nya, \"Sesungguhnya keadaan-Nya apabila Dia menghendaki sesuatu hanyalah berkata kepadanya, 'Jadilah!' Maka terjadilah ia.\" (Q.S. Yaasin, 82)",[["وَلَقَدْ","And certainly"],["خَلَقْنَا","We created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between both of them"],["فِى","in"],["سِتَّةِ","six"],["أَيَّامٍۢ","periods"],["وَمَا","and (did) not"],["مَسَّنَا","touch Us"],["مِن","any"],["لُّغُوبٍۢ","fatigue"]]],"4669":["(Maka bersabarlah kamu) khithab pada ayat ini ditujukan kepada Nabi saw. (terhadap apa yang mereka katakan) yang dikatakan orang-orang Yahudi dan lainnya yang menyerupakan Allah dengan makhluk-Nya dan yang mendustakan kamu (dan bertasbihlah seraya memuji Rabbmu) yakni salatlah seraya memuji-Nya (sebelum terbit matahari) yakni salat Subuh (dan sebelum terbenamnya) yakni salat Zuhur dan salat Asar.",[["فَٱصْبِرْ","So be patient"],["عَلَىٰ","over"],["مَا","what"],["يَقُولُونَ","they say"],["وَسَبِّحْ","and glorify"],["بِحَمْدِ","(the) praise"],["رَبِّكَ","(of) your Lord"],["قَبْلَ","before"],["طُلُوعِ","(the) rising"],["ٱلشَّمْسِ","(of) the sun"],["وَقَبْلَ","and before"],["ٱلْغُرُوبِ","the setting"]]],"4670":["(Dan bertasbihlah kamu di malam hari) artinya lakukanlah kedua salat pada waktu permulaan malam hari (dan setiap selesai salat) kalau dibaca Adbaar berarti bentuk jamak dari lafal Duburun, sedangkan kalau dibaca Idbaar berarti Mashdar dari lafal Adbara. Artinya, lakukanlah salat tambahan yang disunahkan setiap selesai menjalankan salat fardu. Menurut suatu pendapat makna yang dimaksud adalah hakikat dari ucapan tasbih seraya memuji Allah yang dilakukan pada waktu-waktu tersebut.",[["وَمِنَ","And of"],["ٱلَّيْلِ","the night"],["فَسَبِّحْهُ","glorify Him"],["وَأَدْبَـٰرَ","and after"],["ٱلسُّجُودِ","the prostration"]]],"4671":["(Dan dengarkanlah) hai orang yang diajak bicara akan seruan-Ku ini (pada hari penyeru menyeru) yakni malaikat Israfil (dari tempat yang dekat) dari langit, yaitu dari atas Kubbah Shakhr di Baitulmakdis, karena tempat itu yang paling dekat dengan langit. Ia menyerukan kata-kata, \"Hai tulang-belulang yang telah hancur dan sendi-sendi yang telah bercerai-berai dan daging-daging yang telah tercabik-cabik dan rambut-rambut yang telah berantakan! Sesungguhnya Allah memerintahkan kalian semua untuk berhimpun guna melaksanakan peradilan.\"",[["وَٱسْتَمِعْ","And listen"],["يَوْمَ","(The) Day"],["يُنَادِ","will call"],["ٱلْمُنَادِ","the caller"],["مِن","from"],["مَّكَانٍۢ","a place"],["قَرِيبٍۢ","near"]]],"4672":["(Yaitu pada hari) menjadi Badal Isytimal dari lafal Yauma sebelumnya (mereka mendengar) maksudnya, ketika makhluk semuanya mendengar (teriakan dengan sebenar-benarnya) untuk membangkitkan makhluk semuanya, yaitu tiupan yang kedua dari malaikat Israfil. Dan teriakan ini adakalanya sesudah seruan itu atau sebelumnya (itulah) yakni hari seruan yang semua makhluk mendengarnya (hari keluar) dari kubur. Dan yang menashabkan lafal Yauma Yunaadi keberadaannya diperkirakan; lengkapnya: Mereka mengetahui akibat dari kedustaan mereka itu, pada hari penyeru menyerukan.",[["يَوْمَ","(The) Day"],["يَسْمَعُونَ","they will hear"],["ٱلصَّيْحَةَ","the Blast"],["بِٱلْحَقِّ ۚ","in truth"],["ذَٰلِكَ","That"],["يَوْمُ","(is the) Day"],["ٱلْخُرُوجِ","(of) coming forth"]]],"4673":["(Sesungguhnya Kami menghidupkan dan mematikan dan hanya kepada Kamilah tempat kembali -semua makhluk-.)",[["إِنَّا","Indeed, We"],["نَحْنُ","[We]"],["نُحْىِۦ","[We] give life"],["وَنُمِيتُ","and [We] cause death"],["وَإِلَيْنَا","and to Us"],["ٱلْمَصِيرُ","(is) the final return"]]],"4674":["(Yaitu pada hari) lafal Yauma pada ayat ini menjadi Badal atau pengganti dari lafal Yauma sebelumnya, sedangkan kalimat-kalimat yang menengah-nengahi di antara keduanya merupakan jumlah I'tiradh atau kalimat sisipan (terbelah-belah) dapat dibaca Tasyaqqaqu atau Tasysyaqqaqu, pada asalnya adalah Tatasyaqqaqu, lalu huruf Ta yang kedua diidgamkan kepada huruf Syin sehingga menjadi Tasysyaqqaqu (bumi menampakkan mereka dengan cepat) lafal Siraa'an adalah bentuk jamak dari lafal Sarii'un yang artinya cepat; berkedudukan menjadi Hal atau kata keterangan keadaan bagi lafal yang diperkirakan keberadaannya. Lengkapnya, mereka keluar dengan cepat dari kuburnya masing-masing. (Yang demikian itu adalah pengumpulan yang mudah bagi Kami) pada ayat ini terdapat Fashl atau pemisah yang memisahkan antara Maushuf dan Shifatnya, yang menjadi pemisah adalah Muta'alliqnya, hal ini mengandung makna Ikhtishash, dan hal seperti ini tidak mengapa. Demikian ini mengisyaratkan kepada pengertian pengumpulan yang dimaksud, yaitu menghidupkan kembali makhluk yang telah mati, dan pengumpulan ini dimaksud untuk menghadapkan semua makhluk ke hadapan-Nya guna menjalani hisab.",[["يَوْمَ","(The) Day"],["تَشَقَّقُ","will split"],["ٱلْأَرْضُ","the earth"],["عَنْهُمْ","from them"],["سِرَاعًۭا ۚ","hurrying"],["ذَٰلِكَ","That"],["حَشْرٌ","(is) a gathering"],["عَلَيْنَا","for Us"],["يَسِيرٌۭ","easy"]]],"4675":["(Kami lebih mengetahui tentang apa yang mereka katakan) yaitu yang dikatakan oleh orang-orang kafir Quraisy (dan kamu sekali-kali bukanlah seorang pemaksa terhadap mereka yang memaksa mereka untuk beriman, ayat ini diturunkan sebelum ada perintah berjihad. (Maka berilah peringatan dengan Alquran orang yang takut kepada ancaman-Ku) mereka adalah orang-orang mukmin.",[["نَّحْنُ","We"],["أَعْلَمُ","know best"],["بِمَا","[of] what"],["يَقُولُونَ ۖ","they say"],["وَمَآ","and not"],["أَنتَ","(are) you"],["عَلَيْهِم","over them"],["بِجَبَّارٍۢ ۖ","the one to compel"],["فَذَكِّرْ","But remind"],["بِٱلْقُرْءَانِ","with the Quran"],["مَن","whoever"],["يَخَافُ","fears"],["وَعِيدِ","My threat"]]],"4676":["(Demi yang menerbangkan debu) yakni angin dan lain-lainnya (dengan sekuat-kuatnya) adalah Mashdar, yang diambil dari kata: Tudzriihi Dzaryan, artinya angin itu menerbangkannya.",[["وَٱلذَّٰرِيَـٰتِ","By those scattering"],["ذَرْوًۭا","dispersing"]]],"4677":["(Dan demi awan yang mengandung) awan yang membawa air (hujan) yakni beban berupa air hujan, berkedudukan menjadi Maf'ul dari lafal Al Haamiaat.",[["فَٱلْحَـٰمِلَـٰتِ","And those carrying"],["وِقْرًۭا","a load"]]],"4678":["(Dan demi yang berlayar) yakni kapal-kapal yang berlayar di atas permukaan air (dengan mudah) dengan sangat mudahnya. Kalimat ini adalah Mashdar yang berkedudukan menjadi Hal, yakni Muyassaratan.",[["فَٱلْجَـٰرِيَـٰتِ","And those sailing"],["يُسْرًۭا","(with) ease"]]],"4679":["(Dan demi yang membagi-bagi urusan) demi malaikat-malaikat yang membagi-bagi rezeki, hujan dan lain-lainnya ke berbagai negeri dan kepada semua hamba-hamba Allah.",[["فَٱلْمُقَسِّمَـٰتِ","And those distributing"],["أَمْرًا","Command"]]],"4680":["(Sesungguhnya apa yang dijanjikan kepada kalian) huruf Maa pada lafal Innamaa adalah Mashdariyah; yakni janji Allah kepada mereka, yaitu tentang hari berbangkit dan lain-lainnya (pasti benar) artinya sungguh merupakan janji yang benar.",[["إِنَّمَا","Indeed, what"],["تُوعَدُونَ","you are promised"],["لَصَادِقٌۭ","(is) surely true"]]],"4681":["(Dan Sesungguhnya pembalasan itu) yakni pembalasan sesudah hisab (pasti terjadi) pasti akan terjadi.",[["وَإِنَّ","And indeed"],["ٱلدِّينَ","the Judgment"],["لَوَٰقِعٌۭ","(is) surely to occur"]]],"4682":["(Demi langit yang mempunyai jalan-jalan) lafal Al Hubuk adalah bentuk jamak dari Habiikah, sama halnya dengan lafal Thariiqah yang bentuk jamaknya Thuruq, yakni sejak ia diciptakan mempunyai jalan-jalan, sebagaimana jalan di padang pasir.",[["وَٱلسَّمَآءِ","By the heaven"],["ذَاتِ","full of"],["ٱلْحُبُكِ","pathways"]]],"4683":["(Sesungguhnya kalian) hai penduduk Mekah terhadap Nabi saw. dan Alquran (benar-benar dalam keadaan berbeda-beda pendapat) terkadang mengatakannya sebagai penyair, dan terkadang penyihir, dan terkadang peramal, dan terhadap Alquran terkadang mereka mengatakannya sebagai syair; terkadang sebagai sihir dan terkadang dianggap sebagai ramalan.",[["إِنَّكُمْ","Indeed, you"],["لَفِى","(are) surely in"],["قَوْلٍۢ","a speech"],["مُّخْتَلِفٍۢ","differing"]]],"4684":["(Dipalingkan) dijauhkan (daripadanya) dari Nabi saw. dan Alquran; maksudnya dipalingkan dari beriman kepadanya (orang yang dipalingkan) dari jalan petunjuk, menurut ilmu Allah swt.",[["يُؤْفَكُ","Deluded away"],["عَنْهُ","from it"],["مَنْ","(is he) who"],["أُفِكَ","is deluded"]]],"4685":["(Terkutuklah orang-orang yang banyak berdusta) amat terkutuklah orang-orang yang berdusta, yaitu orang-orang yang mempunyai pendapat yang berbeda-beda.",[["قُتِلَ","Cursed be"],["ٱلْخَرَّٰصُونَ","the liars"]]],"4686":["(Yaitu orang-orang yang terbenam di dalam kebodohannya) di dalam kebodohan yang menutupi akal mereka (lagi lalai) akan perkara akhirat.",[["ٱلَّذِينَ","Those who"],["هُمْ","[they]"],["فِى","(are) in"],["غَمْرَةٍۢ","flood"],["سَاهُونَ","(of) heedlessness"]]],"4687":["(Mereka bertanya) kepada nabi dengan nada memperolok-olokkan, (\"Bilakah hari pembalasan?\") kapan datangnya hari pembalasan itu. Jawaban yang patut buat mereka ialah, \"Memang Kiamat pasti datang,",[["يَسْـَٔلُونَ","They ask"],["أَيَّانَ","When"],["يَوْمُ","(is the) Day"],["ٱلدِّينِ","(of) Judgment"]]],"4688":["(Yaitu pada hari ketika mereka di azab di dalam neraka\") yakni sewaktu mereka diazab di dalamnya, lalu dikatakan kepada mereka ketika mereka sedang diazab,",[["يَوْمَ","A Day"],["هُمْ","they"],["عَلَى","over"],["ٱلنَّارِ","the Fire"],["يُفْتَنُونَ","will be tried"]]],"4689":["(\"Rasakanlah azab kalian) siksaan kalian. (Inilah) azab (yang dahulu kalian minta supaya disegerakan\") di dunia dengan nada mengejek.",[["ذُوقُوا۟","Taste"],["فِتْنَتَكُمْ","your trial"],["هَـٰذَا","This"],["ٱلَّذِى","(is) what"],["كُنتُم","you were"],["بِهِۦ","for it"],["تَسْتَعْجِلُونَ","seeking to hasten"]]],"4690":["(Sesungguhnya orang-orang yang bertakwa berada di dalam surga) di taman-taman surga (dan di mata air-mata air) yang mengalir di dalam surga.",[["إِنَّ","Indeed"],["ٱلْمُتَّقِينَ","the righteous"],["فِى","(will be) in"],["جَنَّـٰتٍۢ","Gardens"],["وَعُيُونٍ","and springs"]]],"4691":["(Sambil mengambil) menjadi Hal dari Dhamir yang terkandung di dalam Khabarnya Inna (apa yang didatangkan kepada mereka) apa yang diberikan kepada mereka (oleh Rabb mereka) yaitu berupa pahala-pahala. (Sesungguhnya mereka sebelum itu) sebelum mereka masuk surga (adalah orang-orang yang berbuat baik) di dunia.",[["ءَاخِذِينَ","Taking"],["مَآ","what"],["ءَاتَىٰهُمْ","their Lord has given them"],["رَبُّهُمْ ۚ","their Lord has given them"],["إِنَّهُمْ","Indeed, they"],["كَانُوا۟","were"],["قَبْلَ","before"],["ذَٰلِكَ","that"],["مُحْسِنِينَ","good-doers"]]],"4692":["(Mereka sedikit sekali tidur di waktu malam) lafal Yahja'uuna artinya mereka tidur, dan lafal Maa adalah Zaidah, sedangkan lafal Yahja'uuna adalah Khabar dari Kaana, dan lafal Qaliilan adalah Zharaf. Yakni, mereka tidur di malam hari hanya sedikit, karena kebanyakan dipakai untuk salat.",[["كَانُوا۟","They used to"],["قَلِيلًۭا","little"],["مِّنَ","of"],["ٱلَّيْلِ","the night"],["مَا","[what]"],["يَهْجَعُونَ","sleep"]]],"4693":["(Dan di akhir-akhir malam mereka memohon ampun) mereka berdoa dengan mengucapkan, \"Allaahumaghfir Lanaa\", Ya Allah ampunilah kami.",[["وَبِٱلْأَسْحَارِ","And in the hours before dawn"],["هُمْ","they"],["يَسْتَغْفِرُونَ","would ask forgiveness"]]],"4694":["(Dan pada harta-harta mereka ada hak untuk orang miskin yang meminta dan orang miskin yang tidak meminta-minta) karena ia memelihara dirinya dari perbuatan itu.",[["وَفِىٓ","And in"],["أَمْوَٰلِهِمْ","their wealth"],["حَقٌّۭ","(was the) right"],["لِّلسَّآئِلِ","(of) those who asked"],["وَٱلْمَحْرُومِ","and the deprived"]]],"4695":["(Dan di bumi itu) yakni gunung-gunung, tanahnya, lautan, pohon-pohonan, buah-buahan, dan tumbuh-tumbuhannya serta lain-lainnya (terdapat tanda-tanda) yang menunjukkan akan kekuasaan Allah swt. dan keesaan-Nya (bagi orang-orang yang yakin).",[["وَفِى","And in"],["ٱلْأَرْضِ","the earth"],["ءَايَـٰتٌۭ","(are) signs"],["لِّلْمُوقِنِينَ","for those who are certain"]]],"4696":["(Dan juga pada diri kalian sendiri) terdapat pula tanda-tanda yang menunjukkan kekuasaan dan keesaan-Nya, yaitu mulai dari permulaan penciptaan kalian hingga akhirnya, dan di dalam susunan penciptaan kalian terkandung pula keajaiban-keajaiban. (Maka apakah kalian tidak memperhatikan?) akan hal tersebut yang karena itu lalu kalian dapat menyimpulkan akan Penciptanya dan kekuasaan-Nya yang Maha Besar.",[["وَفِىٓ","And in"],["أَنفُسِكُمْ ۚ","yourselves"],["أَفَلَا","Then will not"],["تُبْصِرُونَ","you see"]]],"4697":["(Dan di langit terdapat rezeki kalian) yaitu hujan yang menyebabkan tumbuhnya tumbuh-tumbuhan sebagai rezeki (dan terdapat pula apa yang dijanjikan kepada kalian) yakni tempat kembali, pahala, dan siksaan. Catatan mengenai hal tersebut terdapat di langit.",[["وَفِى","And in"],["ٱلسَّمَآءِ","the heaven"],["رِزْقُكُمْ","(is) your provision"],["وَمَا","and what"],["تُوعَدُونَ","you are promised"]]],"4698":["(Maka demi Rabb langit dan bumi, sesungguhnya ia) yakni apa yang dijanjikan kepada kalian (adalah benar seperti perkataan yang kalian ucapkan) di-rafa-kannya lafal Mitslu karena menjadi sifat, sedangkan huruf Maa yang sesudahnya adalah Zaidah. Bila dibaca Mitsla maka tulisannya disatukan dengan Maa. Maknanya, kenyataannya seperti perkataan yang kalian ucapkan, yakni pengetahuan mengenai hal itu sudah dimaklumi oleh kalian, dan hal itu justru timbul dari diri kalian sendiri.",[["فَوَرَبِّ","Then by (the) Lord"],["ٱلسَّمَآءِ","(of) the heaven"],["وَٱلْأَرْضِ","and the earth"],["إِنَّهُۥ","indeed, it"],["لَحَقٌّۭ","(is) surely (the) truth"],["مِّثْلَ","(just) as"],["مَآ","[what]"],["أَنَّكُمْ","you"],["تَنطِقُونَ","speak"]]],"4699":["(Sudahkah sampai kepadamu) khithab ini ditujukan kepada Nabi saw. (cerita tamu Ibrahim yang dimuliakan) mereka adalah malaikat-malaikat yang jumlahnya ada dua belas atau sepuluh atau tiga malaikat; di antara mereka terdapat malaikat Jibril.",[["هَلْ","Has"],["أَتَىٰكَ","reached you"],["حَدِيثُ","(the) narration"],["ضَيْفِ","(of the) guests"],["إِبْرَٰهِيمَ","(of) Ibrahim"],["ٱلْمُكْرَمِينَ","the honored"]]],"4700":["(Ketika) lafal Idz di sini berkedudukan menjadi Zharaf bagi lafal Hadiitsu Dhaifi Ibraahiima (mereka masuk ke tempatnya lalu mengucapkan, \"Salaaman\") tamu-tamu itu mengucapkan perkataan tersebut. (Ibrahim menjawab, \"Salaamun\") menjawab dengan ucapan yang sama (mereka adalah orang-orang yang tidak dikenal) maksudnya, kami tidak mengenal mereka, Nabi Ibrahim mengatakan ucapan ini di dalam hatinya. Kalimat ini berkedudukan menjadi Khabar dari Mubtada yang keberadaannya diperkirakan, yaitu lafal Haa`ulaa`i yang artinya mereka.",[["إِذْ","When"],["دَخَلُوا۟","they entered"],["عَلَيْهِ","upon him"],["فَقَالُوا۟","and said"],["سَلَـٰمًۭا ۖ","Peace"],["قَالَ","He said"],["سَلَـٰمٌۭ","Peace"],["قَوْمٌۭ","a people"],["مُّنكَرُونَ","unknown"]]],"4701":["(Maka dia pergi) yakni ia beranjak dari situ (menemui keluarganya) dengan diam-diam (kemudian dibawanya daging anak sapi yang gemuk). Di dalam surah Hud telah disebutkan pula melalui firman-Nya, \"... dengan membawa daging anak sapi yang dipanggang.\" (Q.S. Hud, 69) yakni daging anak sapi gemuk itu sudah dipanggang.",[["فَرَاغَ","Then he went"],["إِلَىٰٓ","to"],["أَهْلِهِۦ","his household"],["فَجَآءَ","and came"],["بِعِجْلٍۢ","with a calf"],["سَمِينٍۢ","fat"]]],"4702":["(Lalu dihidangkannya kepada mereka. Ibrahim berkata, \"Silakan kalian makan\") Nabi Ibrahim mempersilakan mereka untuk makan, tetapi mereka tidak mau memakannya.",[["فَقَرَّبَهُۥٓ","And he placed it near"],["إِلَيْهِمْ","[to] them"],["قَالَ","he said"],["أَلَا","Will not"],["تَأْكُلُونَ","you eat"]]],"4703":["(Maka Ibrahim memendam) di dalam hatinya (rasa takut terhadap mereka. Mereka berkata, \"Janganlah kamu takut\") sesungguhnya kami adalah utusan-utusan Rabbmu (dan mereka memberi kabar gembira dengan kelahiran seorang anak yang alim) yakni anak yang mempunyai ilmu banyak yaitu, Nabi Ishak sebagaimana yang telah disebutkan di dalam surah Hud.",[["فَأَوْجَسَ","Then he felt"],["مِنْهُمْ","from them"],["خِيفَةًۭ ۖ","a fear"],["قَالُوا۟","They said"],["لَا","(Do) not"],["تَخَفْ ۖ","fear"],["وَبَشَّرُوهُ","and they gave him glad tidings"],["بِغُلَـٰمٍ","of a son"],["عَلِيمٍۢ","learned"]]],"4704":["(Kemudian istrinya datang) yakni Siti Sarah (seraya memekik) karena tercengang, berkedudukan menjadi Hal; yakni Siti Sarah datang seraya memekik karena kaget (lalu menepuk mukanya sendiri) menampar mukanya sendiri (seraya berkata, \"Aku adalah seorang perempuan tua yang mandul\") yang tidak dapat melahirkan anak sama sekali, pada saat itu umur Sarah mencapai sembilan puluh sembilan tahun, sedangkan Nabi Ibrahim seratus tahun; atau umur Nabi Ibrahim pada saat itu seratus dua puluh tahun, sedangkan umur Siti Sarah sembilan puluh tahun.",[["فَأَقْبَلَتِ","Then came forward"],["ٱمْرَأَتُهُۥ","his wife"],["فِى","with"],["صَرَّةٍۢ","a loud voice"],["فَصَكَّتْ","and struck"],["وَجْهَهَا","her face"],["وَقَالَتْ","and she said"],["عَجُوزٌ","An old woman"],["عَقِيمٌۭ","barren"]]],"4705":["(Mereka berkata, \"Demikianlah) sebagaimana perkataan kami tentang berita gembira ini (Rabbmu memfirmankan\". Sesungguhnya Dialah Yang Maha Bijaksana) di dalam perbuatan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["قَالُوا۟","They said"],["كَذَٰلِكِ","Thus"],["قَالَ","said"],["رَبُّكِ ۖ","your Lord"],["إِنَّهُۥ","Indeed, He"],["هُوَ","[He]"],["ٱلْحَكِيمُ","(is) the All-Wise"],["ٱلْعَلِيمُ","the All-Knower"]]]});